            let battleCrypto = 'BNB';
            let battleStake = 50;

            if (transaction.relatedId === 16) {
              // Battle ID 16: winner is 61 (OmegaHunter3714), challenger is 62 (EliteLegend3085)
              opponentName = 'EliteLegend3085';
              battleCrypto = 'binancecoin';
              battleStake = 50;
