              amount: transaction.amount,
              description: `Won Battle vs ${opponentName} - ${transaction.amount} NTIQ`,
              createdAt: transaction.createdAt,
              cryptocurrency: battleCrypto,
              isWin: true,
              stakeAmount: battleStake,
              rewardAmount: transaction.amount
