      console.log('✅ [WITHDRAWAL] Session found, userId:', session.userId);

      const withdrawalSchema = z.object({
        ntiqAmount: z.number().min(1),
        chainName: z.string().min(1),
        tokenType: z.enum(["ETH", "USDC", "USDT"]),
        toWalletAddress: z.string().min(1),
