import axios from 'axios';
import { pythPriceService } from './PythPriceService';

// Configure axios defaults for better Ubuntu localhost compatibility
axios.defaults.timeout = 10000;
axios.defaults.headers.common['User-Agent'] = 'Nectiq-Crypto-App/1.0';

// Disable proxy for localhost development
if (process.env.NODE_ENV === 'development') {
  delete process.env.https_proxy;
  delete process.env.http_proxy;
  delete process.env.HTTPS_PROXY;
  delete process.env.HTTP_PROXY;
}
import { storage } from '../storage';

export interface CryptoPrice {
  id: string;
  symbol: string;
  name: string;
  current_price: number;
  price_change_percentage_24h: number;
  image?: string;
  source?: 'coingecko' | 'pyth' | 'hybrid';
  confidence_interval?: number; // For Pyth Network confidence data
  last_updated?: string;
}

const COINGECKO_API_BASE = 'https://api.coingecko.com/api/v3';

export class CryptoService {
  private lastFetchTime = 0;
  private cachedRealPrices: CryptoPrice[] = [];
  private readonly CACHE_DURATION = 10000; // Cache real prices for 10 seconds for better real-time experience
  private fetchPromise: Promise<CryptoPrice[]> | null = null; // Prevent concurrent fetches
  private priceVariationTime = 0; // Consistent variation time for all users
  private pythEnabled = true; // Enable Pyth Network integration

  // Method to clear cache when cryptocurrencies are deleted
  clearCache() {
    this.lastFetchTime = 0;
    this.cachedRealPrices = [];
    this.fetchPromise = null;
    console.log("🔄 [CRYPTO] Cache cleared - fresh data will be fetched on next request");
  }

  // Generate micro-variations on cached data when rate limited
  private generateMicroVariations() {
    if (this.cachedRealPrices.length > 0) {
      // Use a seed based on current time to ensure all users get the same variation
      const seed = Math.floor(Date.now() / 3000) * 3000; // Round to 3-second intervals
      const variation = Math.sin(seed / 10000) * 0.003; // Consistent variation for all users

      this.cachedRealPrices = this.cachedRealPrices.map(crypto => ({
        ...crypto,
        current_price: crypto.current_price * (1 + variation),
        price_change_percentage_24h: crypto.price_change_percentage_24h + variation * 10
      }));
      console.log(`🔄 Generated synchronized micro-variations: ${(variation * 100).toFixed(4)}% for all users`);
    }
  }

  private async fetchFreshPrices(): Promise<CryptoPrice[]> {
    const now = Date.now();

    try {
      // PYTH-ONLY APPROACH: Get Pyth Network prices directly
      console.log('📡 [PYTH-ONLY] Fetching prices from Pyth Network exclusively');
      const pythPrices = await pythPriceService.getLatestPrices();

      if (pythPrices.length === 0) {
        console.log('⚠️ [PYTH-ONLY] No Pyth prices available');
        this.cachedRealPrices = [];
        this.lastFetchTime = now;
        this.fetchPromise = null;
        return [];
      }

      // Convert Pyth prices to CryptoPrice format using image directly from database
      const realPrices: CryptoPrice[] = pythPrices.map((pythPrice) => ({
        id: pythPrice.id,
        symbol: pythPrice.symbol,
        name: pythPrice.name,
        current_price: pythPrice.current_price,
        price_change_percentage_24h: pythPrice.price_change_percentage_24h || 0, // Default to 0 if not available
        image: pythPrice.image, // Use image directly from database (via PythPriceService)
        source: 'pyth' as const,
        confidence_interval: pythPrice.confidence_interval,
        last_updated: pythPrice.last_updated || new Date().toISOString()
      }));

      console.log(`✅ [PYTH-ONLY] Successfully fetched ${realPrices.length} prices from Pyth Network`);

      this.cachedRealPrices = realPrices;
      this.lastFetchTime = now;
      this.fetchPromise = null;

      return realPrices;
    } catch (error: any) {
      console.error('❌ [PYTH-ONLY] Error fetching Pyth prices:', error.message);

      // Try using cached data if available
      if (this.cachedRealPrices.length > 0) {
        console.log('📦 [PYTH-ONLY] Using cached data due to fetch failure');
        this.generateMicroVariations();
        return this.cachedRealPrices;
      }

      this.fetchPromise = null;
      throw error;
    }
  }

  /**
   * Fetch prices using hybrid approach: Pyth Network + CoinGecko fallback
   */
  private async fetchHybridPrices(): Promise<CryptoPrice[]> {
    const now = Date.now();
    console.log('🔗 [HYBRID] Starting hybrid price fetch (Pyth + CoinGecko)');

    try {
      // Get supported cryptocurrencies from database
      const supportedCryptos = await storage.getAllCryptocurrencies();
      const cryptoIds = supportedCryptos.map(crypto => crypto.id);

      if (cryptoIds.length === 0) {
        this.cachedRealPrices = [];
        this.lastFetchTime = now;
        return [];
      }

      let pythPrices: CryptoPrice[] = [];
      let coinGeckoPrices: CryptoPrice[] = [];

      // Try to fetch from Pyth Network first
      try {
        console.log('📡 [PYTH] Attempting to fetch prices from Pyth Network...');
        pythPrices = await pythPriceService.getLatestPrices();
        console.log(`✅ [PYTH] Successfully fetched ${pythPrices.length} prices from Pyth Network`);
      } catch (pythError: any) {
        console.warn('⚠️ [PYTH] Failed to fetch from Pyth Network:', pythError?.message || 'Unknown error');
      }

      // Fetch from CoinGecko for comparison and fallback
      try {
        console.log('🦎 [COINGECKO] Fetching prices from CoinGecko API...');
        const response = await axios.get(`${COINGECKO_API_BASE}/coins/markets`, {
          params: {
            ids: cryptoIds.join(','),
            vs_currency: 'usd',
            order: 'market_cap_desc',
            per_page: 20,
            page: 1,
            sparkline: false,
            price_change_percentage: '24h'
          }
        });

        coinGeckoPrices = response.data.map((coin: any) => ({
          id: coin.id,
          symbol: coin.symbol?.toUpperCase(),
          name: coin.name,
          current_price: coin.current_price,
          price_change_percentage_24h: coin.price_change_percentage_24h,
          image: coin.image || `https://coin-images.coingecko.com/coins/images/1/large/${coin.id}.png`,
          source: 'coingecko',
          last_updated: coin.last_updated
        }));
        console.log(`✅ [COINGECKO] Successfully fetched ${coinGeckoPrices.length} prices from CoinGecko`);
      } catch (coinGeckoError: any) {
        if (coinGeckoError.response?.status === 429) {
          console.log('⏳ [COINGECKO] Rate limit reached');
        } else {
          console.warn('⚠️ [COINGECKO] Failed to fetch from CoinGecko:', coinGeckoError.message);
        }
      }

      // Merge prices: Prefer Pyth for supported cryptos, fallback to CoinGecko
      const mergedPrices = this.mergeHybridPrices(pythPrices, coinGeckoPrices, cryptoIds);

      this.cachedRealPrices = mergedPrices;
      this.lastFetchTime = now;

      console.log(`🔄 [HYBRID] Hybrid fetch completed: ${mergedPrices.length} total prices`);
      return this.getMergedPriceData();

    } catch (error: any) {
      console.error('❌ [HYBRID] Error in hybrid price fetch:', error);
      this.fetchPromise = null;

      if (error.response?.status === 429) {
        console.log('⏳ [HYBRID] Rate limit reached, using micro-variations on cached data');
        this.generateMicroVariations();
        this.lastFetchTime = now + 10000;
      }

      return this.getMergedPriceData();
    }
  }

  /**
   * Merge Pyth and CoinGecko prices intelligently
   */
  private mergeHybridPrices(pythPrices: CryptoPrice[], coinGeckoPrices: CryptoPrice[], cryptoIds: string[]): CryptoPrice[] {
    const mergedPrices: CryptoPrice[] = [];
    const pythMap = new Map(pythPrices.map(p => [p.id, p]));
    const coinGeckoMap = new Map(coinGeckoPrices.map(p => [p.id, p]));

    console.log(`🔄 [MERGE] Merging prices: ${pythPrices.length} from Pyth, ${coinGeckoPrices.length} from CoinGecko`);

    for (const cryptoId of cryptoIds) {
      const pythPrice = pythMap.get(cryptoId);
      const coinGeckoPrice = coinGeckoMap.get(cryptoId);

      if (pythPrice && coinGeckoPrice) {
        // Both sources available - prefer Pyth but add market data from CoinGecko
        const hybridPrice: CryptoPrice = {
          ...pythPrice,
          // Keep Pyth's institutional price
          current_price: pythPrice.current_price,
          // Use CoinGecko's 24h change since Pyth doesn't provide this directly
          price_change_percentage_24h: coinGeckoPrice.price_change_percentage_24h,
          // Use CoinGecko's image if available
          image: coinGeckoPrice.image || pythPrice.image,
          source: 'hybrid',
          confidence_interval: pythPrice.confidence_interval
        };
        mergedPrices.push(hybridPrice);
        console.log(`🤝 [${cryptoId.toUpperCase()}] Hybrid: Pyth price ($${pythPrice.current_price.toFixed(4)}) + CoinGecko market data`);

      } else if (pythPrice) {
        // Only Pyth available
        mergedPrices.push({
          ...pythPrice,
          source: 'pyth'
        });
        console.log(`📡 [${cryptoId.toUpperCase()}] Pyth only: $${pythPrice.current_price.toFixed(4)}`);

      } else if (coinGeckoPrice) {
        // Only CoinGecko available
        mergedPrices.push({
          ...coinGeckoPrice,
          source: 'coingecko'
        });
        console.log(`🦎 [${cryptoId.toUpperCase()}] CoinGecko only: $${coinGeckoPrice.current_price.toFixed(4)}`);
      }
    }

    console.log(`✅ [MERGE] Merged ${mergedPrices.length} prices successfully`);
    return mergedPrices;
  }

  async getCurrentPrices(): Promise<CryptoPrice[]> {
    const now = Date.now();

    // If there's already a fetch in progress, wait for it
    if (this.fetchPromise) {
      return this.fetchPromise;
    }

    // Try to fetch real prices every 45 seconds to avoid rate limits while keeping prices current
    if (now - this.lastFetchTime > this.CACHE_DURATION) {
      // Create and store the fetch promise to prevent concurrent fetches
      this.fetchPromise = this.fetchFreshPrices(); // Pyth-only approach
      return this.fetchPromise;
    }

    // Return cached Pyth data
    return this.cachedRealPrices;
  }

  private async getMergedPriceData(): Promise<CryptoPrice[]> {
    // Get database cryptocurrencies and merge with CoinGecko data
    let allPrices: CryptoPrice[] = [];

    try {
      // Get all cryptocurrencies from database
      const dbCryptos = await storage.getAllCryptocurrencies();

      // Convert database cryptos to CryptoPrice format with database image URLs
      const dbPrices: CryptoPrice[] = dbCryptos.map(crypto => ({
        id: crypto.id,
        symbol: crypto.symbol,
        name: crypto.name,
        current_price: parseFloat(crypto.currentPrice || '0'),
        price_change_percentage_24h: parseFloat(crypto.priceChange24h || '0'),
        image: crypto.image || undefined
      }));

      // If we have real cached prices from CoinGecko, merge them
      if (this.cachedRealPrices.length > 0) {
        // Create a map of CoinGecko prices for easier lookup
        const coinGeckoMap = new Map(this.cachedRealPrices.map(p => [p.id, p]));

        // Start with database prices
        allPrices = [...dbPrices];

        // Update with CoinGecko prices where available, adding synchronized real-time variation
        // Use time rounded to 3-second intervals so all users see identical prices
        const syncTime = Math.floor(Date.now() / 3000) * 3000;
        const fastVariation = Math.sin(syncTime / 2000) * 0.002; // Synchronized fluctuations
        const slowVariation = Math.cos(syncTime / 5000) * 0.001; // Synchronized background movement
        const microVariation = fastVariation + slowVariation;
        console.log(`🔄 [SYNCHRONIZED] Applied ${(microVariation * 100).toFixed(4)}% variation to prices (sync time: ${syncTime})`);

        allPrices = allPrices.map(dbPrice => {
          const coinGeckoPrice = coinGeckoMap.get(dbPrice.id);
          if (coinGeckoPrice) {
            // Use CoinGecko data but add micro-variations for live feeling
            const newPrice = coinGeckoPrice.current_price * (1 + microVariation);
            if (dbPrice.id === 'bitcoin') {
              console.log(`🟠 [BTC] Original: $${coinGeckoPrice.current_price.toFixed(2)}, With variation: $${newPrice.toFixed(2)}`);
            }
            return {
              ...coinGeckoPrice,
              current_price: newPrice,
              image: dbPrice.image
            };
          }
          return dbPrice;
        });

        // Add any CoinGecko prices that aren't in database yet
        for (const cgPrice of this.cachedRealPrices) {
          const existsInDb = allPrices.find(p => p.id === cgPrice.id);
          if (!existsInDb) {
            allPrices.push({
              ...cgPrice,
              current_price: cgPrice.current_price * (1 + microVariation),
              image: cgPrice.image
            });
          }
        }
      } else {
        // Use database prices with real-time variations
        const now = Date.now();
        const fastVariation = Math.sin(now / 2500) * 0.003; // Even faster variations when no fresh data
        const slowVariation = Math.cos(now / 7000) * 0.0015;
        const microVariation = fastVariation + slowVariation;

        allPrices = dbPrices.map(price => ({
          ...price,
          current_price: price.current_price * (1 + microVariation)
        }));
      }
    } catch (error) {
      console.error('Error merging price data:', error);
      // Return cached real prices or fallback if no DB data available
      allPrices = this.cachedRealPrices.length > 0 ? this.cachedRealPrices : this.getFallbackPrices();
    }

    // If no data available from any source, use fallback
    if (allPrices.length === 0) {
      allPrices = this.getFallbackPrices();
    }

    return allPrices;
  }

  async getCryptoPrice(coinId: string): Promise<number> {
    try {
      const prices = await this.getCurrentPrices();
      const crypto = prices.find(p => p.id === coinId || p.symbol.toLowerCase() === coinId.toLowerCase());
      return crypto ? crypto.current_price : 0;
    } catch (error) {
      console.error(`Error getting price for ${coinId}:`, error);
      return 0;
    }
  }

  async getCryptoMetrics(coinId: string): Promise<any> {
    try {
      const response = await axios.get(`${COINGECKO_API_BASE}/coins/${coinId}`, {
        params: {
          localization: false,
          tickers: false,
          market_data: true,
          community_data: false,
          developer_data: false,
          sparkline: false
        },
        timeout: 10000,
        headers: {
          'User-Agent': 'Nectiq-Crypto-App/1.0'
        },
        proxy: false
      });

      const coin = response.data;
      return {
        id: coin.id,
        symbol: coin.symbol?.toUpperCase() || '',
        name: coin.name || '',
        current_price: coin.market_data?.current_price?.usd || 0,
        market_cap: coin.market_data?.market_cap?.usd || 0,
        total_volume: coin.market_data?.total_volume?.usd || 0,
        circulating_supply: coin.market_data?.circulating_supply || 0,
        total_supply: coin.market_data?.total_supply || 0,
        max_supply: coin.market_data?.max_supply || 0,
        price_change_percentage_24h: coin.market_data?.price_change_percentage_24h || 0,
        volume_24h: coin.market_data?.total_volume?.usd || 0,
        volume_30d_estimate: (coin.market_data?.total_volume?.usd || 0) * 30,
        image: coin.image || `https://coin-images.coingecko.com/coins/images/1/large/${coin.id}.png`
      };
    } catch (error) {
      console.error(`Error fetching metrics for ${coinId}:`, error);
      return this.getFallbackMetrics(coinId);
    }
  }

  private getFallbackMetrics(coinId: string): any {
    const prices = this.getFallbackPrices();
    const crypto = prices.find(p => p.id === coinId);

    if (!crypto) {
      return {
        id: coinId,
        symbol: coinId.toUpperCase(),
        name: this.getNameFromId(coinId),
        current_price: 0,
        market_cap: 0,
        total_volume: 0,
        circulating_supply: 0,
        total_supply: 0,
        max_supply: 0,
        price_change_percentage_24h: 0,
        volume_24h: 0,
        volume_30d_estimate: 0,
        image: `https://coin-images.coingecko.com/coins/images/1/large/${coinId}.png`
      };
    }

    return {
      id: crypto.id,
      symbol: crypto.symbol,
      name: crypto.name,
      current_price: crypto.current_price,
      market_cap: crypto.current_price * 19000000,
      total_volume: crypto.current_price * 500000,
      circulating_supply: 19000000,
      total_supply: 21000000,
      max_supply: 21000000,
      price_change_percentage_24h: crypto.price_change_percentage_24h,
      volume_24h: crypto.current_price * 500000,
      volume_30d_estimate: crypto.current_price * 500000 * 30,
      image: crypto.image
    };
  }

  private getSymbolFromId(id: string): string {
    const mapping: { [key: string]: string } = {
      'bitcoin': 'BTC',
      'ethereum': 'ETH',
      'binancecoin': 'BNB',
      'cardano': 'ADA',
      'solana': 'SOL',
      'chainlink': 'LINK',
      'polkadot': 'DOT',
      'litecoin': 'LTC',
      'matic-network': 'MATIC',
      'hyperliquid': 'HYPE',
      'avalanche-2': 'AVAX',
      'stellar': 'XLM',
      'tron': 'TRX',
      'sui': 'SUI',
      'sahara': 'SAHARA'
    };
    return mapping[id] || id.toUpperCase();
  }

  private getNameFromId(id: string): string {
    const mapping: { [key: string]: string } = {
      'bitcoin': 'Bitcoin',
      'ethereum': 'Ethereum',
      'binancecoin': 'Binance Coin',
      'cardano': 'Cardano',
      'solana': 'Solana',
      'chainlink': 'Chainlink',
      'polkadot': 'Polkadot',
      'litecoin': 'Litecoin',
      'matic-network': 'Polygon',
      'hyperliquid': 'Hyperliquid',
      'avalanche-2': 'Avalanche',
      'stellar': 'Stellar',
      'tron': 'TRON',
      'sui': 'Sui',
      'sahara': 'Sahara AI'
    };
    return mapping[id] || id;
  }



  private getFallbackPrices(): CryptoPrice[] {
    const now = Date.now();
    // Create more realistic price movement with faster changes
    const timeVariation = Math.sin(now / 10000) * 0.02 + Math.cos(now / 15000) * 0.015; // Faster oscillation
    const microVariation = (Math.random() - 0.5) * 0.005; // Slightly larger random fluctuation for noticeable changes

    // Updated with more current cryptocurrency prices (June 2025)
    return [
      {
        id: 'bitcoin',
        symbol: 'BTC',
        name: 'Bitcoin',
        current_price: 67500 + (timeVariation * 500) + (microVariation * 67500),
        price_change_percentage_24h: 1.85 + (timeVariation * 0.5),
        image: 'https://coin-images.coingecko.com/coins/images/1/large/bitcoin.png'
      },
      {
        id: 'ethereum',
        symbol: 'ETH',
        name: 'Ethereum',
        current_price: 3850 + (timeVariation * 80) + (microVariation * 3850),
        price_change_percentage_24h: -0.75 + (timeVariation * 0.4),
        image: 'https://coin-images.coingecko.com/coins/images/279/large/ethereum.png'
      },
      {
        id: 'binancecoin',
        symbol: 'BNB',
        name: 'Binance Coin',
        current_price: 615 + (timeVariation * 12) + (microVariation * 615),
        price_change_percentage_24h: 0.65 + (timeVariation * 0.3),
        image: 'https://coin-images.coingecko.com/coins/images/825/large/bnb-icon2_2x.png'
      },
      {
        id: 'cardano',
        symbol: 'ADA',
        name: 'Cardano',
        current_price: 0.55 + (timeVariation * 0.02) + (microVariation * 0.55),
        price_change_percentage_24h: -1.2 + (timeVariation * 0.2),
        image: 'https://coin-images.coingecko.com/coins/images/975/large/cardano.png'
      },
      {
        id: 'solana',
        symbol: 'SOL',
        name: 'Solana',
        current_price: 185 + (timeVariation * 8) + (microVariation * 185),
        price_change_percentage_24h: 2.1 + (timeVariation * 0.6),
        image: '/attached_assets/solana_1750613756851.png'
      }
    ];
  }
}

