import { db } from "../db";
import { 
  dailyChallenges, 
  userDailyChallenges, 
  type DailyChallenge,
  type UserDailyChallenge,
  type InsertDailyChallenge,
  type InsertUserDailyChallenge 
} from "@shared/schema";
import { eq, and } from "drizzle-orm";
import { storage } from "../storage";
import { BalanceService } from "./balanceService";

export class DailyChallengeService {
  // Generate daily challenges for today
  async generateDailyChallenges(): Promise<DailyChallenge[]> {
    const today = new Date().toISOString().split('T')[0]; // YYYY-MM-DD format

    // Check if challenges already exist for today
    const existingChallenges = await db
      .select()
      .from(dailyChallenges)
      .where(and(
        eq(dailyChallenges.date, today),
        eq(dailyChallenges.isActive, true)
      ));

    if (existingChallenges.length > 0) {
      return existingChallenges;
    }

    // Generate new challenges for today
    const challengeTemplates = [
      {
        name: "Daily Predictor",
        description: "Make 3 predictions today",
        type: "make_predictions",
        target: 3,
        reward: 200
      },
      {
        name: "Accuracy Champion",
        description: "Achieve 70% accuracy on predictions today",
        type: "accuracy_target",
        target: 70,
        reward: 300
      },
      {
        name: "High Roller",
        description: "Make a prediction with 500+ NTIQ stake",
        type: "high_stake",
        target: 500,
        reward: 400
      },
      {
        name: "Crypto Explorer",
        description: "Make predictions on 2 different cryptocurrencies",
        type: "diverse_predictions",
        target: 2,
        reward: 250
      }
    ];

    // Randomly select 2-3 challenges for today
    const selectedChallenges = challengeTemplates
      .sort(() => 0.5 - Math.random())
      .slice(0, Math.floor(Math.random() * 2) + 2);

    const newChallenges: DailyChallenge[] = [];

    for (const template of selectedChallenges) {
      const [challenge] = await db
        .insert(dailyChallenges)
        .values({
          ...template,
          date: today,
          isActive: true
        })
        .returning();

      newChallenges.push(challenge);
    }

    return newChallenges;
  }

  // Get today's challenges for a user
  async getUserTodayChallenges(userId: number): Promise<(UserDailyChallenge & { challenge: DailyChallenge })[]> {
    const today = new Date().toISOString().split('T')[0];

    // Ensure challenges exist for today
    await this.generateDailyChallenges();

    const todayChallenges = await db
      .select()
      .from(dailyChallenges)
      .where(and(
        eq(dailyChallenges.date, today),
        eq(dailyChallenges.isActive, true)
      ));

    const userChallenges = [];

    for (const challenge of todayChallenges) {
      let userChallenge = await db
        .select()
        .from(userDailyChallenges)
        .where(and(
          eq(userDailyChallenges.userId, userId),
          eq(userDailyChallenges.challengeId, challenge.id),
          eq(userDailyChallenges.date, today)
        ))
        .limit(1);

      if (userChallenge.length === 0) {
        // Create new user challenge tracking
        const [newUserChallenge] = await db
          .insert(userDailyChallenges)
          .values({
            userId,
            challengeId: challenge.id,
            progress: 0,
            isCompleted: false,
            date: today
          })
          .returning();

        userChallenges.push({
          ...newUserChallenge,
          challenge
        });
      } else {
        userChallenges.push({
          ...userChallenge[0],
          challenge
        });
      }
    }

    return userChallenges;
  }

  // Update challenge progress for a user
  async updateChallengeProgress(userId: number): Promise<UserDailyChallenge[]> {
    const today = new Date().toISOString().split('T')[0];
    const completedChallenges: UserDailyChallenge[] = [];

    const userChallenges = await this.getUserTodayChallenges(userId);

    for (const userChallenge of userChallenges) {
      if (userChallenge.isCompleted) continue;

      const progress = await this.calculateChallengeProgress(userId, userChallenge.challenge, today);
      const isCompleted = progress >= userChallenge.challenge.target;

      const [updated] = await db
        .update(userDailyChallenges)
        .set({
          progress,
          isCompleted,
          completedAt: isCompleted ? new Date() : userChallenge.completedAt
        })
        .where(eq(userDailyChallenges.id, userChallenge.id))
        .returning();

      if (isCompleted && !userChallenge.isCompleted) {
        // CRITICAL FIX: Use BalanceService for daily challenge rewards
        const balanceResult = await BalanceService.processTransaction({
          userId,
          type: 'daily_challenge_reward',
          amount: userChallenge.challenge.reward,
          description: `Daily challenge reward: ${userChallenge.challenge.name}`,
          relatedId: userChallenge.challengeId
        }, storage);

        console.log(`✅ Awarded ${userChallenge.challenge.reward} NTIQ to user ${userId} for daily challenge: ${userChallenge.challenge.name}`);
        completedChallenges.push(updated);
      }
    }

    return completedChallenges;
  }

  // Calculate progress for different challenge types
  private async calculateChallengeProgress(userId: number, challenge: DailyChallenge, date: string): Promise<number> {
    const predictions = await storage.getUserPredictions(userId);
    const todayPredictions = predictions.filter(p => 
      p.createdAt.toISOString().split('T')[0] === date
    );

    switch (challenge.type) {
      case 'make_predictions':
        return todayPredictions.length;

      case 'accuracy_target':
        if (todayPredictions.length === 0) return 0;
        const completedToday = todayPredictions.filter(p => p.status === 'completed');
        if (completedToday.length === 0) return 0;

        const correctToday = completedToday.filter(p => p.accuracy !== null && parseFloat(p.accuracy) >= 90);
        return Math.round((correctToday.length / completedToday.length) * 100);

      case 'high_stake':
        const maxStakeToday = Math.max(...todayPredictions.map(p => p.stakeAmount), 0);
        return maxStakeToday >= challenge.target ? challenge.target : maxStakeToday;

      case 'diverse_predictions':
        const uniqueCryptos = new Set(todayPredictions.map(p => p.cryptocurrency));
        return uniqueCryptos.size;

      default:
        return 0;
    }
  }

  // Get user's challenge history
  async getUserChallengeHistory(userId: number, limit: number = 7): Promise<(UserDailyChallenge & { challenge: DailyChallenge })[]> {
    return await db
      .select({
        id: userDailyChallenges.id,
        userId: userDailyChallenges.userId,
        challengeId: userDailyChallenges.challengeId,
        progress: userDailyChallenges.progress,
        isCompleted: userDailyChallenges.isCompleted,
        completedAt: userDailyChallenges.completedAt,
        date: userDailyChallenges.date,
        createdAt: userDailyChallenges.createdAt,
        challenge: dailyChallenges,
      })
      .from(userDailyChallenges)
      .innerJoin(dailyChallenges, eq(userDailyChallenges.challengeId, dailyChallenges.id))
      .where(eq(userDailyChallenges.userId, userId))
      .orderBy(userDailyChallenges.date)
      .limit(limit);
  }
}

export const dailyChallengeService = new DailyChallengeService();

server/services/deposit-expiry-service.t.content:
/**
 * Deposit Expiry Monitoring Service
 * 
 * This service monitors pending deposits and automatically cancels them
 * if they are not completed within the 1-hour expiration period.
 * 
 * Features:
 * - Automatic monitoring every 5 minutes
 * - Cancels expired pending deposits
 * - Comprehensive logging for audit trail
 * - Email notifications (future enhancement)
 */

import { IStorage } from '../storage';

interface DepositExpiryStats {
  expiredDeposits: number;
  cancelledDeposits: number;
  totalValue: number;
}

export class DepositExpiryService {
  private intervalId: NodeJS.Timeout | null = null;
  private isRunning: boolean = false;
  private storage: IStorage;

  constructor(storage: IStorage) {
    this.storage = storage;
  }

  /**
   * Start the deposit expiry monitoring service
   */
  public start(): void {
    if (this.isRunning) {
      console.log('⚠️ [DEPOSIT-EXPIRY] Service already running');
      return;
    }

    console.log('🚀 [DEPOSIT-EXPIRY] Starting deposit expiry monitoring service...');

    // Run immediately on startup
    this.checkExpiredDeposits();

    // Then run every 5 minutes (300,000 ms)
    this.intervalId = setInterval(() => {
      this.checkExpiredDeposits();
    }, 5 * 60 * 1000);

    this.isRunning = true;
    console.log('✅ [DEPOSIT-EXPIRY] Deposit expiry monitoring started - checking every 5 minutes');
  }

  /**
   * Stop the deposit expiry monitoring service
   */
  public stop(): void {
    if (this.intervalId) {
      clearInterval(this.intervalId);
      this.intervalId = null;
    }
    this.isRunning = false;
    console.log('🛑 [DEPOSIT-EXPIRY] Deposit expiry monitoring stopped');
  }

  /**
   * Check for expired deposits and cancel them
   */
  private async checkExpiredDeposits(): Promise<void> {
    try {
      console.log('🔍 [DEPOSIT-EXPIRY] Running expired deposit check...');

      const expiredDeposits = await this.storage.getExpiredDeposits();

      if (expiredDeposits.length === 0) {
        console.log('✅ [DEPOSIT-EXPIRY] No expired deposits found');
        return;
      }

      console.log(`🚨 [DEPOSIT-EXPIRY] Found ${expiredDeposits.length} expired deposits to cancel`);

      let totalCancelled = 0;
      let totalValue = 0;

      for (const deposit of expiredDeposits) {
        try {
          // Cancel the expired deposit
          await this.storage.cancelExpiredDeposit(deposit.id);

          totalCancelled++;
          totalValue += parseFloat(deposit.amountUSD || '0');

          console.log(`❌ [DEPOSIT-EXPIRY] Cancelled expired deposit:`, {
            id: deposit.id,
            userId: deposit.userId,
            amount: `${deposit.amountUSD} USD`,
            ntiqAmount: `${deposit.ntiqAmount} NTIQ`,
            tokenType: deposit.tokenType,
            chainName: deposit.chainName,
            createdAt: deposit.createdAt,
            expiresAt: deposit.expiresAt,
            timeExpired: this.getTimeExpiredText(deposit.expiresAt)
          });

        } catch (error) {
          console.error(`❌ [DEPOSIT-EXPIRY] Failed to cancel deposit ${deposit.id}:`, error);
        }
      }

      if (totalCancelled > 0) {
        console.log(`✅ [DEPOSIT-EXPIRY] Successfully cancelled ${totalCancelled} expired deposits`);
        console.log(`💰 [DEPOSIT-EXPIRY] Total value cancelled: $${totalValue.toFixed(2)}`);

        // Log summary for admin monitoring
        this.logExpiryStats({
          expiredDeposits: expiredDeposits.length,
          cancelledDeposits: totalCancelled,
          totalValue
        });
      }

    } catch (error) {
      console.error('❌ [DEPOSIT-EXPIRY] Error during expired deposit check:', error);
    }
  }

  /**
   * Get human-readable time expired text
   */
  private getTimeExpiredText(expiresAt: string): string {
    const now = new Date();
    const expiry = new Date(expiresAt);
    const diffMs = now.getTime() - expiry.getTime();
    const diffMinutes = Math.floor(diffMs / (1000 * 60));

    if (diffMinutes < 60) {
      return `${diffMinutes} minutes ago`;
    } else {
      const hours = Math.floor(diffMinutes / 60);
      const minutes = diffMinutes % 60;
      return `${hours}h ${minutes}m ago`;
    }
  }

  /**
   * Log expiry statistics for monitoring
   */
  private logExpiryStats(stats: DepositExpiryStats): void {
    console.log('📊 [DEPOSIT-EXPIRY] Expiry Statistics:', {
      timestamp: new Date().toISOString(),
      expiredDeposits: stats.expiredDeposits,
      cancelledDeposits: stats.cancelledDeposits,
      totalValueCancelled: `$${stats.totalValue.toFixed(2)}`,
      successRate: `${((stats.cancelledDeposits / stats.expiredDeposits) * 100).toFixed(1)}%`
    });
  }

  /**
   * Get service status
   */
  public getStatus(): { isRunning: boolean; nextCheck?: string } {
    const status: any = { isRunning: this.isRunning };

    if (this.isRunning) {
      // Calculate next check time (5 minutes from now)
      const nextCheck = new Date();
      nextCheck.setMinutes(nextCheck.getMinutes() + 5);
      status.nextCheck = nextCheck.toISOString();
    }

    return status;
  }

  /**
   * Manual check for expired deposits (for admin use)
   */
  public async manualCheck(): Promise<DepositExpiryStats> {
    console.log('🔧 [DEPOSIT-EXPIRY] Manual deposit expiry check initiated');

    const expiredDeposits = await this.storage.getExpiredDeposits();
    let cancelledDeposits = 0;
    let totalValue = 0;

    for (const deposit of expiredDeposits) {
      try {
        await this.storage.cancelExpiredDeposit(deposit.id);
        cancelledDeposits++;
        totalValue += parseFloat(deposit.amountUSD || '0');
      } catch (error) {
        console.error(`Failed to cancel deposit ${deposit.id}:`, error);
      }
    }

    const stats = {
      expiredDeposits: expiredDeposits.length,
      cancelledDeposits,
      totalValue
    };

    console.log('📊 [DEPOSIT-EXPIRY] Manual check completed:', stats);
    return stats;
  }
}

// Create singleton instance
let depositExpiryServiceInstance: DepositExpiryService | null = null;

export function initializeDepositExpiryService(storage: IStorage): DepositExpiryService {
  if (!depositExpiryServiceInstance) {
    depositExpiryServiceInstance = new DepositExpiryService(storage);
  }
  return depositExpiryServiceInstance;
}

export function getDepositExpiryService(): DepositExpiryService | null {
  return depositExpiryServiceInstance;
}

server/services/depositMonitorService.ts.content:
import axios from 'axios';
import { storage } from '../storage.js';
import { BalanceService } from './balanceService.js';

class DepositMonitorService {
  private static instance: DepositMonitorService;
  private isRunning = false;
  private intervalId: NodeJS.Timeout | null = null;
  private readonly CHECK_INTERVAL = 60000; // Check every 1 minute
  private readonly ETHERSCAN_API_KEY = process.env.ETHERSCAN_API_KEY || 'YOUR_API_KEY_HERE';

  static getInstance(): DepositMonitorService {
    if (!DepositMonitorService.instance) {
      DepositMonitorService.instance = new DepositMonitorService();
    }
    return DepositMonitorService.instance;
  }

  async start() {
    if (this.isRunning) {
      console.log('🔄 [DEPOSIT-MONITOR] Already running');
      return;
    }

    this.isRunning = true;
    console.log('🚀 [DEPOSIT-MONITOR] Starting automated deposit status monitoring...');

    // Run initial check
    await this.checkProcessingDeposits();

    // Set up recurring checks
    this.intervalId = setInterval(async () => {
      await this.checkProcessingDeposits();
    }, this.CHECK_INTERVAL);
  }

  stop() {
    if (this.intervalId) {
      clearInterval(this.intervalId);
      this.intervalId = null;
    }
    this.isRunning = false;
    console.log('⏹️ [DEPOSIT-MONITOR] Stopped');
  }

  private async checkProcessingDeposits() {
    try {
      console.log('🔍 [DEPOSIT-MONITOR] Checking processing deposits...');

      const processingDeposits = await storage.getDepositsByStatus('processing');

      if (processingDeposits.length === 0) {
        console.log('✅ [DEPOSIT-MONITOR] No processing deposits found');
        return;
      }

      console.log(`📊 [DEPOSIT-MONITOR] Found ${processingDeposits.length} processing deposits`);

      for (const deposit of processingDeposits) {
        await this.checkDepositStatus(deposit);
      }
    } catch (error) {
      console.error('❌ [DEPOSIT-MONITOR] Error checking deposits:', error);
    }
  }

  private async checkDepositStatus(deposit: any) {
    try {
      if (!deposit.transactionHash) {
        console.log(`⚠️ [DEPOSIT-MONITOR] Deposit ${deposit.id} has no transaction hash, skipping`);
        return;
      }

      console.log(`🔍 [DEPOSIT-MONITOR] Checking deposit ${deposit.id} - ${deposit.transactionHash}`);

      const isSuccess = await this.checkTransactionStatus(deposit.transactionHash, deposit.network || 'sepolia');

      if (isSuccess) {
        console.log(`✅ [DEPOSIT-MONITOR] Transaction ${deposit.transactionHash} confirmed on blockchain`);
        await this.processSuccessfulDeposit(deposit);
      } else {
        console.log(`⏳ [DEPOSIT-MONITOR] Transaction ${deposit.transactionHash} still pending or not found`);
      }
    } catch (error) {
      console.error(`❌ [DEPOSIT-MONITOR] Error checking deposit ${deposit.id}:`, error);
    }
  }

  private async checkTransactionStatus(txHash: string, network: string): Promise<boolean> {
    try {
      let apiUrl = '';

      switch (network.toLowerCase()) {
        case 'sepolia':
          apiUrl = `https://api-sepolia.etherscan.io/api?module=transaction&action=gettxreceiptstatus&txhash=${txHash}&apikey=${this.ETHERSCAN_API_KEY}`;
          break;
        case 'holesky':
          apiUrl = `https://api-holesky.etherscan.io/api?module=transaction&action=gettxreceiptstatus&txhash=${txHash}&apikey=${this.ETHERSCAN_API_KEY}`;
          break;
        case 'ethereum':
        case 'mainnet':
          apiUrl = `https://api.etherscan.io/api?module=transaction&action=gettxreceiptstatus&txhash=${txHash}&apikey=${this.ETHERSCAN_API_KEY}`;
          break;
        case 'bsc':
          apiUrl = `https://api.bscscan.com/api?module=transaction&action=gettxreceiptstatus&txhash=${txHash}&apikey=${this.ETHERSCAN_API_KEY}`;
          break;
        case 'optimism':
          apiUrl = `https://api-optimistic.etherscan.io/api?module=transaction&action=gettxreceiptstatus&txhash=${txHash}&apikey=${this.ETHERSCAN_API_KEY}`;
          break;
        case 'arbitrum':
          apiUrl = `https://api.arbiscan.io/api?module=transaction&action=gettxreceiptstatus&txhash=${txHash}&apikey=${this.ETHERSCAN_API_KEY}`;
          break;
        default:
          console.log(`⚠️ [DEPOSIT-MONITOR] Unsupported network: ${network}, defaulting to sepolia`);
          apiUrl = `https://api-sepolia.etherscan.io/api?module=transaction&action=gettxreceiptstatus&txhash=${txHash}&apikey=${this.ETHERSCAN_API_KEY}`;
      }

      const response = await axios.get(apiUrl, {
        timeout: 10000,
        headers: {
          'User-Agent': 'Nectiq-DepositMonitor/1.0'
        }
      });

      if (response.data && response.data.status === '1') {
        // Status 1 means success, 0 means failure
        return response.data.result?.status === '1';
      }

      return false;
    } catch (error) {
      console.error(`❌ [DEPOSIT-MONITOR] Error checking transaction ${txHash}:`, error);
      return false;
    }
  }

  private async processSuccessfulDeposit(deposit: any) {
    try {
      console.log(`🎉 [DEPOSIT-MONITOR] Processing successful deposit ${deposit.id} for user ${deposit.userId}`);

      // Update deposit status to completed
      await storage.updateDepositStatus(deposit.id, 'completed');
      console.log(`✅ [DEPOSIT-MONITOR] Updated deposit ${deposit.id} status to completed`);

      // Credit user balance using BalanceService
      await BalanceService.processTransaction({
        userId: deposit.userId,
        type: 'deposit_credit',
        amount: deposit.ntiqAmount,
        token: 'NTIQ',
        hash: deposit.transactionHash,
        description: `Automated deposit credit - Deposit ID ${deposit.id}`,
        relatedId: deposit.id,
        metadata: {
          depositId: deposit.id,
          originalAmount: deposit.ntiqAmount,
          source: 'automated_monitor'
        }
      }, storage);

      console.log(`💰 [DEPOSIT-MONITOR] Credited ${deposit.ntiqAmount} NTIQ to user ${deposit.userId}`);

      // Get user info for logging
      const user = await storage.getUserById(deposit.userId);
      if (user) {
        console.log(`📈 [DEPOSIT-MONITOR] User ${user.username} balance updated automatically from blockchain confirmation`);
      }

      // Send real-time notification to user
      try {
        // Import broadcastNotification function from routes
        const { broadcastNotificationCallback } = await import('../routes.js');

        if (broadcastNotificationCallback) {
          broadcastNotificationCallback(deposit.userId, {
            type: 'deposit_completed',
            title: 'Deposit Completed',
            message: `Your deposit of ${deposit.ntiqAmount} NTIQ has been successfully processed and credited to your account.`,
            data: {
              depositId: deposit.id,
              amount: deposit.ntiqAmount,
              currency: 'NTIQ',
              transactionHash: deposit.transactionHash,
              completedAt: new Date().toISOString()
            },
            timestamp: Date.now(),
            priority: 'high'
          });

          console.log(`📡 [DEPOSIT-MONITOR] Real-time notification sent to user ${deposit.userId} for completed deposit`);
        } else {
          console.log(`⚠️ [DEPOSIT-MONITOR] Broadcast function not available, notification not sent`);
        }
      } catch (error) {
        console.error(`❌ [DEPOSIT-MONITOR] Error sending notification:`, error);
      }

    } catch (error) {
      console.error(`❌ [DEPOSIT-MONITOR] Error processing successful deposit ${deposit.id}:`, error);
    }
  }

  getStatus() {
    return {
      isRunning: this.isRunning,
      checkInterval: this.CHECK_INTERVAL,
      uptime: this.isRunning ? Date.now() : 0
    };
  }
}

export { DepositMonitorService };

server/services/loyaltyService.ts.content:
import { pool } from "../db";

export interface TierInfo {
  tierName: string;
  minEarnings: number;
  maxEarnings: number | null;
  rewardMultiplier: number;
  cashbackPercentage: number;
  monthlyBonus: number;
  freeInsuranceDaily: number;
  prioritySupport: boolean;
  earlyAccess: boolean;
  personalManager: boolean;
}

export interface UserTierData {
  currentTier: string;
  lifetimeEarnings: number;
  nextTier: string | null;
  nextTierRequirement: number | null;
  progressPercentage: number;
  currentBenefits: TierInfo;
  nextTierBenefits: TierInfo | null;
}

export class LoyaltyService {
  // Get all tier configurations
  static async getAllTiers(): Promise<TierInfo[]> {
    const query = `
      SELECT tier_name, min_earnings, max_earnings, reward_multiplier, 
             cashback_percentage, monthly_bonus, free_insurance_daily,
             priority_support, early_access, personal_manager
      FROM loyalty_tiers 
      ORDER BY min_earnings ASC
    `;

    const result = await pool.query(query);
    return result.rows.map(row => ({
      tierName: row.tier_name,
      minEarnings: row.min_earnings,
      maxEarnings: row.max_earnings,
      rewardMultiplier: parseFloat(row.reward_multiplier),
      cashbackPercentage: parseFloat(row.cashback_percentage),
      monthlyBonus: row.monthly_bonus,
      freeInsuranceDaily: row.free_insurance_daily,
      prioritySupport: row.priority_support,
      earlyAccess: row.early_access,
      personalManager: row.personal_manager
    }));
  }

  // Calculate user's tier based on lifetime earnings
  static async calculateTier(lifetimeEarnings: number): Promise<string> {
    const tiers = await this.getAllTiers();

    for (let i = tiers.length - 1; i >= 0; i--) {
      const tier = tiers[i];
      if (lifetimeEarnings >= tier.minEarnings) {
        return tier.tierName;
      }
    }

    return 'bronze'; // Default fallback
  }

  // Get user tier data with progress information
  static async getUserTierData(userId: number): Promise<UserTierData> {
    // Get user's current data
    const userQuery = `SELECT loyalty_tier, lifetime_earnings FROM users WHERE id = $1`;
    const userResult = await pool.query(userQuery, [userId]);

    if (userResult.rows.length === 0) {
      throw new Error('User not found');
    }

    const user = userResult.rows[0];
    const lifetimeEarnings = user.lifetime_earnings || 0;

    // Get all tiers
    const tiers = await this.getAllTiers();

    // Find current tier
    const currentTierName = await this.calculateTier(lifetimeEarnings);
    const currentTier = tiers.find(t => t.tierName === currentTierName)!;

    // Find next tier
    const currentTierIndex = tiers.findIndex(t => t.tierName === currentTierName);
    const nextTier = currentTierIndex < tiers.length - 1 ? tiers[currentTierIndex + 1] : null;

    // Calculate progress
    let progressPercentage = 0;
    if (nextTier) {
      const currentTierMin = currentTier.minEarnings;
      const nextTierMin = nextTier.minEarnings;
      const userProgress = lifetimeEarnings - currentTierMin;
      const tierRange = nextTierMin - currentTierMin;
      progressPercentage = Math.min(100, (userProgress / tierRange) * 100);
    } else {
      progressPercentage = 100; // Already at max tier
    }

    return {
      currentTier: currentTierName,
      lifetimeEarnings,
      nextTier: nextTier?.tierName || null,
      nextTierRequirement: nextTier?.minEarnings || null,
      progressPercentage: Math.round(progressPercentage),
      currentBenefits: currentTier,
      nextTierBenefits: nextTier
    };
  }

  // Update user's lifetime earnings and check for tier promotion
  static async updateLifetimeEarnings(userId: number, earnedAmount: number): Promise<{ 
    promoted: boolean, 
    oldTier: string, 
    newTier: string,
    celebrationData?: any 
  }> {
    // Get current user data
    const userQuery = `SELECT loyalty_tier, lifetime_earnings FROM users WHERE id = $1`;
    const userResult = await pool.query(userQuery, [userId]);

    if (userResult.rows.length === 0) {
      throw new Error('User not found');
    }

    const currentUser = userResult.rows[0];
    const oldTier = currentUser.loyalty_tier;
    const oldEarnings = currentUser.lifetime_earnings || 0;
    const newEarnings = oldEarnings + earnedAmount;

    // Calculate new tier
    const newTier = await this.calculateTier(newEarnings);

    // Update user's lifetime earnings and tier
    const updateQuery = `
      UPDATE users 
      SET lifetime_earnings = $1, loyalty_tier = $2, last_tier_update = NOW()
      WHERE id = $3
    `;
    await pool.query(updateQuery, [newEarnings, newTier, userId]);

    const promoted = oldTier !== newTier;

    // If promoted, log the promotion
    if (promoted) {
      const promotionQuery = `
        INSERT INTO tier_promotions (user_id, from_tier, to_tier, lifetime_earnings)
        VALUES ($1, $2, $3, $4)
      `;
      await pool.query(promotionQuery, [userId, oldTier, newTier, newEarnings]);

      // Get tier benefits for celebration
      const tierInfo = await this.getTierInfo(newTier);

      return {
        promoted: true,
        oldTier,
        newTier,
        celebrationData: {
          tierName: newTier,
          benefits: tierInfo,
          newEarnings
        }
      };
    }

    return { promoted: false, oldTier, newTier };
  }

  // Get tier information by name
  static async getTierInfo(tierName: string): Promise<TierInfo | null> {
    const query = `
      SELECT tier_name, min_earnings, max_earnings, reward_multiplier, 
             cashback_percentage, monthly_bonus, free_insurance_daily,
             priority_support, early_access, personal_manager
      FROM loyalty_tiers 
      WHERE tier_name = $1
    `;

    const result = await pool.query(query, [tierName]);

    if (result.rows.length === 0) return null;

    const row = result.rows[0];
    return {
      tierName: row.tier_name,
      minEarnings: row.min_earnings,
      maxEarnings: row.max_earnings,
      rewardMultiplier: parseFloat(row.reward_multiplier),
      cashbackPercentage: parseFloat(row.cashback_percentage),
      monthlyBonus: row.monthly_bonus,
      freeInsuranceDaily: row.free_insurance_daily,
      prioritySupport: row.priority_support,
      earlyAccess: row.early_access,
      personalManager: row.personal_manager
    };
  }

  // Generate monthly tier rewards for all users
  static async generateMonthlyRewards(month: string): Promise<number> {
    const usersQuery = `
      SELECT id, loyalty_tier, username 
      FROM users 
      WHERE loyalty_tier != 'bronze'
    `;

    const usersResult = await pool.query(usersQuery);
    let generatedCount = 0;

    for (const user of usersResult.rows) {
      const tierInfo = await this.getTierInfo(user.loyalty_tier);
      if (!tierInfo || tierInfo.monthlyBonus === 0) continue;

      // Check if reward already exists for this month
      const existingQuery = `
        SELECT id FROM monthly_tier_rewards 
        WHERE user_id = $1 AND month = $2
      `;
      const existingResult = await pool.query(existingQuery, [user.id, month]);

      if (existingResult.rows.length === 0) {
        // Create monthly reward
        const insertQuery = `
          INSERT INTO monthly_tier_rewards (user_id, month, tier, bonus_amount, free_entries)
          VALUES ($1, $2, $3, $4, $5)
        `;

        const freeEntries = user.loyalty_tier === 'gold' ? 1 : user.loyalty_tier === 'platinum' ? 3 : 0;

        await pool.query(insertQuery, [
          user.id, 
          month, 
          user.loyalty_tier, 
          tierInfo.monthlyBonus,
          freeEntries
        ]);

        generatedCount++;
      }
    }

    return generatedCount;
  }

  // Claim monthly tier reward
  static async claimMonthlyReward(userId: number, month: string): Promise<{
    success: boolean,
    reward?: { bonusAmount: number, freeEntries: number },
    message: string
  }> {
    const rewardQuery = `
      SELECT bonus_amount, free_entries, claimed
      FROM monthly_tier_rewards 
      WHERE user_id = $1 AND month = $2
    `;

    const rewardResult = await pool.query(rewardQuery, [userId, month]);

    if (rewardResult.rows.length === 0) {
      return { success: false, message: 'No monthly reward available for this month' };
    }

    const reward = rewardResult.rows[0];

    if (reward.claimed) {
      return { success: false, message: 'Monthly reward already claimed' };
    }

    // Mark as claimed and add to user balance
    const updateRewardQuery = `
      UPDATE monthly_tier_rewards 
      SET claimed = true, claimed_at = NOW()
      WHERE user_id = $1 AND month = $2
    `;

    const updateBalanceQuery = `
      UPDATE users 
      SET balance = balance + $1
      WHERE id = $2
    `;

    await pool.query(updateRewardQuery, [userId, month]);
    await pool.query(updateBalanceQuery, [reward.bonus_amount, userId]);

    return {
      success: true,
      reward: {
        bonusAmount: reward.bonus_amount,
        freeEntries: reward.free_entries
      },
      message: 'Monthly reward claimed successfully'
    };
  }
}

server/services/parlayProcessorService.t.content:
import { db } from '../db.js';
import { parlayPredictionCoins, parlayPredictions } from '@shared/schema';
import { eq, and, lte, isNull } from 'drizzle-orm';
import { cryptoService } from './cryptoService.js';
import { BalanceService } from './balanceService.js';
import { storage } from '../storage.js';

export class ParlayProcessorService {
  // Process expired parlay prediction coins by setting their end prices
  async processExpiredParlayPredictions() {
    try {
      console.log('🔍 [PARLAY-PROCESSOR] Checking for expired parlay prediction coins...');

      // Get all expired parlay prediction coins that haven't been processed yet
      const now = new Date();
      const expiredCoins = await db
        .select()
        .from(parlayPredictionCoins)
        .leftJoin(parlayPredictions, eq(parlayPredictionCoins.parlayId, parlayPredictions.id))
        .where(
          and(
            lte(parlayPredictionCoins.targetTime, now),
            isNull(parlayPredictionCoins.endPrice),
            eq(parlayPredictions.status, 'active')
          )
        );

      if (expiredCoins.length === 0) {
        console.log('✅ [PARLAY-PROCESSOR] No expired parlay prediction coins found');
        return;
      }

      console.log(`🔍 [PARLAY-PROCESSOR] Found ${expiredCoins.length} expired parlay prediction coins`);

      // Get current prices for processing
      const currentPrices = await cryptoService.getCurrentPrices();
      const priceMap = new Map(currentPrices.map(p => [p.id, p.current_price]));

      for (const expiredCoin of expiredCoins) {
        const coinData = expiredCoin.parlay_prediction_coins;
        const parlayData = expiredCoin.parlay_predictions;

        if (!coinData || !parlayData) continue;

        const currentPrice = priceMap.get(coinData.cryptocurrency) || 0;
        const startPrice = parseFloat(coinData.startPrice || '0');

        // Determine if prediction was correct
        const priceWentUp = currentPrice > startPrice;
        const wasCorrect = (coinData.prediction === 'up' && priceWentUp) || 
                          (coinData.prediction === 'down' && !priceWentUp);

        // Update the coin with end price and correctness directly via database
        await db
          .update(parlayPredictionCoins)
          .set({
            endPrice: currentPrice.toString(),
            isCorrect: wasCorrect
          })
          .where(eq(parlayPredictionCoins.id, coinData.id));

        console.log(`📸 [PARLAY-PROCESSOR] Updated ${coinData.cryptocurrency}: ${coinData.prediction} prediction, Start: $${startPrice}, End: $${currentPrice}, Correct: ${wasCorrect}`);
      }

      console.log('✅ [PARLAY-PROCESSOR] Successfully processed all expired coins');

      // After processing all expired coins, check for completed parlays and award rewards
      await this.processCompletedParlays();

    } catch (error) {
      console.error('❌ [PARLAY-PROCESSOR] Error processing expired parlay predictions:', error);
    }
  }

  // Process completed parlays and award rewards
  async processCompletedParlays() {
    try {
      console.log('🎯 [PARLAY-REWARDS] Checking for completed parlays...');

      // Get all active parlays that might be completed
      const activeParlays = await db
        .select()
        .from(parlayPredictions)
        .where(eq(parlayPredictions.status, 'active'));

      if (activeParlays.length === 0) {
        console.log('✅ [PARLAY-REWARDS] No active parlays found');
        return;
      }

      console.log(`🔍 [PARLAY-REWARDS] Found ${activeParlays.length} active parlays to check`);

      for (const parlay of activeParlays) {
        await this.checkAndProcessParlayCompletion(parlay);
      }

      console.log('✅ [PARLAY-REWARDS] Finished processing completed parlays');

    } catch (error) {
      console.error('❌ [PARLAY-REWARDS] Error processing completed parlays:', error);
    }
  }

  // Check if a parlay is completed and process rewards
  async checkAndProcessParlayCompletion(parlay: any) {
    try {
      // Get all coins for this parlay
      const parlayCoins = await db
        .select()
        .from(parlayPredictionCoins)
        .where(eq(parlayPredictionCoins.parlayId, parlay.id));

      if (parlayCoins.length === 0) {
        console.log(`⚠️ [PARLAY-REWARDS] Parlay ${parlay.id} has no coins`);
        return;
      }

      // Check if all coins have been processed (have endPrice and isCorrect)
      const processedCoins = parlayCoins.filter(coin => 
        coin.endPrice !== null && coin.isCorrect !== null
      );

      if (processedCoins.length !== parlayCoins.length) {
        console.log(`🕐 [PARLAY-REWARDS] Parlay ${parlay.id} not yet complete: ${processedCoins.length}/${parlayCoins.length} coins processed`);
        return; // Not all coins processed yet
      }

      console.log(`🎯 [PARLAY-REWARDS] Parlay ${parlay.id} is complete, processing rewards...`);

      // Check if all predictions are correct (parlay wins only if ALL are correct)
      const allCorrect = processedCoins.every(coin => coin.isCorrect === true);

      if (allCorrect) {
        // Calculate parlay reward using compound multiplier system
        const totalReward = this.calculateParlayReward(parlay.stakeAmount, processedCoins);

        console.log(`🏆 [PARLAY-REWARDS] Parlay ${parlay.id} WON! Stake: ${parlay.stakeAmount}, Reward: ${totalReward}`);

        // Award reward using BalanceService
        const balanceResult = await BalanceService.processTransaction({
          userId: parlay.userId,
          type: 'parlay_reward',
          amount: totalReward,
          description: `Parlay victory reward - ${processedCoins.length} coins, ${totalReward} NTIQ`,
          relatedId: parlay.id,
          metadata: {
            stakeAmount: parlay.stakeAmount,
            totalCoins: processedCoins.length,
            multiplier: totalReward / parlay.stakeAmount,
            coinResults: processedCoins.map(coin => ({
              cryptocurrency: coin.cryptocurrency,
              prediction: coin.prediction,
              isCorrect: coin.isCorrect,
              duration: coin.duration
            }))
          }
        }, storage);

        console.log(`✅ [PARLAY-REWARDS] Successfully awarded ${totalReward} NTIQ to user ${parlay.userId}`);

        // Update parlay status to completed with win
        await db
          .update(parlayPredictions)
          .set({ 
            status: 'completed',
            result: 'win',
            rewardAmount: totalReward,
            completedAt: new Date()
          })
          .where(eq(parlayPredictions.id, parlay.id));

      } else {
        console.log(`💔 [PARLAY-REWARDS] Parlay ${parlay.id} LOST - at least one prediction was wrong`);

        // Update parlay status to completed with loss (no reward)
        await db
          .update(parlayPredictions)
          .set({ 
            status: 'completed',
            result: 'lose',
            rewardAmount: 0,
            completedAt: new Date()
          })
          .where(eq(parlayPredictions.id, parlay.id));
      }

    } catch (error) {
      console.error(`❌ [PARLAY-REWARDS] Error processing parlay ${parlay.id}:`, error);
    }
  }

  // Calculate parlay reward using frontend-synchronized multiplier system
  private calculateParlayReward(stakeAmount: number, coins: any[]): number {
    // Duration multipliers matching frontend exactly
    const getDurationMultiplier = (duration: string): number => {
      switch (duration) {
        case '1h': return 1.2;
        case '6h': return 1.5;
        case '24h': return 2.0;
        case '7d': return 3.0;
        default: return 1.2;
      }
    };

    // Calculate total multiplier using frontend formula: (1.5 × Duration Multiplier)^Number_of_Predictions
    // Since all coins must have same duration, we can use the first coin's duration
    const duration = coins[0]?.duration || '1h';
    const durationMultiplier = getDurationMultiplier(duration);
    const numberOfPredictions = coins.length;

    const totalMultiplier = Math.pow(1.5 * durationMultiplier, numberOfPredictions);

    // Calculate final reward
    const grossReward = Math.round(stakeAmount * totalMultiplier);

    // Apply 6% platform fee (matching frontend documentation)
    const platformFee = Math.round(grossReward * 0.06);
    const netReward = grossReward - platformFee;

    console.log(`💰 [PARLAY-REWARD-CALC] Stake: ${stakeAmount}, Predictions: ${numberOfPredictions}, Duration: ${duration} (${durationMultiplier}x), Base Formula: (1.5 × ${durationMultiplier})^${numberOfPredictions} = ${totalMultiplier.toFixed(2)}x, Gross: ${grossReward}, Fee (6%): ${platformFee}, Net: ${netReward}`);

    return netReward;
  }
}

