client/src/components/WalletConnectionSt.content:
import React from 'react';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { AlertCircle, CheckCircle, WifiOff, Wifi } from 'lucide-react';
import { useWalletConnectionStatus } from '@/hooks/useWalletConnectionStatus';
import { useAccount } from 'wagmi';

interface WalletConnectionStatusProps {
  className?: string;
  showDetails?: boolean;
}

export function WalletConnectionStatus({ 
  className = "", 
  showDetails = false 
}: WalletConnectionStatusProps) {
  const { isConnected, address } = useAccount();
  const {
    connectionQuality,
    connectionHistory,
    getRecentDisconnects,
    hasRecentConnection
  } = useWalletConnectionStatus();

  // Don't show anything if wallet is not connected
  if (!isConnected || !address) {
    return null;
  }

  const recentDisconnects = getRecentDisconnects();
  const isRecentConnection = hasRecentConnection();

  const getStatusIcon = () => {
    if (!connectionQuality.isStable) {
      return <WifiOff className="h-4 w-4 text-orange-500" />;
    }
    if (isRecentConnection) {
      return <CheckCircle className="h-4 w-4 text-green-500" />;
    }
    return <Wifi className="h-4 w-4 text-blue-500" />;
  };

  const getStatusText = () => {
    if (!connectionQuality.isStable) {
      return "Connection Unstable";
    }
    if (isRecentConnection) {
      return "Recently Connected";
    }
    return "Connected";
  };

  const getStatusVariant = (): "default" | "secondary" | "destructive" | "outline" => {
    if (!connectionQuality.isStable) {
      return "destructive";
    }
    if (isRecentConnection) {
      return "default";
    }
    return "secondary";
  };

  if (!showDetails) {
    // Simple badge view
    return (
      <div className={`flex items-center gap-2 ${className}`}>
        {getStatusIcon()}
        <Badge variant={getStatusVariant()}>
          {getStatusText()}
        </Badge>
      </div>
    );
  }

  // Detailed card view
  return (
    <Card className={`${className}`}>
      <CardContent className="p-4">
        <div className="space-y-3">
          {/* Status Header */}
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              {getStatusIcon()}
              <span className="font-medium">{getStatusText()}</span>
            </div>
            <Badge variant={getStatusVariant()}>
              {address.slice(0, 6)}...{address.slice(-4)}
            </Badge>
          </div>

          {/* Connection Quality Info */}
          {!connectionQuality.isStable && (
            <div className="flex items-start gap-2 p-2 bg-orange-50 dark:bg-orange-950/20 rounded-md">
              <AlertCircle className="h-4 w-4 text-orange-500 mt-0.5" />
              <div className="text-sm text-orange-700 dark:text-orange-300">
                <div className="font-medium">Connection Issues Detected</div>
                <div className="text-xs">
                  {connectionQuality.disconnectCount} disconnections detected. 
                  Please check your wallet extension.
                </div>
              </div>
            </div>
          )}

          {/* Recent Activity */}
          {(recentDisconnects.length > 0 || isRecentConnection) && (
            <div className="space-y-2">
              <div className="text-xs font-medium text-gray-500 dark:text-gray-400">
                Recent Activity
              </div>

              {isRecentConnection && (
                <div className="text-xs text-green-600 dark:text-green-400">
                  ✓ Connected successfully
                </div>
              )}

              {recentDisconnects.slice(0, 3).map((event, index) => (
                <div key={index} className="text-xs text-gray-600 dark:text-gray-400">
                  ⚠ Disconnected {Math.round((Date.now() - event.timestamp) / 60000)}m ago
                </div>
              ))}
            </div>
          )}

          {/* Stability Tips */}
          {!connectionQuality.isStable && (
            <div className="pt-2 border-t border-gray-200 dark:border-gray-700">
              <div className="text-xs text-gray-600 dark:text-gray-400">
                <div className="font-medium mb-1">Tips for stable connection:</div>
                <ul className="space-y-1 text-xs">
                  <li>• Keep wallet extension updated</li>
                  <li>• Avoid switching browser tabs frequently</li>
                  <li>• Check internet connection stability</li>
                </ul>
              </div>
            </div>
          )}
        </div>
      </CardContent>
    </Card>
  );
}

export default WalletConnectionStatus;

client/src/components/WalletEmailVerific.content:
import { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent } from "@/components/ui/card";
import { Mail, Wallet, Shield, CheckCircle, AlertCircle } from "lucide-react";
import { signInWithGoogle, auth } from "@/lib/firebase";
import { onAuthStateChanged, User } from "firebase/auth";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";

interface WalletEmailVerificationProps {
  walletAddress: string;
  onSuccess: () => void;
  onCancel: () => void;
}

interface LinkWalletEmailRequest {
  walletAddress: string;
  email: string;
  firebaseUid: string;
  displayName?: string;
}

export function WalletEmailVerification({ 
  walletAddress, 
  onSuccess, 
  onCancel 
}: WalletEmailVerificationProps) {
  const [step, setStep] = useState<'info' | 'gmail' | 'manual' | 'success'>('info');
  const [firebaseUser, setFirebaseUser] = useState<User | null>(null);
  const [manualEmail, setManualEmail] = useState('');
  const [isSigningIn, setIsSigningIn] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const { toast } = useToast();
  const queryClient = useQueryClient();

  // Debug logging
  if (import.meta.env.DEV) {
    console.log('🔧 [WalletEmailVerification] Component rendered with props:', { walletAddress, step });
  }

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      setFirebaseUser(user);
      if (user && step === 'gmail') {
        handleEmailVerified(user);
      }
    });

    return () => unsubscribe();
  }, [step]);

  const linkWalletEmailMutation = useMutation({
    mutationFn: async (data: LinkWalletEmailRequest) => {
      return apiRequest('/api/auth/link-wallet-email', {
        method: 'POST',
        body: JSON.stringify(data),
      });
    },
    onSuccess: () => {
      setStep('success');
      queryClient.invalidateQueries({ queryKey: ['/api/user'] });
      toast({
        title: "Email Linked Successfully",
        description: "Your wallet address has been linked with your Gmail account.",
      });
    },
    onError: (error: any) => {
      if (import.meta.env.DEV) {
        console.error('Link wallet email error:', error);
      }

      // Handle specific error codes for better user experience
      let title = "Verification Failed";
      let description = "Failed to link wallet with email. Please try again.";

      if (error.code === "EMAIL_ALREADY_LINKED" || 
          (error.message && (error.message.includes("sudah terkait") || error.message.includes("already linked")))) {
        title = "Email Already Used";
        description = error.message || "This email is already linked with another wallet address. Please use a different email.";
        setErrorMessage(error.message || "This email is already linked with another wallet address. Please use a different email.");
      } else if (error.message) {
        description = error.message;
        setErrorMessage(error.message);
      } else {
        setErrorMessage("Failed to link wallet with email. Please try again.");
      }

      toast({
        title,
        description,
        variant: "destructive",
      });
    },
  });

  const handleGoogleSignIn = async () => {
    setIsSigningIn(true);
    setErrorMessage(null); // Reset error message
    try {
      if (import.meta.env.DEV) {
        console.log('🔥 [FIREBASE] Attempting Google Sign-In...');
        console.log('🔥 [FIREBASE] Current domain:', window.location.hostname);
      }
      const user = await signInWithGoogle();
      if (user) {
        if (import.meta.env.DEV) {
          console.log('✅ [FIREBASE] Google Sign-In successful:', user.email);
        }
        setStep('gmail');
      }
    } catch (error: any) {
      console.error('❌ [FIREBASE] Google sign-in error:', error);

      // Check if it's an unauthorized domain error
      if (error.code === 'auth/unauthorized-domain') {
        console.log('🔥 [FIREBASE] Domain authorization required for:', window.location.hostname);
        toast({
          title: "Firebase Domain Configuration Required",
          description: `Add "${window.location.hostname}" to Firebase Console > Authentication > Settings > Authorized domains`,
          variant: "destructive",
        });

        // Show domain info in console for easy copy-paste
        console.log(`
🔧 FIREBASE SETUP REQUIRED:
1. Go to https://console.firebase.google.com/
2. Select your project  
3. Go to Authentication > Settings > Authorized domains
4. Click "Add domain" and enter: ${window.location.hostname}
5. Save and try again
        `);

        // Show manual email option for unauthorized domain
        setStep('manual');
      } else {
        toast({
          title: "Google Sign-in Failed",
          description: error.message || "Failed to sign in with Google. Please try again.",
          variant: "destructive",
        });
        setStep('manual');
      }
    } finally {
      setIsSigningIn(false);
    }
  };

  const handleEmailVerified = async (user: User) => {
    if (user.email) {
      try {
        await linkWalletEmailMutation.mutateAsync({
          walletAddress,
          email: user.email,
          firebaseUid: user.uid,
          displayName: user.displayName || undefined,
        });
      } catch (error) {
        console.error('Email verification error:', error);
      }
    }
  };

  const handleManualEmail = async () => {
    setErrorMessage(null); // Reset error message
    if (!manualEmail.includes('@gmail.com')) {
      toast({
        title: "Invalid Email",
        description: "Please enter a valid Gmail address.",
        variant: "destructive",
      });
      return;
    }

    try {
      await linkWalletEmailMutation.mutateAsync({
        walletAddress,
        email: manualEmail,
        firebaseUid: '',
        displayName: undefined,
      });
    } catch (error) {
      console.error('Manual email error:', error);
    }
  };

  const handleComplete = () => {
    onSuccess();
  };

  const handleSkip = () => {
    toast({
      title: "Email Verification Skipped",
      description: "You can link your email later in your profile settings.",
    });
    onCancel();
  };

  return (
    <Dialog open={true} onOpenChange={onCancel}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Shield className="h-5 w-5 text-blue-500" />
            Wallet Email Verification
          </DialogTitle>
          <DialogDescription>
            Link your wallet address with Gmail for enhanced security and recovery options.
          </DialogDescription>
        </DialogHeader>

        {/* Error Message Display */}
        {errorMessage && (
          <Card className="border-red-200 bg-red-50/50 mb-4">
            <CardContent className="p-4">
              <div className="flex items-start gap-3">
                <AlertCircle className="h-5 w-5 text-red-600 mt-0.5 flex-shrink-0" />
                <div className="space-y-1">
                  <p className="text-sm font-medium text-red-900">
                    Email Linking Error
                  </p>
                  <p className="text-xs text-red-700">
                    {errorMessage}
                  </p>
                </div>
              </div>
            </CardContent>
          </Card>
        )}

        {step === 'info' && (
          <div className="space-y-4">
            <Card className="border-blue-200 bg-blue-50/50">
              <CardContent className="p-4">
                <div className="flex items-start gap-3">
                  <Wallet className="h-5 w-5 text-blue-600 mt-0.5" />
                  <div className="space-y-1">
                    <p className="text-sm font-medium text-blue-900">Wallet Address</p>
                    <p className="text-xs text-blue-700 font-mono break-all">
                      {walletAddress}
                    </p>
                  </div>
                </div>
              </CardContent>
            </Card>

            <div className="space-y-3 text-sm text-gray-600">
              <div className="flex items-start gap-2">
                <CheckCircle className="h-4 w-4 text-green-500 mt-0.5 flex-shrink-0" />
                <span>Enhanced account security</span>
              </div>
              <div className="flex items-start gap-2">
                <CheckCircle className="h-4 w-4 text-green-500 mt-0.5 flex-shrink-0" />
                <span>Account recovery options</span>
              </div>
              <div className="flex items-start gap-2">
                <CheckCircle className="h-4 w-4 text-green-500 mt-0.5 flex-shrink-0" />
                <span>Email notifications for important activities</span>
              </div>
            </div>

            <div className="flex gap-2 pt-2">
              <Button onClick={() => setStep('gmail')} className="flex-1">
                <Mail className="h-4 w-4 mr-2" />
                Verify with Gmail
              </Button>
              <Button variant="outline" onClick={handleSkip}>
                Skip for now
              </Button>
            </div>
          </div>
        )}

        {step === 'gmail' && (
          <div className="space-y-4">
            <div className="text-center space-y-3">
              <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto">
                <Mail className="h-8 w-8 text-red-600" />
              </div>
              <h3 className="font-medium">Sign in with Gmail</h3>
              <p className="text-sm text-gray-600">
                Click below to sign in with your Gmail account and verify your email address.
              </p>
            </div>

            <div className="space-y-3">
              <Button
                onClick={handleGoogleSignIn}
                disabled={isSigningIn || linkWalletEmailMutation.isPending}
                className="w-full bg-red-600 hover:bg-red-700"
              >
                {isSigningIn ? (
                  <>
                    <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2" />
                    Signing in...
                  </>
                ) : (
                  <>
                    <Mail className="h-4 w-4 mr-2" />
                    Sign in with Google
                  </>
                )}
              </Button>

              <div className="text-center">
                <Button
                  variant="link"
                  onClick={() => setStep('manual')}
                  className="text-sm text-gray-500"
                >
                  Enter email manually instead
                </Button>
              </div>
            </div>
          </div>
        )}

        {step === 'manual' && (
          <div className="space-y-4">
            <div className="text-center space-y-2">
              <AlertCircle className="h-12 w-12 text-amber-500 mx-auto" />
              <h3 className="font-medium">Enter Gmail Address</h3>
              <p className="text-sm text-gray-600">
                Please enter your Gmail address manually for verification.
              </p>
            </div>

            <div className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="email">Gmail Address</Label>
                <Input
                  id="email"
                  type="email"
                  placeholder="your.email@gmail.com"
                  value={manualEmail}
                  onChange={(e) => setManualEmail(e.target.value)}
                  className="w-full"
                />
              </div>

              <Button
                onClick={handleManualEmail}
                disabled={!manualEmail || linkWalletEmailMutation.isPending}
                className="w-full"
              >
                {linkWalletEmailMutation.isPending ? (
                  <>
                    <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2" />
                    Verifying...
                  </>
                ) : (
                  <>
                    <Mail className="h-4 w-4 mr-2" />
                    Verify Email
                  </>
                )}
              </Button>

              <Button
                variant="outline"
                onClick={() => setStep('gmail')}
                className="w-full"
              >
                Back to Google Sign-in
              </Button>
            </div>
          </div>
        )}

        {step === 'success' && (
          <div className="space-y-4">
            <div className="text-center space-y-3">
              <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto">
                <CheckCircle className="h-8 w-8 text-green-600" />
              </div>
              <h3 className="font-medium text-green-900">Email Verified Successfully!</h3>
              <p className="text-sm text-gray-600">
                Your wallet address has been linked with your Gmail account.
              </p>
            </div>

            {firebaseUser && (
              <Card className="border-green-200 bg-green-50/50">
                <CardContent className="p-4">
                  <div className="flex items-center gap-3">
                    <div className="w-8 h-8 bg-green-600 rounded-full flex items-center justify-center">
                      <Mail className="h-4 w-4 text-white" />
                    </div>
                    <div>
                      <p className="text-sm font-medium text-green-900">
                        {firebaseUser.displayName || 'Gmail User'}
                      </p>
                      <p className="text-xs text-green-700">{firebaseUser.email}</p>
                    </div>
                  </div>
                </CardContent>
              </Card>
            )}

            <Button onClick={handleComplete} className="w-full">
              Continue to Dashboard
            </Button>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

