import React from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Trophy, Target, Zap, CheckCircle, TrendingUp, Calendar, Coins } from 'lucide-react';
import { SocialShare } from './social-share';

interface AchievementCardProps {
  prediction: {
    id: number;
    cryptocurrency: string;
    predictedPrice: number;
    actualPrice: number;
    accuracyScore: number;
    rewardAmount: number;
    stakeAmount: number;
    submissionTime: string;
    targetTime: string;
  };
  onViewDetails?: () => void;
}

export function AchievementCard({ prediction, onViewDetails }: AchievementCardProps) {
  const accuracyPercentage = (prediction.accuracyScore / 10000) * 100;
  const rewardMultiplier = prediction.rewardAmount / prediction.stakeAmount;
  const profitAmount = prediction.rewardAmount - prediction.stakeAmount;

  // Get achievement details
  const getAchievement = () => {
    if (accuracyPercentage >= 99.9) return {
      icon: Trophy,
      label: 'Perfect Predictor',
      color: 'bg-gradient-to-r from-yellow-400 to-yellow-600',
      textColor: 'text-yellow-600',
      description: 'Achieved near-perfect accuracy!'
    };
    if (accuracyPercentage >= 99) return {
      icon: Target,
      label: 'Sharpshooter',
      color: 'bg-gradient-to-r from-orange-400 to-orange-600',
      textColor: 'text-orange-600',
      description: 'Exceptional precision in prediction!'
    };
    if (accuracyPercentage >= 95) return {
      icon: Zap,
      label: 'Accuracy Master',
      color: 'bg-gradient-to-r from-blue-400 to-blue-600',
      textColor: 'text-blue-600',
      description: 'Outstanding market analysis!'
    };
    if (accuracyPercentage >= 90) return {
      icon: CheckCircle,
      label: 'Skilled Trader',
      color: 'bg-gradient-to-r from-green-400 to-green-600',
      textColor: 'text-green-600',
      description: 'Great trading instincts!'
    };
    return {
      icon: CheckCircle,
      label: 'Good Prediction',
      color: 'bg-gradient-to-r from-gray-400 to-gray-600',
      textColor: 'text-gray-600',
      description: 'Solid market prediction!'
    };
  };

  const achievement = getAchievement();
  const AchievementIcon = achievement.icon;

  // Format cryptocurrency
  const formatCrypto = (crypto: string) => {
    const cryptoNames: Record<string, string> = {
      'bitcoin': 'Bitcoin',
      'ethereum': 'Ethereum',
      'binancecoin': 'BNB',
      'cardano': 'Cardano',
      'solana': 'Solana',
      'chainlink': 'Chainlink',
      'polkadot': 'Polkadot',
      'litecoin': 'Litecoin',
      'matic-network': 'Polygon',
      'hyperliquid': 'Hyperliquid'
    };
    return cryptoNames[crypto] || crypto.toUpperCase();
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  return (
    <Card className="overflow-hidden border-0 shadow-md hover:shadow-lg transition-shadow">
      {/* Achievement Header */}
      <div className={`${achievement.color} p-4 text-white`}>
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-white/20 rounded-full p-2">
              <AchievementIcon className="h-6 w-6" />
            </div>
            <div>
              <h3 className="font-bold text-lg">{achievement.label}</h3>
              <p className="text-white/80 text-sm">{achievement.description}</p>
            </div>
          </div>
          <div className="text-right">
            <div className="text-2xl font-bold">{accuracyPercentage.toFixed(1)}%</div>
            <div className="text-white/80 text-sm">Accuracy</div>
          </div>
        </div>
      </div>

      <CardContent className="p-4 space-y-4">
        {/* Prediction Summary */}
        <div className="flex items-center justify-between">
          <div>
            <h4 className="font-semibold text-lg">{formatCrypto(prediction.cryptocurrency)}</h4>
            <div className="flex items-center gap-2 text-sm text-muted-foreground">
              <Calendar className="h-4 w-4" />
              {formatDate(prediction.submissionTime)}
            </div>
          </div>
          <div className="text-right">
            <div className="flex gap-2">
              <Badge variant="secondary" className={achievement.textColor}>
                {rewardMultiplier.toFixed(1)}x
              </Badge>
              <Badge variant="outline">
                +{profitAmount.toLocaleString()} NTIQ
              </Badge>
            </div>
          </div>
        </div>

        {/* Price Details */}
        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-1">
            <div className="text-sm text-muted-foreground">Predicted</div>
            <div className="font-semibold">${prediction.predictedPrice.toLocaleString()}</div>
          </div>
          <div className="space-y-1">
            <div className="text-sm text-muted-foreground">Actual</div>
            <div className="font-semibold">${prediction.actualPrice.toLocaleString()}</div>
          </div>
        </div>

        {/* Reward Details */}
        <div className="flex items-center justify-between p-3 bg-muted/50 rounded-lg">
          <div className="flex items-center gap-2">
            <Coins className="h-4 w-4 text-muted-foreground" />
            <span className="text-sm text-muted-foreground">Total Reward</span>
          </div>
          <div className="font-semibold text-green-600">
            {prediction.rewardAmount.toLocaleString()} NTIQ
          </div>
        </div>

        {/* Action Buttons */}
        <div className="flex gap-2 pt-2">
          <SocialShare 
            prediction={prediction}
            trigger={
              <Button className="flex-1" size="sm">
                Share Achievement
              </Button>
            }
          />
          {onViewDetails && (
            <Button variant="outline" size="sm" onClick={onViewDetails}>
              View Details
            </Button>
          )}
        </div>
      </CardContent>
    </Card>
  );
}

client/src/components/achievements-galle.content:
import React, { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Trophy, TrendingUp, Filter, Calendar, Award } from 'lucide-react';
import { AchievementCard } from './achievement-card';

interface Prediction {
  id: number;
  cryptocurrency: string;
  predictedPrice: number;
  actualPrice: number;
  accuracyScore: number;
  rewardAmount: number;
  stakeAmount: number;
  submissionTime: string;
  targetTime: string;
  resolved: boolean;
  claimed: boolean;
}

export function AchievementsGallery() {
  const [sortBy, setSortBy] = useState<'accuracy' | 'reward' | 'date'>('accuracy');
  const [filterBy, setFilterBy] = useState<'all' | 'perfect' | 'high' | 'medium'>('all');

  // Fetch user's successful predictions
  const { data: predictions = [], isLoading } = useQuery({
    queryKey: ['/api/predictions/user-history'],
    enabled: true,
  });

  // Filter and sort predictions
  const processedPredictions = React.useMemo(() => {
    let filtered = predictions.filter((p: Prediction) => p.resolved && p.claimed);

    // Apply filters
    if (filterBy !== 'all') {
      filtered = filtered.filter((p: Prediction) => {
        const accuracy = (p.accuracyScore / 10000) * 100;
        switch (filterBy) {
          case 'perfect': return accuracy >= 99.9;
          case 'high': return accuracy >= 95 && accuracy < 99.9;
          case 'medium': return accuracy >= 90 && accuracy < 95;
          default: return true;
        }
      });
    }

    // Apply sorting
    filtered.sort((a: Prediction, b: Prediction) => {
      switch (sortBy) {
        case 'accuracy':
          return b.accuracyScore - a.accuracyScore;
        case 'reward':
          return b.rewardAmount - a.rewardAmount;
        case 'date':
          return new Date(b.submissionTime).getTime() - new Date(a.submissionTime).getTime();
        default:
          return 0;
      }
    });

    return filtered;
  }, [predictions, sortBy, filterBy]);

  // Calculate statistics
  const stats = React.useMemo(() => {
    const totalPredictions = predictions.filter((p: Prediction) => p.resolved).length;
    const successfulPredictions = processedPredictions.length;
    const totalRewards = processedPredictions.reduce((sum: number, p: Prediction) => sum + p.rewardAmount, 0);
    const avgAccuracy = processedPredictions.length > 0 
      ? processedPredictions.reduce((sum: number, p: Prediction) => sum + p.accuracyScore, 0) / processedPredictions.length / 100
      : 0;

    return {
      totalPredictions,
      successfulPredictions,
      totalRewards,
      avgAccuracy,
      successRate: totalPredictions > 0 ? (successfulPredictions / totalPredictions) * 100 : 0
    };
  }, [predictions, processedPredictions]);

  if (isLoading) {
    return (
      <Card>
        <CardContent className="p-6">
          <div className="text-center">Loading achievements...</div>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      {/* Statistics Overview */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card>
          <CardContent className="p-4 text-center">
            <div className="text-2xl font-bold text-green-600">{stats.successfulPredictions}</div>
            <div className="text-sm text-muted-foreground">Successful Predictions</div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4 text-center">
            <div className="text-2xl font-bold text-blue-600">{stats.avgAccuracy.toFixed(1)}%</div>
            <div className="text-sm text-muted-foreground">Average Accuracy</div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4 text-center">
            <div className="text-2xl font-bold text-purple-600">{stats.totalRewards.toLocaleString()}</div>
            <div className="text-sm text-muted-foreground">Total NTIQ Earned</div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4 text-center">
            <div className="text-2xl font-bold text-orange-600">{stats.successRate.toFixed(1)}%</div>
            <div className="text-sm text-muted-foreground">Success Rate</div>
          </CardContent>
        </Card>
      </div>

      {/* Achievements Section */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <CardTitle className="flex items-center gap-2">
              <Trophy className="h-5 w-5 text-yellow-600" />
              Your Achievements
            </CardTitle>
            <div className="flex gap-2">
              <Select value={sortBy} onValueChange={(value: any) => setSortBy(value)}>
                <SelectTrigger className="w-32">
                  <SelectValue />
