import { useQuery } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Trophy, Target, Award, Star, TrendingUp, Coins } from "lucide-react";

interface Achievement {
  id: number;
  name: string;
  description: string;
  type: string;
  target: number;
  reward: number;
  icon: string;
  isActive: boolean;
}

interface UserAchievement {
  id: number;
  userId: number;
  achievementId: number;
  progress: number;
  isCompleted: boolean;
  completedAt: string | null;
  achievement: Achievement;
}

function getAchievementIcon(type: string, isCompleted: boolean) {
  const iconClass = `w-6 h-6 ${isCompleted ? 'text-yellow-500' : 'text-gray-400'}`;

  switch (type) {
    case 'prediction_count':
      return <Target className={iconClass} />;
    case 'accuracy':
      return <TrendingUp className={iconClass} />;
    case 'streak':
      return <Trophy className={iconClass} />;
    case 'rewards':
      return <Coins className={iconClass} />;
    case 'high_stake':
      return <Star className={iconClass} />;
    default:
      return <Award className={iconClass} />;
  }
}

function getAchievementTypeLabel(type: string) {
  switch (type) {
    case 'prediction_count':
      return 'Predictions';
    case 'accuracy':
      return 'Accuracy';
    case 'streak':
      return 'Win Streak';
    case 'rewards':
      return 'Rewards';
    case 'high_stake':
      return 'High Stakes';
    default:
      return 'Achievement';
  }
}

export function Achievements() {
  const { data: userAchievements = [], isLoading } = useQuery<UserAchievement[]>({
    queryKey: ["/api/achievements"],
  });

  const { data: allAchievements = [] } = useQuery<Achievement[]>({
