import { useQuery } from '@tanstack/react-query';
import { Card, CardContent } from '@/components/ui/card';
import { TrendingUp, TrendingDown, DollarSign, BarChart3 } from 'lucide-react';

interface FinancialMetricsProps {
  cryptoId: string;
  symbol: string;
}

interface CryptoMetrics {
  id: string;
  symbol: string;
  name: string;
  current_price: number;
  market_cap: number;
  market_cap_rank: number;
  volume_24h: number;
  volume_change_24h: number;
  price_change_24h: number;
  price_change_7d: number;
  price_change_30d: number;
  circulating_supply: number;
  total_supply: number;
}

export default function FinancialMetrics({ cryptoId, symbol }: FinancialMetricsProps) {
  const { data: metrics, isLoading } = useQuery<CryptoMetrics>({
    queryKey: ['/api/crypto/metrics', cryptoId],
    queryFn: () => fetch(`/api/crypto/metrics/${cryptoId}`).then(res => res.json()),
    refetchInterval: 30000, // Refresh every 30 seconds
    staleTime: 20000
  });

  const formatNumber = (num: number | undefined | null) => {
    if (num === undefined || num === null || isNaN(num)) return '$0.00';
    if (num >= 1e12) return `$${(num / 1e12).toFixed(2)}T`;
    if (num >= 1e9) return `$${(num / 1e9).toFixed(2)}B`;
    if (num >= 1e6) return `$${(num / 1e6).toFixed(2)}M`;
    if (num >= 1e3) return `$${(num / 1e3).toFixed(2)}K`;
    return `$${num.toFixed(2)}`;
  };

  const formatSupply = (num: number | undefined | null) => {
    if (num === undefined || num === null || isNaN(num)) return '0';
    if (num >= 1e12) return `${(num / 1e12).toFixed(2)}T`;
    if (num >= 1e9) return `${(num / 1e9).toFixed(2)}B`;
    if (num >= 1e6) return `${(num / 1e6).toFixed(2)}M`;
    if (num >= 1e3) return `${(num / 1e3).toFixed(2)}K`;
    return num.toLocaleString();
  };

  const calculateMonthlyVolume = (dailyVolume: number | undefined | null) => {
    if (dailyVolume === undefined || dailyVolume === null || isNaN(dailyVolume)) return 0;
    // Estimate monthly volume (30 days average)
    return dailyVolume * 30;
  };

  if (isLoading) {
    return (
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mt-6">
        {[...Array(4)].map((_, i) => (
          <Card key={i} className="bg-white/10 backdrop-blur-sm border-white/20">
            <CardContent className="p-4">
              <div className="animate-pulse">
                <div className="h-4 bg-gray-300 rounded mb-2"></div>
                <div className="h-6 bg-gray-300 rounded mb-1"></div>
                <div className="h-3 bg-gray-300 rounded"></div>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
    );
  }

  if (!metrics) return null;

  const monthlyVolume = calculateMonthlyVolume(metrics.volume_24h);
  const volumeChange = metrics.volume_change_24h || 0;

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mt-6 mb-8">
      {/* Volume Harian */}
      <Card className="bg-gradient-to-br from-blue-500/20 to-purple-600/20 backdrop-blur-sm border-white/20 hover:border-blue-400/40 transition-all duration-300">
        <CardContent className="p-4">
          <div className="flex items-center gap-2 mb-2">
            <BarChart3 className="h-4 w-4 text-blue-400" />
            <h3 className="text-sm font-medium text-gray-300">Daily Volume</h3>
          </div>
          <div className="text-xl font-bold text-white mb-1">
            {formatNumber(metrics.volume_24h)}
          </div>
          <div className={`flex items-center gap-1 text-xs ${
            volumeChange >= 0 ? 'text-green-400' : 'text-red-400'
          }`}>
            {volumeChange >= 0 ? (
              <TrendingUp className="h-3 w-3" />
            ) : (
              <TrendingDown className="h-3 w-3" />
            )}
            {Math.abs(volumeChange).toFixed(1)}%
          </div>
        </CardContent>
      </Card>

      {/* Volume Bulanan */}
      <Card className="bg-gradient-to-br from-green-500/20 to-emerald-600/20 backdrop-blur-sm border-white/20 hover:border-green-400/40 transition-all duration-300">
        <CardContent className="p-4">
          <div className="flex items-center gap-2 mb-2">
            <BarChart3 className="h-4 w-4 text-green-400" />
            <h3 className="text-sm font-medium text-gray-300">Monthly Volume</h3>
          </div>
          <div className="text-xl font-bold text-white mb-1">
            {formatNumber(monthlyVolume)}
          </div>
          <div className="text-xs text-gray-400">
            30 days estimate
          </div>
        </CardContent>
      </Card>

      {/* Market Cap */}
      <Card className="bg-gradient-to-br from-orange-500/20 to-red-600/20 backdrop-blur-sm border-white/20 hover:border-orange-400/40 transition-all duration-300">
        <CardContent className="p-4">
          <div className="flex items-center gap-2 mb-2">
            <DollarSign className="h-4 w-4 text-orange-400" />
            <h3 className="text-sm font-medium text-gray-300">Market Cap</h3>
          </div>
          <div className="text-xl font-bold text-white mb-1">
            {formatNumber(metrics.market_cap)}
          </div>
          <div className="text-xs text-gray-400">
            Rank #{metrics.market_cap_rank}
          </div>
        </CardContent>
      </Card>

      {/* Circulating Supply */}
      <Card className="bg-gradient-to-br from-purple-500/20 to-pink-600/20 backdrop-blur-sm border-white/20 hover:border-purple-400/40 transition-all duration-300">
        <CardContent className="p-4">
          <div className="flex items-center gap-2 mb-2">
            <BarChart3 className="h-4 w-4 text-purple-400" />
            <h3 className="text-sm font-medium text-gray-300">Supply</h3>
          </div>
          <div className="text-xl font-bold text-white mb-1">
            {formatSupply(metrics.circulating_supply)} {symbol}
          </div>
          <div className="text-xs text-gray-400">
            {metrics.total_supply > 0 ? (
              `Total: ${formatSupply(metrics.total_supply)} ${symbol}`
            ) : (
              'Unlimited supply'
            )}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

client/src/components/financial-wallet.t.content:
import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Wallet, Plus, Send, Copy, ExternalLink, CheckCircle, AlertCircle } from "lucide-react";
import { toast } from "@/hooks/use-toast";
import { apiRequest } from "@/lib/queryClient";

interface WalletData {
  id: number;
  walletType: string;
  chainType: string;
  walletAddress: string;
  isActive: boolean;
  isVerified: boolean;
}

interface BalanceData {
  tokenSymbol: string;
  balance: string;
  usdValue: string;
  chainType: string;
}

export function FinancialWallet() {
  const [selectedChain, setSelectedChain] = useState<string>("ethereum");
  const [showAddWallet, setShowAddWallet] = useState(false);
  const [showWithdraw, setShowWithdraw] = useState(false);
  const queryClient = useQueryClient();

  // Hardcoded supported chains untuk sementara
  const supportedChains = [
    { chainId: 'ethereum', name: 'Ethereum', symbol: 'ETH' },
    { chainId: 'bsc', name: 'BSC', symbol: 'BNB' },
    { chainId: 'polygon', name: 'Polygon', symbol: 'MATIC' },
    { chainId: 'solana', name: 'Solana', symbol: 'SOL' }
  ];

  // Query untuk mendapatkan wallet summary
  const { data: walletSummary, isLoading } = useQuery({
    queryKey: ["/api/wallet/summary"],
    refetchInterval: 5000,
    retry: false,
  });

  // Mutation untuk menambah wallet
  const addWalletMutation = useMutation({
    mutationFn: async (walletData: { walletType: string; chainType: string; walletAddress: string }) => {
      const response = await apiRequest("/api/wallet/add", {
        method: "POST",
        body: JSON.stringify(walletData),
      });
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/wallet/summary"] });
      setShowAddWallet(false);
      toast({
        title: "Wallet Added Successfully",
        description: "New wallet has been registered to the system",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to add wallet",
        variant: "destructive",
      });
    },
  });

  // Mutation untuk withdrawal
  const withdrawMutation = useMutation({
    mutationFn: async (withdrawData: { 
      walletId: number; 
      chainType: string; 
      tokenSymbol: string; 
      amount: string; 
      toAddress: string; 
    }) => {
      const response = await apiRequest("/api/wallet/withdraw", {
        method: "POST",
        body: JSON.stringify(withdrawData),
      });
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/wallet/summary"] });
      setShowWithdraw(false);
      toast({
        title: "Withdrawal Request Created",
        description: "Withdrawal request has been submitted for processing",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to create withdrawal request",
        variant: "destructive",
      });
    },
  });

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    toast({
      title: "Copied",
      description: "Address has been copied to clipboard",
    });
  };

  const formatAddress = (address: string) => {
    if (!address) return "";
    return `${address.slice(0, 6)}...${address.slice(-4)}`;
  };

  const getChainIcon = (chainType: string) => {
    const icons: { [key: string]: string } = {
      ethereum: "🔷",
      bsc: "🟡",
      polygon: "🟣",
      solana: "🌟"
    };
    return icons[chainType] || "⚡";
  };

  if (isLoading) {
    return (
      <div className="space-y-4">
        <div className="animate-pulse bg-gray-200 h-48 rounded-lg"></div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header dengan Total Value */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Wallet className="h-6 w-6" />
            Multi-Chain Wallet
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid md:grid-cols-3 gap-4">
            <div className="text-center">
              <p className="text-sm text-muted-foreground">Total USD Value</p>
              <p className="text-2xl font-bold">${walletSummary?.totalUsdValue?.toFixed(2) || "0.00"}</p>
            </div>
            <div className="text-center">
              <p className="text-sm text-muted-foreground">Active Wallets</p>
              <p className="text-2xl font-bold">{walletSummary?.wallets?.length || 0}</p>
            </div>
            <div className="text-center">
              <p className="text-sm text-muted-foreground">NTIQ Credits</p>
              <p className="text-2xl font-bold">
                {walletSummary?.credits?.find((c: any) => c.creditType === 'NTIQ')?.amount || "0"}
              </p>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Tabs untuk setiap chain */}
      <Tabs value={selectedChain} onValueChange={setSelectedChain}>
        <TabsList className="grid grid-cols-4 w-full">
          {supportedChains.map((chain) => (
            <TabsTrigger key={chain.chainId} value={chain.chainId} className="flex items-center gap-2">
              <span>{getChainIcon(chain.chainId)}</span>
              {chain.symbol}
            </TabsTrigger>
          ))}
        </TabsList>

        {supportedChains.map((chain) => (
          <TabsContent key={chain.chainId} value={chain.chainId}>
            <div className="grid md:grid-cols-2 gap-6">
              {/* Wallet List */}
              <Card>
                <CardHeader className="flex flex-row items-center justify-between">
                  <CardTitle>{chain.name} Wallets</CardTitle>
                  <Dialog open={showAddWallet} onOpenChange={setShowAddWallet}>
                    <DialogTrigger asChild>
                      <Button size="sm">
                        <Plus className="h-4 w-4 mr-2" />
                        Add Wallet
                      </Button>
                    </DialogTrigger>
                    <DialogContent>
                      <DialogHeader>
                        <DialogTitle>Add {chain.name} Wallet</DialogTitle>
                      </DialogHeader>
                      <AddWalletForm 
                        chainType={chain.chainId} 
                        onSubmit={(data) => addWalletMutation.mutate(data)}
                        isLoading={addWalletMutation.isPending}
                      />
                    </DialogContent>
                  </Dialog>
                </CardHeader>
                <CardContent>
                  <div className="space-y-3">
                    {walletSummary?.wallets
                      ?.filter((w: WalletData) => w.chainType === chain.chainId)
                      ?.map((wallet: WalletData) => (
                      <div key={wallet.id} className="flex items-center justify-between p-3 border rounded-lg">
                        <div>
                          <div className="flex items-center gap-2">
                            <Badge variant={wallet.isVerified ? "default" : "secondary"}>
                              {wallet.walletType}
                            </Badge>
                            {wallet.isVerified && <CheckCircle className="h-4 w-4 text-green-500" />}
                          </div>
                          <p className="text-sm text-muted-foreground">{formatAddress(wallet.walletAddress)}</p>
                        </div>
                        <div className="flex gap-2">
                          <Button 
                            size="sm" 
                            variant="outline"
                            onClick={() => copyToClipboard(wallet.walletAddress)}
                          >
                            <Copy className="h-4 w-4" />
                          </Button>
                          <Button size="sm" variant="outline">
                            <ExternalLink className="h-4 w-4" />
                          </Button>
                        </div>
                      </div>
                    )) || (
                      <div className="text-center py-8 text-muted-foreground">
                        No wallets added for {chain.name}
                      </div>
                    )}
                  </div>
                </CardContent>
              </Card>

              {/* Balances */}
              <Card>
                <CardHeader className="flex flex-row items-center justify-between">
                  <CardTitle>Token Balances</CardTitle>
                  <Dialog open={showWithdraw} onOpenChange={setShowWithdraw}>
                    <DialogTrigger asChild>
                      <Button size="sm">
                        <Send className="h-4 w-4 mr-2" />
                        Withdraw
                      </Button>
                    </DialogTrigger>
                    <DialogContent>
                      <DialogHeader>
                        <DialogTitle>Withdraw {chain.name}</DialogTitle>
                      </DialogHeader>
                      <WithdrawForm 
                        chainType={chain.chainId}
                        wallets={walletSummary?.wallets?.filter((w: WalletData) => w.chainType === chain.chainId) || []}
                        balances={walletSummary?.balances?.filter((b: BalanceData) => b.chainType === chain.chainId) || []}
                        onSubmit={(data) => withdrawMutation.mutate(data)}
                        isLoading={withdrawMutation.isPending}
                      />
                    </DialogContent>
                  </Dialog>
                </CardHeader>
                <CardContent>
                  <div className="space-y-3">
                    {walletSummary?.balances
                      ?.filter((b: BalanceData) => b.chainType === chain.chainId)
                      ?.map((balance: BalanceData, index: number) => (
                      <div key={index} className="flex items-center justify-between p-3 border rounded-lg">
                        <div>
                          <p className="font-medium">{balance.tokenSymbol}</p>
                          <p className="text-sm text-muted-foreground">${balance.usdValue}</p>
                        </div>
                        <div className="text-right">
                          <p className="font-medium">{parseFloat(balance.balance).toFixed(6)}</p>
                          <p className="text-sm text-muted-foreground">{balance.tokenSymbol}</p>
                        </div>
                      </div>
                    )) || (
                      <div className="text-center py-8 text-muted-foreground">
                        No token balances for {chain.name}
                      </div>
                    )}
                  </div>
                </CardContent>
              </Card>
            </div>
          </TabsContent>
        ))}
      </Tabs>

      {/* Conversion Info */}
      {/* Conversion Info & Coming Soon Notice */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <AlertCircle className="h-5 w-5 text-blue-500" />
            Multi-Chain Wallet System
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            <div className="bg-blue-50 dark:bg-blue-950/20 border border-blue-200 dark:border-blue-800 rounded-lg p-4">
              <h4 className="font-semibold text-blue-900 dark:text-blue-100 mb-2">🚀 Coming Soon</h4>
              <p className="text-blue-800 dark:text-blue-200 text-sm mb-3">
                Advanced multi-chain wallet integration for seamless deposit/buy and withdrawal management across Ethereum, BSC, Polygon, and Solana networks.
              </p>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                <div className="text-center p-2 bg-white dark:bg-gray-800 rounded border">
                  <p className="font-medium text-sm">1 ETH</p>
                  <p className="text-xs text-muted-foreground">= 1000 NTIQ</p>
                </div>
                <div className="text-center p-2 bg-white dark:bg-gray-800 rounded border">
