    try {
      await navigator.clipboard.writeText(text);
      setCopiedItem(itemType);
      toast({
        title: "Copied successfully",
        description: `${itemType} copied to clipboard`,
      });

      // Reset icon after 2 seconds
      setTimeout(() => {
        setCopiedItem(null);
      }, 2000);
