import { useQuery } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Activity, TrendingUp, Swords, Crown, Zap, Clock, CheckCircle2 } from "lucide-react";
import { formatDistanceToNow } from "date-fns";
import { EnhancedSkeleton } from "@/components/enhanced-skeleton";

interface ActivityItem {
  id: string;
  type: 'prediction' | 'battle_win' | 'battle_created' | 'survival_win' | 'achievement';
  username: string;
  description: string;
  amount?: number;
  cryptocurrency?: string;
  timestamp: string;
  icon: string;
  color: string;
}

interface ActivePrediction {
  id: number;
  userId: number;
  cryptocurrency: string;
  predictedPrice: string;
  stakeAmount: number;
  targetTime: string;
  createdAt: string;
  currentPrice: string;
  timeLeft: number;
  username?: string;
  cryptocurrencyName?: string;
}

const iconMap = {
  TrendingUp,
  TrendingDown: TrendingUp,
  Swords,
  Crown,
  Zap,
  Activity,
};

export function LiveActivityFeed() {
  // Get completed activities
  const { data: activities = [], isLoading: isLoadingActivities } = useQuery<ActivityItem[]>({
    queryKey: ["/api/activities/live"],
    refetchInterval: 3000,
    refetchIntervalInBackground: true,
    staleTime: 0,
  });

  // Get active predictions from all users
  const { data: activePredictions = [], isLoading: isLoadingActive } = useQuery<ActivePrediction[]>({
    queryKey: ["/api/predictions/live-feed"],
    refetchInterval: 2000,
    refetchIntervalInBackground: true,
    staleTime: 0,
  });

  const isLoading = isLoadingActivities || isLoadingActive;

  if (isLoading) {
    return (
      <div className="bg-surface rounded-xl p-6 border border-surface-light">
        <div className="flex items-center justify-center mb-6">
          <Activity className="text-primary mr-2 animate-pulse" size={18} />
          <h3 className="text-lg font-bold">Live Activity Feed</h3>
          <div className="ml-2 w-2 h-2 bg-primary rounded-full animate-pulse"></div>
        </div>
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <div className="space-y-3">
            <h4 className="font-semibold text-slate-200 mb-3 flex items-center">
              <CheckCircle2 className="text-green-500 mr-2 animate-pulse" size={16} />
              Completed Activities
            </h4>
            <EnhancedSkeleton type="activity" count={3} />
          </div>
          <div className="space-y-3">
            <h4 className="font-semibold text-slate-200 mb-3 flex items-center">
              <Clock className="text-orange-500 mr-2 animate-pulse" size={16} />
              Ongoing Activities
            </h4>
            <EnhancedSkeleton type="activity" count={3} />
          </div>
        </div>
      </div>
    );
  }

  const formatTimeLeft = (seconds: number): string => {
    // Handle invalid values (undefined, null, NaN)
    if (seconds === undefined || seconds === null || isNaN(seconds) || seconds <= 0) {
      return "Expired";
    }

    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    const secs = seconds % 60;

    if (hours > 0) return `${hours}h ${minutes}m`;
    if (minutes > 0) return `${minutes}m ${secs}s`;
    return `${secs}s`;
  };

  return (
    <div className="bg-surface rounded-xl p-6 border border-surface-light">
      <div className="flex items-center justify-center mb-6">
        <Activity className="text-primary mr-2" size={18} />
        <h3 className="text-lg font-bold">Live Activity Feed</h3>
        <div className="ml-2 w-2 h-2 bg-green-500 rounded-full animate-pulse"></div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Left Column - Completed Activities */}
        <div className="space-y-4">
          <div className="flex items-center space-x-2 mb-4">
            <CheckCircle2 className="text-green-500" size={16} />
            <h4 className="font-semibold text-slate-200">Completed Activities</h4>
          </div>

          <div className="max-h-80 overflow-hidden relative">
            {activities.length === 0 ? (
              <div className="text-center py-4">
                <div className="relative mb-3">
                  <div className="w-10 h-10 bg-gradient-to-br from-green-500 to-blue-600 rounded-xl mx-auto flex items-center justify-center shadow-lg">
                    <CheckCircle2 className="text-white" size={20} />
                  </div>
                  <div className="absolute -top-1 -right-1 w-3 h-3 bg-green-400 rounded-full animate-pulse shadow-md"></div>
                </div>
                <p className="text-sm font-medium text-white mb-2">Ready for Action!</p>
                <p className="text-xs text-slate-400">Completed rewards appear here</p>
              </div>
            ) : (
              <div className="space-y-3">
                {activities.map((activity, index) => {
                  const IconComponent = iconMap[activity.icon as keyof typeof iconMap] || Activity;
                  return (
                  <div
                    key={activity.id}
                    className="flex items-start space-x-3 p-3 rounded-lg bg-slate-800/30 border border-slate-700/50 hover:bg-slate-800/50 transition-colors"
                  >
                    <div className={`w-8 h-8 rounded-full flex items-center justify-center ${activity.color} flex-shrink-0 mt-0.5`}>
                      <IconComponent className="w-4 h-4 text-white" />
                    </div>

                    <div className="flex-1 min-w-0">
                      <div className="flex items-center space-x-2">
                        <span className="font-medium text-slate-200 truncate text-sm">
                          {activity.username}
                        </span>
                        {activity.type === 'battle_win' && (
                          <Badge variant="secondary" className="bg-yellow-600/20 text-yellow-400 text-xs">
                            Battle
                          </Badge>
                        )}
                        {activity.type === 'survival_win' && (
                          <Badge variant="secondary" className="bg-purple-600/20 text-purple-400 text-xs">
                            Survival
                          </Badge>
                        )}
                      </div>

                      <p className="text-xs text-slate-300 mt-1">
                        {activity.description}
                        {activity.amount && (
                          <span className="font-semibold text-green-400 ml-1">
                            +{activity.amount} NTIQ
                          </span>
                        )}
                      </p>

                      <p className="text-xs text-slate-500 mt-1">
                        {formatDistanceToNow(new Date(activity.timestamp), { addSuffix: true })}
                      </p>
                    </div>
                  </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>

        {/* Right Column - Ongoing Activities */}
        <div className="space-y-4">
          <div className="flex items-center space-x-2 mb-4">
            <Clock className="text-orange-500" size={16} />
            <h4 className="font-semibold text-slate-200">Ongoing Activities</h4>
          </div>

          <div className="max-h-80 overflow-hidden relative">
            {activePredictions.length === 0 ? (
              <div className="text-center py-4">
                <div className="relative mb-3">
                  <div className="w-10 h-10 bg-gradient-to-br from-orange-500 to-red-600 rounded-xl mx-auto flex items-center justify-center shadow-lg">
                    <Clock className="text-white" size={20} />
                  </div>
                  <div className="absolute -top-1 -right-1 w-3 h-3 bg-orange-400 rounded-full animate-pulse shadow-md"></div>
                </div>
                <p className="text-sm font-medium text-white mb-2">Quiet Moment</p>
                <p className="text-xs text-slate-400">Active predictions will show here</p>
              </div>
            ) : (
              <div className="space-y-3">
                {activePredictions.slice(0, 8).map((prediction, index) => (
                  <div
                    key={prediction.id}
                    className="flex items-start space-x-3 p-3 rounded-lg bg-orange-800/20 border border-orange-700/50 hover:bg-orange-800/30 transition-colors"
                  >
                    <div className="w-8 h-8 rounded-full flex items-center justify-center bg-orange-600 flex-shrink-0 mt-0.5">
                      <Clock className="w-4 h-4 text-white" />
                    </div>

                    <div className="flex-1 min-w-0">
                      <div className="flex items-center space-x-2">
                        <span className="font-medium text-slate-200 truncate text-sm">
                          {prediction.username || `User #${prediction.userId}`}
                        </span>
                        <Badge variant="secondary" className="bg-orange-600/20 text-orange-400 text-xs">
                          Predicting
                        </Badge>
                      </div>

                      <p className="text-xs text-slate-300 mt-1">
                        {prediction.cryptocurrencyName || prediction.cryptocurrency} prediction
                        <span className="font-semibold text-blue-400 ml-1">
                          ${parseFloat(prediction.predictedPrice).toFixed(2)}
                        </span>
                      </p>

                      <div className="flex items-center justify-between mt-1">
                        <p className="text-xs text-slate-500">
                          Stake: {prediction.stakeAmount} NTIQ
                        </p>
                        <p className="text-xs text-orange-400 font-medium">
                          {formatTimeLeft(prediction.timeLeft)}
                        </p>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>

      <div className="mt-4 text-center">
        <p className="text-xs text-slate-500">
          Live updates • Last updated {formatDistanceToNow(new Date(), { addSuffix: true })}
        </p>
      </div>
    </div>
  );
}

client/src/components/live-prediction-fe.content:
import { useState, useEffect } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { TrendingUp, MessageCircle, Heart, Users, Clock, Target } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { useToast } from "@/hooks/use-toast";

interface LivePrediction {
  id: number;
  userId: number;
  username: string;
  cryptocurrency: string;
  predictedPrice: number;
  currentPrice: number;
  stake: number;
  timeframe: string;
  createdAt: string;
  reactions: PredictionReaction[];
  comments: PredictionComment[];
  _count: {
    reactions: number;
    comments: number;
  };
}

interface PredictionReaction {
  id: number;
  userId: number;
  username: string;
  type: 'like' | 'fire' | 'rocket' | 'thinking';
  createdAt: string;
}

interface PredictionComment {
  id: number;
  userId: number;
  username: string;
  content: string;
  createdAt: string;
}

interface TrendingCrypto {
  cryptocurrency: string;
  predictionCount: number;
  totalStake: number;
  averagePrice: number;
}

// Dynamic function to get crypto image from live API data
function getCryptoImageUrl(cryptoId: string, cryptoPrices: any[]): string {
  const cryptoData = cryptoPrices?.find(crypto => crypto.id === cryptoId);
  return cryptoData?.image || `https://coin-images.coingecko.com/coins/images/1/large/${cryptoId}.png`;
}

function formatTimeAgo(dateString: string): string {
  const date = new Date(dateString);
  const now = new Date();
  const diffInMs = now.getTime() - date.getTime();
  const diffInMinutes = Math.floor(diffInMs / (1000 * 60));

  if (diffInMinutes < 1) return 'just now';
  if (diffInMinutes < 60) return `${diffInMinutes}m ago`;

  const diffInHours = Math.floor(diffInMinutes / 60);
  if (diffInHours < 24) return `${diffInHours}h ago`;

  const diffInDays = Math.floor(diffInHours / 24);
  return `${diffInDays}d ago`;
}

const reactionEmojis = {
  like: '👍',
  fire: '🔥',
  rocket: '🚀',
  thinking: '🤔'
};

export function LivePredictionFeed() {
  const [selectedTab, setSelectedTab] = useState<'feed' | 'trending'>('feed');
  const [commentInputs, setCommentInputs] = useState<Record<number, string>>({});
  const { toast } = useToast();
  const queryClient = useQueryClient();

  // Get real-time crypto prices for logo display
  const { data: cryptoPrices = [] } = useQuery<any[]>({
    queryKey: ["/api/crypto/prices"],
    refetchInterval: 15000, // Reduced to 15 seconds to prevent rate limiting
    staleTime: 10000, // 10 seconds
    retry: 2, // Retry failed requests
  });

  // Get live predictions feed
  const { data: livePredictions = [], isLoading: feedLoading } = useQuery<LivePrediction[]>({
    queryKey: ["/api/predictions/live-feed"],
    refetchInterval: 10000, // Reduced to 10 seconds to prevent rate limiting
    staleTime: 5000, // 5 seconds
    retry: 2, // Retry failed requests
  });

  // Get trending cryptocurrencies
  const { data: trendingCryptos = [], isLoading: trendingLoading } = useQuery<TrendingCrypto[]>({
    queryKey: ["/api/predictions/trending"],
    refetchInterval: 20000, // Reduced to 20 seconds to prevent rate limiting
    staleTime: 10000, // 10 seconds
  });

  // Add reaction mutation
  const addReactionMutation = useMutation({
    mutationFn: async ({ predictionId, type }: { predictionId: number; type: string }) => {
      const response = await fetch('/api/predictions/react', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ predictionId, type }),
      });
      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.message || 'Failed to add reaction');
      }
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/predictions/live-feed"] });
      toast({
        title: "Reaction added!",
        description: "Your reaction has been added to the prediction.",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to add reaction",
        variant: "destructive",
      });
    }
  });

  // Add comment mutation
  const addCommentMutation = useMutation({
    mutationFn: async ({ predictionId, content }: { predictionId: number; content: string }) => {
      const response = await fetch('/api/predictions/comment', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ predictionId, content }),
      });
      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.message || 'Failed to add comment');
      }
      return response.json();
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ["/api/predictions/live-feed"] });
      setCommentInputs(prev => ({ ...prev, [variables.predictionId]: '' }));
      toast({
        title: "Comment added!",
        description: "Your comment has been posted.",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to add comment",
        variant: "destructive",
      });
    }
  });

  const handleReaction = (predictionId: number, type: string) => {
    addReactionMutation.mutate({ predictionId, type });
  };

  const handleComment = (predictionId: number) => {
    const content = commentInputs[predictionId]?.trim();
    if (content) {
      addCommentMutation.mutate({ predictionId, content });
    }
  };

  const calculatePriceChangePercent = (predicted: number, current: number): number => {
    return ((predicted - current) / current) * 100;
  };

  return (
    <div className="bg-surface rounded-xl p-6 border border-surface-light">
      <div className="flex items-center justify-between mb-6">
        <h3 className="text-xl font-bold flex items-center">
          <TrendingUp className="text-primary mr-2" size={20} />
          Live Prediction Feed
        </h3>

        <div className="flex space-x-2">
          <Button
            variant={selectedTab === 'feed' ? 'default' : 'outline'}
            size="sm"
            onClick={() => setSelectedTab('feed')}
          >
            Live Feed
          </Button>
          <Button
            variant={selectedTab === 'trending' ? 'default' : 'outline'}
            size="sm"
            onClick={() => setSelectedTab('trending')}
          >
            Trending
          </Button>
        </div>
      </div>

      {selectedTab === 'feed' && (
        <div className="space-y-4">
          {feedLoading ? (
            <div className="text-center py-8 text-slate-400">
              <div className="animate-spin w-8 h-8 border-2 border-primary border-t-transparent rounded-full mx-auto mb-2"></div>
              <p>Loading live predictions...</p>
            </div>
          ) : livePredictions.length === 0 ? (
            <div className="text-center py-8 text-slate-400">
              <Target className="mx-auto mb-2" size={32} />
              <p>No live predictions yet</p>
              <p className="text-sm">Be the first to make a prediction!</p>
            </div>
          ) : (
            livePredictions.map((prediction) => {
              const priceChange = calculatePriceChangePercent(prediction.predictedPrice, prediction.currentPrice);
              const isPositive = priceChange > 0;

              return (
                <Card key={prediction.id} className="bg-surface-light border-slate-600">
                  <CardContent className="p-4">
                    {/* Prediction Header */}
                    <div className="flex items-center justify-between mb-3">
                      <div className="flex items-center space-x-3">
                        <div className="relative w-8 h-8 flex-shrink-0">
                          <img 
                            src={getCryptoImageUrl(prediction.cryptocurrency, cryptoPrices || [])}
                            alt={prediction.cryptocurrency}
                            className="w-8 h-8 rounded-full object-cover"
                            onError={(e) => {
                              const target = e.target as HTMLImageElement;
                              const fallback = target.nextElementSibling as HTMLElement;
                              if (fallback) {
                                target.style.display = 'none';
                                fallback.style.display = 'flex';
                              }
                            }}
                          />
                          <div className="w-8 h-8 bg-primary rounded-full hidden items-center justify-center text-white font-bold text-xs">
                            {prediction.cryptocurrency.charAt(0).toUpperCase()}
                          </div>
                        </div>
                        <div>
                          <p className="font-semibold">@{prediction.username}</p>
                          <p className="text-sm text-slate-400 flex items-center">
                            <Clock size={12} className="mr-1" />
                            {formatTimeAgo(prediction.createdAt)}
                          </p>
                        </div>
                      </div>
                      <Badge variant={prediction.timeframe === '1h' ? 'default' : prediction.timeframe === '6h' ? 'secondary' : 'outline'}>
                        {prediction.timeframe}
                      </Badge>
                    </div>

                    {/* Prediction Details */}
                    <div className="bg-surface rounded-lg p-3 mb-3">
                      <div className="flex items-center justify-between mb-2">
                        <span className="text-sm font-medium uppercase">{prediction.cryptocurrency}</span>
                        <span className="text-sm text-slate-400">{prediction.stake} NTIQ stake</span>
                      </div>
                      <div className="flex items-center justify-between">
                        <div>
                          <p className="text-xs text-slate-400">Predicted</p>
                          <p className="font-bold">${prediction.predictedPrice.toFixed(4)}</p>
                        </div>
                        <div className="text-center">
                          <p className={`text-sm font-bold ${isPositive ? 'text-green-400' : 'text-red-400'}`}>
                            {isPositive ? '+' : ''}{priceChange.toFixed(2)}%
                          </p>
                        </div>
                        <div className="text-right">
                          <p className="text-xs text-slate-400">Current</p>
                          <p className="font-bold">${prediction.currentPrice.toFixed(4)}</p>
                        </div>
                      </div>
                    </div>

                    {/* Reactions */}
                    <div className="flex items-center justify-between mb-3">
                      <div className="flex space-x-1">
                        {Object.entries(reactionEmojis).map(([type, emoji]) => (
                          <Button
                            key={type}
                            variant="ghost"
                            size="sm"
                            className="h-8 px-2 hover:bg-surface"
                            onClick={() => handleReaction(prediction.id, type)}
                            disabled={addReactionMutation.isPending}
                          >
                            <span className="mr-1">{emoji}</span>
                            <span className="text-xs">
                              {prediction.reactions.filter(r => r.type === type).length}
                            </span>
                          </Button>
                        ))}
                      </div>
                      <div className="flex items-center text-sm text-slate-400 space-x-3">
                        <span className="flex items-center">
                          <Heart size={14} className="mr-1" />
                          {prediction._count.reactions}
                        </span>
                        <span className="flex items-center">
                          <MessageCircle size={14} className="mr-1" />
                          {prediction._count.comments}
                        </span>
                      </div>
                    </div>

                    {/* Comments */}
                    {prediction.comments.length > 0 && (
                      <div className="space-y-2 mb-3">
                        {prediction.comments.slice(0, 2).map((comment) => (
                          <div key={comment.id} className="text-sm">
                            <span className="font-semibold">@{comment.username}</span>
                            <span className="ml-2">{comment.content}</span>
                            <span className="ml-2 text-xs text-slate-400">
                              {formatTimeAgo(comment.createdAt)}
                            </span>
                          </div>
                        ))}
                        {prediction.comments.length > 2 && (
                          <p className="text-xs text-slate-400">
                            View all {prediction.comments.length} comments
                          </p>
                        )}
                      </div>
                    )}

                    {/* Add Comment */}
                    <div className="flex space-x-2">
                      <Input
                        placeholder="Add a comment..."
                        value={commentInputs[prediction.id] || ''}
                        onChange={(e) => setCommentInputs(prev => ({
                          ...prev,
                          [prediction.id]: e.target.value
                        }))}
                        onKeyPress={(e) => {
                          if (e.key === 'Enter') {
                            handleComment(prediction.id);
                          }
                        }}
                        className="flex-1"
                      />
                      <Button
                        size="sm"
                        onClick={() => handleComment(prediction.id)}
                        disabled={!commentInputs[prediction.id]?.trim() || addCommentMutation.isPending}
                      >
                        Post
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              );
            })
          )}
        </div>
      )}

      {selectedTab === 'trending' && (
        <div className="space-y-4">
          {trendingLoading ? (
            <div className="text-center py-8 text-slate-400">
              <div className="animate-spin w-8 h-8 border-2 border-primary border-t-transparent rounded-full mx-auto mb-2"></div>
              <p>Loading trending cryptocurrencies...</p>
            </div>
          ) : trendingCryptos.length === 0 ? (
            <div className="text-center py-8 text-slate-400">
              <TrendingUp className="mx-auto mb-2" size={32} />
              <p>No trending data yet</p>
              <p className="text-sm">Start making predictions to see trends!</p>
            </div>
          ) : (
            trendingCryptos.map((crypto, index) => (
              <Card key={crypto.cryptocurrency} className="bg-surface-light border-slate-600">
                <CardContent className="p-4">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center space-x-3">
                      <div className="flex items-center justify-center w-8 h-8 bg-primary rounded-full text-white font-bold text-sm">
                        #{index + 1}
                      </div>
                      <div className="relative w-8 h-8 flex-shrink-0">
                        <img 
                          src={getCryptoImageUrl(crypto.cryptocurrency, cryptoPrices || [])}
                          alt={crypto.cryptocurrency}
                          className="w-8 h-8 rounded-full object-cover"
                          onError={(e) => {
                            const target = e.target as HTMLImageElement;
                            const fallback = target.nextElementSibling as HTMLElement;
                            if (fallback) {
                              target.style.display = 'none';
                              fallback.style.display = 'flex';
                            }
                          }}
                        />
                        <div className="w-8 h-8 bg-primary rounded-full hidden items-center justify-center text-white font-bold text-xs">
                          {crypto.cryptocurrency.charAt(0).toUpperCase()}
                        </div>
                      </div>
                      <div>
                        <p className="font-semibold uppercase">{crypto.cryptocurrency}</p>
                        <p className="text-sm text-slate-400">Avg: ${crypto.averagePrice.toFixed(4)}</p>
                      </div>
                    </div>
                    <div className="text-right">
                      <div className="flex items-center text-sm font-medium mb-1">
                        <Users size={14} className="mr-1" />
                        {crypto.predictionCount} predictions
                      </div>
                      <p className="text-xs text-slate-400">{crypto.totalStake} NTIQ total stake</p>
                    </div>
                  </div>
                </CardContent>
              </Card>
            ))
          )}
        </div>
      )}
    </div>
  );
}

client/src/components/live-prices.tsx.content:
import React from "react";
import { useQuery } from "@tanstack/react-query";
import { TrendingUp, TrendingDown, ChartLine } from "lucide-react";
import type { CryptoPrice } from "@/types";

function getValidImageUrl(crypto: CryptoPrice): string {
  // Use image from API/database directly - no more manual mappings needed
  return crypto.image || '';
}

function getCryptoIcon(id: string): string {
  const icons: Record<string, string> = {
    bitcoin: "₿",
    ethereum: "Ξ",
    binancecoin: "BNB",
    cardano: "ADA",
    solana: "SOL",
    aave: "AAVE",
    litecoin: "LTC",
    hyperliquid: "HYPE",
    "avalanche-2": "AVAX",
    "matic-network": "MATIC",
    monero: "XMR",
    uniswap: "UNI",
    ripple: "XRP",
    bittensor: "TAO",
    polkadot: "DOT",
    chainlink: "LINK",
  };
  return icons[id] || id.toUpperCase().slice(0, 4);
}

function getCryptoColor(id: string): string {
  const colors: Record<string, string> = {
    bitcoin: "bg-orange-500",
    ethereum: "bg-blue-500",
    binancecoin: "bg-yellow-500",
    cardano: "bg-blue-600",
    solana: "bg-purple-500",
    aave: "bg-purple-600",
    litecoin: "bg-gray-500",
    hyperliquid: "bg-green-500",
    "avalanche-2": "bg-red-500",
    "matic-network": "bg-purple-700",
    monero: "bg-orange-600",
    uniswap: "bg-pink-500",
    ripple: "bg-blue-400",
    bittensor: "bg-green-600",
    polkadot: "bg-pink-600",
    chainlink: "bg-blue-700",
  };
  return colors[id] || "bg-gray-500";
}

interface LivePricesProps {
  onCryptoSelect?: (crypto: CryptoPrice) => void;
  onPredictClick?: (cryptoId: string) => void;
}

export function LivePrices({ onCryptoSelect, onPredictClick }: LivePricesProps) {
  console.log("🔍 [LIVE-PRICES-INIT] Live Prices component rendered/re-rendered");

  // REAL-TIME PRICES - Synchronized with other components
  const { data: prices = [], isLoading, dataUpdatedAt, isFetching } = useQuery<CryptoPrice[]>({
    queryKey: ["/api/crypto/pyth-prices"], 
    refetchInterval: 1000, // Same as Active Predictions and Battles - 1 second refresh
    refetchIntervalInBackground: true, // Enable background updates
    staleTime: 0, // Always consider data stale to ensure fresh updates
    retry: 3,
    refetchOnWindowFocus: true, // Enable refresh on window focus for consistency
    refetchOnMount: true, // Fetch on component mount
    placeholderData: (previousData) => previousData, // Keep previous data during refresh
  });

  console.log("🔍 [LIVE-PRICES-QUERY] Query state:", { isLoading, isFetching, pricesLength: prices?.length });


  // Add visual indicator for when data was last updated
  const lastUpdate = new Date(dataUpdatedAt).toLocaleTimeString();

  // Sort prices by market cap (highest price first) - memoize to prevent unnecessary re-sorts
  const sortedPrices = React.useMemo(() => {
    console.log("🔍 [LIVE-PRICES-DEBUG] Raw prices received:", prices);
    console.log("🔍 [LIVE-PRICES-DEBUG] Prices length:", prices?.length);
    console.log("🔍 [LIVE-PRICES-DEBUG] Is array?", Array.isArray(prices));

    if (!prices || !Array.isArray(prices) || prices.length === 0) {
      console.log("🔴 [LIVE-PRICES-DEBUG] No valid prices data - returning empty array");
      return [];
    }

    const sorted = [...prices].sort((a, b) => b.current_price - a.current_price);
    console.log("✅ [LIVE-PRICES-DEBUG] Sorted prices:", sorted.length, "items");
    return sorted;
  }, [prices]);

  // Only show skeleton on very first load when no data exists
  if (isLoading && sortedPrices.length === 0) {
    return (
      <div className="bg-surface rounded-lg p-2 border border-surface-light">
        <h3 className="text-base font-bold mb-3 flex items-center">
          <ChartLine className="text-success mr-2" size={16} />
          Live Prices
        </h3>
        <div className="flex gap-1.5 overflow-x-auto scrollbar-thin scrollbar-track-surface-light scrollbar-thumb-primary pb-2">
          {[...Array(14)].map((_, i) => (
            <div key={i} className="crypto-card px-3 py-2 bg-surface-light rounded-md animate-pulse flex-shrink-0">
              <div className="w-16 h-14 bg-slate-600 rounded"></div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="bg-surface rounded-lg p-1 sm:p-2 border border-surface-light">
      <div className="flex items-center justify-between mb-2 sm:mb-3">
        <h3 className="text-sm sm:text-base font-bold flex items-center">
          <ChartLine className="text-success mr-1 sm:mr-2" size={14} />
          <span className="hidden sm:inline">Live Prices</span>
          <span className="sm:hidden">Prices</span>
          <span className="ml-1 sm:ml-2 text-xs bg-gradient-to-r from-purple-500 to-blue-500 text-white px-1 sm:px-2 py-0.5 rounded-full font-medium">
            Pyth
          </span>
        </h3>
        <div className="flex items-center text-xs text-green-400">
          <div className={`w-1.5 h-1.5 rounded-full mr-1 ${isFetching ? 'bg-orange-400 animate-spin' : 'bg-green-400 animate-pulse'}`}></div>
          REAL-TIME {lastUpdate}
        </div>
      </div>

      {/* Scrollable horizontal list */}
      <div className="relative">
        <div 
          className="flex gap-1.5 overflow-x-auto scrollbar-thin scrollbar-track-surface-light scrollbar-thumb-primary hover:scrollbar-thumb-primary/80 pb-2"
          style={{
            scrollbarWidth: 'thin',
            msOverflowStyle: 'auto'
          }}
        >
          {sortedPrices.map((crypto) => {
            const isPositive = crypto.price_change_percentage_24h >= 0;

            return (
              <div 
                key={crypto.id} 
                className="crypto-card px-3 py-2 bg-surface-light rounded-md transition-all duration-200 cursor-pointer hover:bg-slate-700 hover:scale-105 flex-shrink-0"
                onClick={() => onCryptoSelect?.(crypto)}
              >
                <div className="flex flex-col items-center space-y-1 min-w-0">
                  {/* Crypto logo and symbol */}
                  <div className="relative w-5 h-5 flex-shrink-0">
                    {(() => {
                      const validImageUrl = getValidImageUrl(crypto);
                      if (validImageUrl) {
                        return (
                          <img 
                            src={validImageUrl} 
                            alt={crypto.name}
                            className="w-5 h-5 rounded-full object-cover"
                            onError={(e) => {
                              const target = e.target as HTMLImageElement;
                              const fallback = target.nextElementSibling as HTMLElement;
                              if (fallback) {
                                target.style.display = 'none';
                                fallback.style.display = 'flex';
                              }
                            }}
                          />
                        );
                      }
                      return null;
                    })()}
                    {/* Fallback removed - only show logo images, no text fallback */}
                  </div>

                  {/* Symbol */}
                  <p className="font-semibold text-xs whitespace-nowrap">{crypto.symbol}</p>

                  {/* Price */}
                  <p className="font-medium text-xs whitespace-nowrap">${crypto.current_price.toFixed(2)}</p>

                  {/* Change percentage */}
                  <div className="flex items-center space-x-0.5">
                    {isPositive ? (
                      <TrendingUp className="text-success" size={8} />
                    ) : (
                      <TrendingDown className="text-error" size={8} />
                    )}
                    <span className={`text-xs font-medium whitespace-nowrap ${isPositive ? "text-success" : "text-error"}`}>
                      {isPositive ? "+" : ""}{crypto.price_change_percentage_24h.toFixed(1)}%
                    </span>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

client/src/components/loyalty-tier.tsx.content:
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Crown, Star, Zap, Gift, Shield, Clock, TrendingUp } from "lucide-react";
import { useQuery } from "@tanstack/react-query";

interface TierInfo {
  tierName: string;
  minEarnings: number;
  maxEarnings: number | null;
  rewardMultiplier: number;
  cashbackPercentage: number;
  monthlyBonus: number;
  freeInsuranceDaily: number;
  prioritySupport: boolean;
  earlyAccess: boolean;
  personalManager: boolean;
}

interface UserTierData {
  currentTier: string;
  lifetimeEarnings: number;
  nextTier: string | null;
  nextTierRequirement: number | null;
  progressPercentage: number;
  currentBenefits: TierInfo;
  nextTierBenefits: TierInfo | null;
}

const tierColors = {
  bronze: "from-orange-600 to-amber-700",
  silver: "from-gray-400 to-slate-500", 
  gold: "from-yellow-400 to-yellow-600",
  platinum: "from-purple-400 to-pink-500"
};

const tierIcons = {
  bronze: Crown,
  silver: Star,
  gold: Zap,
  platinum: Gift
};

export function LoyaltyTier() {
  const { data: tierData, isLoading } = useQuery<UserTierData>({
    queryKey: ['/api/user/tier'],
    refetchInterval: 30000, // Refresh every 30 seconds
  });

  if (isLoading || !tierData) {
    return (
      <Card className="relative overflow-hidden">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Crown className="h-5 w-5" />
            Loyalty Tier
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            <div className="h-4 bg-gray-200 rounded animate-pulse"></div>
            <div className="h-4 bg-gray-200 rounded animate-pulse"></div>
            <div className="h-4 bg-gray-200 rounded animate-pulse"></div>
          </div>
        </CardContent>
      </Card>
    );
  }

  const TierIcon = tierIcons[tierData.currentTier as keyof typeof tierIcons] || Crown;
  const tierGradient = tierColors[tierData.currentTier as keyof typeof tierColors];

  return (
    <div className="space-y-6">
      {/* Current Tier Status */}
      <Card className="relative overflow-hidden">
        <div className={`absolute inset-0 bg-gradient-to-r ${tierGradient} opacity-10`}></div>
        <CardHeader className="relative">
          <CardTitle className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className={`p-2 rounded-lg bg-gradient-to-r ${tierGradient}`}>
                <TierIcon className="h-6 w-6 text-white" />
              </div>
              <div>
                <h3 className="text-lg font-bold capitalize">{tierData.currentTier} Tier</h3>
                <p className="text-sm text-muted-foreground">
                  {tierData.lifetimeEarnings.toLocaleString()} NTIQ Lifetime Earnings
                </p>
              </div>
            </div>
            <Badge variant="secondary" className={`bg-gradient-to-r ${tierGradient} text-white border-0`}>
              {tierData.currentBenefits.rewardMultiplier}x Multiplier
            </Badge>
          </CardTitle>
        </CardHeader>
        <CardContent className="relative space-y-4">
          {/* Progress to Next Tier */}
          {tierData.nextTier && (
            <div className="space-y-2">
              <div className="flex justify-between text-sm">
                <span>Progress to {tierData.nextTier}</span>
                <span className="font-medium">{tierData.progressPercentage}%</span>
              </div>
              <Progress value={tierData.progressPercentage} className="h-2" />
              <p className="text-xs text-muted-foreground">
                Need {(tierData.nextTierRequirement! - tierData.lifetimeEarnings).toLocaleString()} more NTIQ
              </p>
            </div>
          )}

          {/* Current Benefits */}
          <div className="grid grid-cols-2 gap-3 pt-4 border-t">
            <div className="flex items-center gap-2 text-sm">
              <TrendingUp className="h-4 w-4 text-green-500" />
              <span>{(tierData.currentBenefits.rewardMultiplier * 100 - 100)}% Bonus Rewards</span>
            </div>
            <div className="flex items-center gap-2 text-sm">
              <Shield className="h-4 w-4 text-blue-500" />
              <span>{tierData.currentBenefits.cashbackPercentage}% Cashback</span>
            </div>
            {tierData.currentBenefits.monthlyBonus > 0 && (
              <div className="flex items-center gap-2 text-sm">
                <Gift className="h-4 w-4 text-purple-500" />
                <span>{tierData.currentBenefits.monthlyBonus} NTIQ/month</span>
              </div>
            )}
            {tierData.currentBenefits.freeInsuranceDaily > 0 && (
              <div className="flex items-center gap-2 text-sm">
                <Clock className="h-4 w-4 text-orange-500" />
                <span>{tierData.currentBenefits.freeInsuranceDaily} Free Insurance/day</span>
              </div>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Next Tier Preview */}
      {tierData.nextTier && tierData.nextTierBenefits && (
        <Card>
          <CardHeader>
            <CardTitle className="text-lg">
              Unlock {tierData.nextTier} Tier Benefits
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-3">
                <div className="flex items-center gap-2">
                  <TrendingUp className="h-4 w-4 text-green-500" />
                  <span className="text-sm">
                    {(tierData.nextTierBenefits.rewardMultiplier * 100 - 100)}% Bonus Rewards
                    <Badge variant="outline" className="ml-2 text-xs">
                      +{((tierData.nextTierBenefits.rewardMultiplier - tierData.currentBenefits.rewardMultiplier) * 100).toFixed(0)}%
                    </Badge>
                  </span>
                </div>
                <div className="flex items-center gap-2">
                  <Shield className="h-4 w-4 text-blue-500" />
                  <span className="text-sm">
                    {tierData.nextTierBenefits.cashbackPercentage}% Cashback
                    <Badge variant="outline" className="ml-2 text-xs">
                      +{(tierData.nextTierBenefits.cashbackPercentage - tierData.currentBenefits.cashbackPercentage).toFixed(1)}%
                    </Badge>
                  </span>
                </div>
              </div>
              <div className="space-y-3">
                {tierData.nextTierBenefits.monthlyBonus > 0 && (
                  <div className="flex items-center gap-2">
                    <Gift className="h-4 w-4 text-purple-500" />
                    <span className="text-sm">
                      {tierData.nextTierBenefits.monthlyBonus} NTIQ/month
                      {tierData.currentBenefits.monthlyBonus === 0 && (
                        <Badge variant="outline" className="ml-2 text-xs text-green-600">NEW!</Badge>
                      )}
                    </span>
                  </div>
                )}
                {tierData.nextTierBenefits.freeInsuranceDaily > 0 && (
                  <div className="flex items-center gap-2">
                    <Clock className="h-4 w-4 text-orange-500" />
                    <span className="text-sm">
                      {tierData.nextTierBenefits.freeInsuranceDaily} Free Insurance/day
                      {tierData.currentBenefits.freeInsuranceDaily === 0 && (
                        <Badge variant="outline" className="ml-2 text-xs text-green-600">NEW!</Badge>
                      )}
                    </span>
                  </div>
                )}
              </div>
            </div>
            <div className="mt-4 p-3 bg-gradient-to-r from-primary/5 to-purple-500/5 rounded-lg border border-primary/10">
              <p className="text-sm text-center">
                Earn <span className="font-bold">{(tierData.nextTierRequirement! - tierData.lifetimeEarnings).toLocaleString()} more NTIQ</span> to unlock {tierData.nextTier} tier benefits!
              </p>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Tier Information */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Loyalty Program</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            {(['bronze', 'silver', 'gold', 'platinum'] as const).map((tier) => {
              const isCurrentTier = tier === tierData.currentTier;
              const TierIconComponent = tierIcons[tier];
              const gradient = tierColors[tier];

              return (
                <div 
                  key={tier}
                  className={`p-3 rounded-lg border-2 transition-all ${
                    isCurrentTier 
                      ? 'border-primary bg-primary/5' 
                      : 'border-border hover:border-primary/50'
                  }`}
                >
                  <div className="flex flex-col items-center space-y-2">
                    <div className={`p-2 rounded-lg bg-gradient-to-r ${gradient} ${!isCurrentTier ? 'opacity-50' : ''}`}>
                      <TierIconComponent className="h-5 w-5 text-white" />
                    </div>
                    <h4 className={`text-sm font-semibold capitalize ${isCurrentTier ? 'text-primary' : 'text-muted-foreground'}`}>
                      {tier}
                    </h4>
                    {isCurrentTier && (
                      <Badge variant="default" className="text-xs">
                        Current
                      </Badge>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
          <div className="mt-4 text-center">
            <p className="text-sm text-muted-foreground">
              Tiers are based on lifetime NTIQ earnings and provide permanent benefits
            </p>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

