      queryClient.refetchQueries({ queryKey: ['/api/battles/live'] });
      queryClient.refetchQueries({ queryKey: ['/api/user'] }); // Refresh user balance
      // Also refresh after a short delay to ensure database consistency
      setTimeout(() => {
