import { useQuery } from '@tanstack/react-query';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import { TrendingUp, TrendingDown, Clock, Users, Trophy, Skull } from 'lucide-react';

interface Participant {
  id: number;
  userId: number;
  username: string;
  uid: string;
  status: string;
  eliminatedRound: number | null;
  joinedAt: string;
  eliminatedAt: string | null;
  profilePhoto: string | null;
  prediction: string | null;
  submittedAt: string | null;
  startingPrice: number | null;
  currentRound: number;
}

interface SurvivalParticipantsListProps {
  tournamentId: number;
}

export function SurvivalParticipantsList({ tournamentId }: SurvivalParticipantsListProps) {
  const { data: participants = [], isLoading, error } = useQuery({
    queryKey: [`/api/survival-tournaments/${tournamentId}/participants-with-predictions`],
    refetchInterval: 3000, // Refresh every 3 seconds
  });

  if (isLoading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Users className="h-5 w-5" />
            Tournament Participants
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="animate-pulse space-y-2">
            {[1, 2, 3].map((i) => (
              <div key={i} className="h-16 bg-gray-200 dark:bg-gray-700 rounded-lg" />
            ))}
          </div>
        </CardContent>
      </Card>
    );
  }

  if (error) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Users className="h-5 w-5" />
            Tournament Participants
          </CardTitle>
        </CardHeader>
        <CardContent>
          <p className="text-gray-500">Failed to load participants</p>
        </CardContent>
      </Card>
    );
  }

  const activeParticipants = participants.filter((p: Participant) => p.status === 'active');
  const eliminatedParticipants = participants.filter((p: Participant) => p.status === 'eliminated');
  const totalPredictions = participants.filter((p: Participant) => p.prediction).length;

  const getStatusBadge = (participant: Participant) => {
    if (participant.status === 'active') {
      return <Badge variant="default" className="bg-green-500 text-white">Active</Badge>;
    } else if (participant.status === 'eliminated') {
      return <Badge variant="destructive" className="bg-red-500 text-white">Eliminated R{participant.eliminatedRound}</Badge>;
    } else if (participant.status === 'winner') {
      return <Badge variant="default" className="bg-yellow-500 text-black">Winner</Badge>;
    }
    return <Badge variant="outline">{participant.status}</Badge>;
  };

  const getPredictionDisplay = (participant: Participant) => {
    if (!participant.prediction) {
      return (
        <div className="flex items-center gap-1 text-gray-500">
          <Clock className="h-4 w-4" />
          <span className="text-sm">Not predicted</span>
        </div>
      );
    }

    const isUp = participant.prediction.toLowerCase() === 'up';
    return (
      <div className={`flex items-center gap-1 ${isUp ? 'text-green-600' : 'text-red-600'}`}>
        {isUp ? <TrendingUp className="h-4 w-4" /> : <TrendingDown className="h-4 w-4" />}
        <span className="font-semibold">{participant.prediction.toUpperCase()}</span>
      </div>
    );
  };

  return (
    <div className="space-y-4">
      {/* Elimination Alerts */}
      {eliminatedParticipants.length > 0 && (
        <Card className="border-red-500 bg-red-50 dark:bg-red-900/20">
          <CardContent className="pt-6">
            <div className="flex items-center gap-3 mb-3">
              <Skull className="h-6 w-6 text-red-500" />
              <h3 className="text-lg font-bold text-red-700 dark:text-red-300">
                Elimination Alert!
              </h3>
            </div>
            <div className="text-red-600 dark:text-red-400">
              {eliminatedParticipants.length === 1 ? (
                <p>
                  <strong>{eliminatedParticipants[0].username}</strong> has been eliminated from Round {eliminatedParticipants[0].eliminatedRound} due to wrong prediction.
                </p>
              ) : (
                <p>
                  <strong>{eliminatedParticipants.length} participants</strong> have been eliminated from the tournament due to wrong predictions.
                </p>
              )}
            </div>
          </CardContent>
        </Card>
      )}

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Users className="h-5 w-5" />
            Tournament Participants ({participants.length})
          </CardTitle>
          <div className="flex gap-4 text-sm text-gray-600 dark:text-gray-400">
            <span className="flex items-center gap-1">
              <Trophy className="h-4 w-4 text-green-500" />
              Active: {activeParticipants.length}
            </span>
            <span className="flex items-center gap-1">
              <Skull className="h-4 w-4 text-red-500" />
              Eliminated: {eliminatedParticipants.length}
            </span>
            <span className="flex items-center gap-1">
              <TrendingUp className="h-4 w-4 text-blue-500" />
              Predictions: {totalPredictions}/{participants.length}
            </span>
          </div>
        </CardHeader>
        <CardContent>
          <div className="space-y-3">
            {/* Active Participants */}
            {activeParticipants.length > 0 && (
              <div>
                <h4 className="font-semibold text-green-600 dark:text-green-400 mb-2 flex items-center gap-2">
                  <Trophy className="h-4 w-4" />
                  Active Players ({activeParticipants.length})
                </h4>
                <div className="space-y-2">
                  {activeParticipants.map((participant: Participant) => (
                    <div
                      key={participant.id}
                      className="flex items-center justify-between p-3 bg-green-50 dark:bg-green-900/20 rounded-lg border border-green-200 dark:border-green-800"
                    >
                      <div className="flex items-center gap-3">
                        <Avatar className="h-8 w-8">
                          <AvatarImage src={participant.profilePhoto || undefined} />
                          <AvatarFallback>{participant.username.charAt(0).toUpperCase()}</AvatarFallback>
                        </Avatar>
                        <div>
                          <div className="font-medium text-gray-900 dark:text-gray-100">
                            {participant.username}
                          </div>
                          <div className="text-xs text-gray-500">
                            UID: {participant.uid}
                          </div>
                        </div>
                      </div>
                      <div className="flex items-center gap-3">
                        {getPredictionDisplay(participant)}
                        {getStatusBadge(participant)}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Eliminated Participants */}
            {eliminatedParticipants.length > 0 && (
              <div>
                <h4 className="font-semibold text-red-600 dark:text-red-400 mb-2 flex items-center gap-2">
                  <Skull className="h-4 w-4" />
                  Eliminated Players ({eliminatedParticipants.length})
                </h4>
                <div className="space-y-2">
                  {eliminatedParticipants.map((participant: Participant) => (
                    <div
                      key={participant.id}
                      className="flex items-center justify-between p-3 bg-red-50 dark:bg-red-900/20 rounded-lg border border-red-200 dark:border-red-800 opacity-75"
                    >
                      <div className="flex items-center gap-3">
                        <Avatar className="h-8 w-8">
                          <AvatarImage src={participant.profilePhoto || undefined} />
                          <AvatarFallback>{participant.username.charAt(0).toUpperCase()}</AvatarFallback>
                        </Avatar>
                        <div>
                          <div className="font-medium text-gray-900 dark:text-gray-100">
                            {participant.username}
                          </div>
                          <div className="text-xs text-gray-500">
                            UID: {participant.uid} • Eliminated Round {participant.eliminatedRound}
                          </div>
                          <div className="text-xs text-red-600 dark:text-red-400 font-medium mt-1">
                            ❌ Wrong prediction - Eliminated from tournament
                          </div>
                        </div>
                      </div>
                      <div className="flex items-center gap-3">
                        {getPredictionDisplay(participant)}
                        {getStatusBadge(participant)}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {participants.length === 0 && (
              <div className="text-center py-8 text-gray-500">
                <Users className="h-12 w-12 mx-auto mb-2 opacity-50" />
                <p>No participants yet</p>
              </div>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Prediction Summary */}
      {participants.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle className="text-lg">Round {participants[0]?.currentRound || 0} Predictions Summary</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-3 gap-4 text-center">
              <div className="p-3 bg-green-100 dark:bg-green-900/20 rounded-lg">
                <div className="flex items-center justify-center gap-2 text-green-600 dark:text-green-400">
                  <TrendingUp className="h-5 w-5" />
                  <span className="font-semibold">UP</span>
                </div>
                <div className="text-2xl font-bold text-green-700 dark:text-green-300 mt-1">
                  {participants.filter((p: Participant) => p.prediction?.toLowerCase() === 'up').length}
                </div>
              </div>
              <div className="p-3 bg-red-100 dark:bg-red-900/20 rounded-lg">
                <div className="flex items-center justify-center gap-2 text-red-600 dark:text-red-400">
                  <TrendingDown className="h-5 w-5" />
                  <span className="font-semibold">DOWN</span>
                </div>
                <div className="text-2xl font-bold text-red-700 dark:text-red-300 mt-1">
                  {participants.filter((p: Participant) => p.prediction?.toLowerCase() === 'down').length}
                </div>
              </div>
              <div className="p-3 bg-gray-100 dark:bg-gray-800 rounded-lg">
                <div className="flex items-center justify-center gap-2 text-gray-600 dark:text-gray-400">
                  <Clock className="h-5 w-5" />
                  <span className="font-semibold">WAITING</span>
                </div>
                <div className="text-2xl font-bold text-gray-700 dark:text-gray-300 mt-1">
                  {participants.filter((p: Participant) => !p.prediction).length}
                </div>
              </div>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

client/src/components/survival-status.ts.content:
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Shield, Trophy, AlertCircle, Clock, Target, TrendingUp, TrendingDown } from "lucide-react";
import { SocialShare, createShareData } from "@/components/SocialShare";

interface SurvivalStatus {
  tournaments: Array<{
    id: number;
    title: string;
    cryptocurrency: string;
    status: 'active' | 'eliminated' | 'winner' | 'completed';
    round: number;
    eliminatedRound?: number;
    wonRound?: number;
    totalParticipants: number;
    remainingParticipants: number;
    prizePool: number;
    entryFee: number;
    joinedAt: string;
    prediction?: string;
    eliminatedAt?: string;
    wonAt?: string;
    finalPosition?: number;
  }>;
  stats: {
    totalTournaments: number;
    tournamentsWon: number;
    totalWinnings: number;
    averageRoundsReached: number;
    bestFinish: number;
    winRate: number;
  };
}

export function SurvivalStatus() {
  const { data: survivalStatus, isLoading } = useQuery<SurvivalStatus>({
    queryKey: ["/api/user/survival-status"],
    staleTime: 10000, // 10 seconds
  });

  if (isLoading) {
    return (
      <Card className="bg-surface border-surface-light">
        <CardHeader>
          <CardTitle className="flex items-center">
            <Shield className="mr-2" size={20} />
            Survival Tournament Status
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="text-center text-slate-400">Loading survival status...</div>
        </CardContent>
      </Card>
    );
  }

  if (!survivalStatus || survivalStatus.tournaments.length === 0) {
    return (
      <Card className="bg-surface border-surface-light">
        <CardHeader>
          <CardTitle className="flex items-center">
            <Shield className="mr-2" size={20} />
            Survival Tournament Status
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="text-center space-y-3">
            <AlertCircle className="mx-auto text-slate-400" size={48} />
            <p className="text-slate-400">No tournament participation yet</p>
            <p className="text-xs text-slate-500">Join a survival tournament to see your status here</p>
          </div>
        </CardContent>
      </Card>
    );
  }

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'active':
        return <Badge className="bg-blue-600 text-white">ACTIVE</Badge>;
      case 'eliminated':
        return <Badge className="bg-red-600 text-white">ELIMINATED</Badge>;
      case 'winner':
        return <Badge className="bg-gradient-to-r from-yellow-500 to-amber-500 text-white font-bold border border-yellow-400">WIN 🏆</Badge>;
      case 'completed':
        return <Badge className="bg-gray-600 text-white">COMPLETED</Badge>;
      default:
        return <Badge className="bg-gray-500 text-white">{status.toUpperCase()}</Badge>;
    }
  };

  const getPredictionIcon = (prediction?: string) => {
    if (prediction === 'up') return <TrendingUp className="text-green-500" size={16} />;
    if (prediction === 'down') return <TrendingDown className="text-red-500" size={16} />;
    return <Target className="text-gray-500" size={16} />;
  };

  return (
    <div className="space-y-6">
      {/* Tournament Statistics */}
      <Card className="bg-surface border-surface-light">
        <CardHeader>
          <CardTitle className="flex items-center">
            <Shield className="mr-2" size={20} />
            Survival Tournament Statistics
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
            <div className="text-center">
              <div className="text-2xl font-bold text-white">{survivalStatus.stats.totalTournaments}</div>
              <div className="text-xs text-slate-400">Total Tournaments</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-yellow-500">{survivalStatus.stats.tournamentsWon}</div>
              <div className="text-xs text-slate-400">Tournaments Won</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-green-500">{survivalStatus.stats.totalWinnings}</div>
              <div className="text-xs text-slate-400">Total Winnings (NTIQ)</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-blue-500">{survivalStatus.stats.averageRoundsReached.toFixed(1)}</div>
              <div className="text-xs text-slate-400">Avg Rounds Reached</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-purple-500">#{survivalStatus.stats.bestFinish}</div>
              <div className="text-xs text-slate-400">Best Finish</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-orange-500">{survivalStatus.stats.winRate.toFixed(1)}%</div>
              <div className="text-xs text-slate-400">Win Rate</div>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Tournament History */}
      <Card className="bg-surface border-surface-light">
        <CardHeader>
          <CardTitle className="flex items-center">
            <Trophy className="mr-2" size={20} />
            Tournament History
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {survivalStatus.tournaments.map((tournament) => (
              <div key={tournament.id} className="bg-surface-light rounded-lg p-4 border border-surface-light">
                <div className="flex justify-between items-start mb-3">
                  <div>
                    <h4 className="font-medium text-white">{tournament.title}</h4>
                    <p className="text-sm text-slate-400">{tournament.cryptocurrency.toUpperCase()}</p>
                  </div>
                  {getStatusBadge(tournament.status)}
                </div>

                <div className="grid grid-cols-2 gap-4 text-sm">
                  <div className="space-y-2">
                    <div className="flex justify-between">
                      <span className="text-slate-400">Round:</span>
                      <span className="text-white">{tournament.round}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-slate-400">Entry Fee:</span>
                      <span className="text-white">{tournament.entryFee} NTIQ</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-slate-400">Prize Pool:</span>
                      <span className="text-green-400">{tournament.prizePool} NTIQ</span>
                    </div>
                  </div>

                  <div className="space-y-2">
                    <div className="flex justify-between">
                      <span className="text-slate-400">Participants:</span>
                      <span className="text-white">{tournament.remainingParticipants}/{tournament.totalParticipants}</span>
                    </div>
                    {tournament.prediction && (
                      <div className="flex justify-between items-center">
                        <span className="text-slate-400">Last Prediction:</span>
                        <div className="flex items-center space-x-1">
                          {getPredictionIcon(tournament.prediction)}
                          <span className="text-white uppercase">{tournament.prediction}</span>
                        </div>
                      </div>
                    )}
                    {tournament.finalPosition && (
                      <div className="flex justify-between">
                        <span className="text-slate-400">Final Position:</span>
                        <span className="text-yellow-400">#{tournament.finalPosition}</span>
                      </div>
                    )}
                  </div>
                </div>

                {/* Status specific information */}
                {tournament.status === 'eliminated' && tournament.eliminatedRound && (
                  <div className="mt-3 p-2 bg-red-900/20 rounded border border-red-700/30">
                    <div className="flex items-center space-x-2 text-red-400 text-sm">
                      <AlertCircle size={16} />
                      <span>Eliminated in Round {tournament.eliminatedRound}</span>
                    </div>
                  </div>
                )}

                {tournament.status === 'winner' && (
                  <div className="mt-3 p-2 bg-gradient-to-r from-yellow-900/30 to-amber-900/30 rounded border border-yellow-500/50">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center space-x-2 text-yellow-300 text-sm">
                        <Trophy size={16} />
                        <span className="font-semibold">WIN - Tournament Champion!</span>
                      </div>
                      <div className="flex items-center gap-3">
                        <div className="text-green-400 font-bold text-sm">
                          +{tournament.prizePool} NTIQ
                        </div>
                        {/* Share Button for Tournament Win */}
                        <SocialShare
                          compact={true}
                          data={createShareData.survival(
                            tournament.finalPosition || 1,
                            tournament.round,
                            tournament.totalParticipants - tournament.remainingParticipants,
                            tournament.prizePool
                          )}
                        />
                      </div>
                    </div>
                    {tournament.wonAt && (
                      <div className="text-xs text-yellow-400/70 mt-1">
                        Won on {new Date(tournament.wonAt).toLocaleDateString()}
                      </div>
                    )}
                  </div>
                )}

                {tournament.status === 'active' && (
                  <div className="mt-3 p-2 bg-blue-900/20 rounded border border-blue-700/30">
                    <div className="flex items-center space-x-2 text-blue-400 text-sm">
                      <Clock size={16} />
                      <span>Tournament in progress - Round {tournament.round}</span>
                    </div>
                  </div>
                )}

                <div className="mt-3 text-xs text-slate-500">
                  Joined: {new Date(tournament.joinedAt).toLocaleDateString()}
                </div>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

