import { useQuery } from "@tanstack/react-query";
import { Medal, Eye, ExternalLink } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Link } from "wouter";
import type { LeaderboardEntry, UserStats } from "@/types";
import type { User } from "@shared/schema";

function getRankIcon(rank: number): string {
  switch (rank) {
    case 1:
      return "🥇";
    case 2:
      return "🥈";
    case 3:
      return "🥉";
    default:
      return `${rank}`;
  }
}

function getRankColor(rank: number): string {
  switch (rank) {
    case 1:
      return "bg-warning text-dark";
    case 2:
      return "bg-slate-400 text-dark";
    case 3:
      return "bg-amber-600 text-white";
    default:
      return "bg-surface-light text-slate-300";
  }
}

export function TopPredictors() {
  const { data: leaderboard = [], isLoading } = useQuery<LeaderboardEntry[]>({
    queryKey: ["/api/leaderboard"],
    refetchInterval: false, // DISABLED to prevent rate limiting
    refetchIntervalInBackground: false,
    staleTime: 10 * 60 * 1000, // 10 minutes stale time
  });

  // Get current user information
  const { data: user } = useQuery<User>({
    queryKey: ["/api/user"],
    retry: false,
    staleTime: 60000,
  });

  // Get current user stats to access their rank
  const { data: userStats } = useQuery<UserStats>({
    queryKey: ["/api/user/stats"],
    enabled: !!user,
    retry: false,
    staleTime: 60000,
  });

  if (isLoading) {
    return (
      <div className="bg-surface rounded-xl p-6 border border-surface-light h-full flex flex-col">
        <h3 className="text-lg font-bold mb-4 flex items-center">
          <Medal className="text-warning mr-2" size={18} />
          Top Predictors
        </h3>
        <div className="space-y-3 flex-1">
          {[...Array(6)].map((_, i) => (
            <div key={i} className="p-3 bg-surface-light rounded-lg animate-pulse">
              <div className="h-12 bg-slate-600 rounded"></div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  if (leaderboard.length === 0) {
    return (
      <div className="bg-surface rounded-xl p-6 border border-surface-light h-full flex flex-col">
        <h3 className="text-lg font-bold mb-4 flex items-center">
          <Medal className="text-warning mr-2" size={18} />
          Top Predictors
        </h3>
        <div className="text-center py-8 text-slate-400 flex-1 flex flex-col justify-center">
          <Medal className="mx-auto mb-2" size={32} />
          <p>No predictors yet</p>
          <p className="text-sm">Be the first to make predictions!</p>
        </div>
      </div>
    );
  }

  // Limit to top 6 predictors only
  const topSixPredictors = leaderboard.slice(0, 6);

  // Check if current user is in top 6
  const currentUserInTopSix = user && topSixPredictors.some(predictor => predictor.id === user.id);

  // Create user rank entry if user is logged in and not in top 6
  const userRankEntry = user && userStats && !currentUserInTopSix ? {
    id: user.id,
    username: "You",
    rank: userStats.rank || 0, // Default to 0 if no rank assigned
    totalPredictions: 0,
    correctPredictions: 0,
    accuracy: userStats.accuracy || 0,
    totalRewards: userStats.totalRewards || 0,
  } : null;

  return (
    <div className="bg-surface rounded-xl p-6 border border-surface-light h-full flex flex-col">
      <h3 className="text-lg font-bold mb-4 flex items-center">
        <Medal className="text-warning mr-2" size={18} />
        Top Predictors
      </h3>

      <div className="space-y-3 flex-1">
        {topSixPredictors.map((user, index) => {
          // Use backend-provided rank for consistency
          const rank = user.rank;

          return (
            <div key={user.id} className="flex items-center space-x-3 p-3 bg-surface-light rounded-lg">
              <div className={`flex items-center justify-center w-8 h-8 ${getRankColor(rank)} font-bold rounded-full text-sm`}>
                {rank <= 3 ? getRankIcon(rank) : rank}
              </div>
              <div className="flex-1">
                <p className="font-semibold text-sm">{user.username}</p>
                <div className="flex items-center space-x-2 text-xs text-slate-400">
                  <span>Accuracy: {user.accuracy}%</span>
                  {(user.totalBattles || 0) > 0 && (
                    <span className="text-blue-400">⚔{user.wonBattles || 0}/{user.totalBattles || 0}</span>
                  )}
                  {(user.totalSurvivalTournaments || 0) > 0 && (
                    <span className="text-orange-400">🏆{user.wonSurvivalTournaments || 0}/{user.totalSurvivalTournaments || 0}</span>
                  )}
                </div>
              </div>
              <div className="text-right">
                <p className="text-sm font-semibold text-success">
                  {user.totalRewards.toLocaleString()}
                </p>
                <p className="text-xs text-slate-400">NTIQ</p>
              </div>
            </div>
          );
        })}

        {/* Show current user's rank if they're not in top 6 */}
        {userRankEntry && (
          <div className="flex items-center space-x-3 p-3 bg-surface-light rounded-lg">
            <div className={`flex items-center justify-center w-8 h-8 ${getRankColor(userRankEntry.rank)} font-bold rounded-full text-sm`}>
              {userRankEntry.rank <= 3 ? getRankIcon(userRankEntry.rank) : userRankEntry.rank}
            </div>
            <div className="flex-1">
              <p className="font-semibold text-sm text-warning">You</p>
              <div className="flex items-center space-x-2 text-xs text-slate-400">
                <span>Accuracy: {userRankEntry.accuracy}%</span>
              </div>
            </div>
            <div className="text-right">
              <p className="text-sm font-semibold text-success">
                {userRankEntry.totalRewards.toLocaleString()}
              </p>
              <p className="text-xs text-slate-400">NTIQ</p>
            </div>
          </div>
        )}

        {/* Fill remaining space if less than 6 predictors and no user rank entry */}
        {topSixPredictors.length < 6 && !userRankEntry && (
          <div className="flex-1 flex flex-col justify-center items-center text-slate-400 text-sm">
            <p>{6 - topSixPredictors.length} more slots available</p>
          </div>
        )}
      </div>

      <div className="mt-4">
        <Link href="/leaderboard">
          <Button
            variant="outline"
            className="w-full bg-primary/20 hover:bg-primary/30 text-primary border-primary/20 group transition-all duration-200 hover:scale-[1.02]"
          >
            <Eye className="mr-2 group-hover:mr-3 transition-all duration-200" size={16} />
            View Full Leaderboard
            <ExternalLink className="ml-2 group-hover:ml-3 transition-all duration-200" size={14} />
          </Button>
        </Link>
      </div>
    </div>
  );
}

client/src/components/tournament-card.ts.content:
import { useState, useEffect } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { TrendingUp, TrendingDown, Users, Clock, Trophy, Target, DollarSign, X, CheckCircle, AlertTriangle } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import { useToast } from '@/hooks/use-toast';
import { apiRequest } from '@/lib/queryClient';
import { format } from 'date-fns';
import { CountdownTimer } from '@/components/countdown-timer';
import PredictionTimingIndicator from '@/components/prediction-timing-indicator';
import { useWalletRequired } from '@/hooks/useWalletRequired';

// Types
interface SurvivalTournament {
  id: number;
  title: string;
  description: string;
  cryptocurrency: string;
  entryFee: number;
  maxParticipants: number;
  currentParticipants: number;
  prizePool: number;
  rewardAmount: number;
  rewardType: string;
  status: 'open' | 'active' | 'completed' | 'cancelled';
  roundDuration: number;
  round1Duration?: number | null;
  round2Duration?: number | null;
  round3Duration?: number | null;
  individualRoundDurations?: string | null;
  startTime: string;
  endTime: string;
  nextRoundTime: string;
  participants: Array<{
    id: number;
    userId: number;
    status: string;
    username?: string;
    profilePhoto?: string;
  }>;
  rounds: Array<{
    id: number;
    roundNumber: number;
    status: string;
    startTime: string;
    endTime: string;
    startPrice?: number;
    endPrice?: number;
  }>;
  currentRound: number;
}

interface CryptoPrice {
  id: string;
  symbol: string;
  name: string;
  current_price: number;
  price_change_percentage_24h: number;
  image: string;
}

interface TournamentCardProps {
  tournament: SurvivalTournament;
  user: any;
  cryptoPrices: CryptoPrice[];
  onWalletRequired?: (callback: () => void, actionType: string) => void;
}



export const TournamentCard = ({ tournament, user, cryptoPrices, onWalletRequired }: TournamentCardProps) => {
  const { toast } = useToast();
  const queryClient = useQueryClient();

  // Wallet requirement system
  const { checkWalletRequired } = useWalletRequired();

  // Helper function to get real-time price from Pyth Network data
  const getRealTimePrice = (cryptoId: string): number => {
    const crypto = cryptoPrices?.find(c => c.id === cryptoId);
    return crypto?.current_price || 0;
  };

  // Early return with error card if props are invalid
  if (!tournament) {
    return (
      <Card className="p-4 bg-red-100 border-red-300">
        <CardContent>
          <p className="text-red-600">Error: Tournament data is missing</p>
        </CardContent>
      </Card>
    );
  }



  // Helper function to get individual round duration
  const getRoundDuration = (tournament: SurvivalTournament, roundNumber: number): number => {
    if (roundNumber === 1 && tournament.round1Duration) {
      return tournament.round1Duration;
    }
    if (roundNumber === 2 && tournament.round2Duration) {
      return tournament.round2Duration;
    }
    if (roundNumber === 3 && tournament.round3Duration) {
      return tournament.round3Duration;
    }

    if (tournament.individualRoundDurations) {
      try {
        const durations = JSON.parse(tournament.individualRoundDurations);
        if (Array.isArray(durations) && durations[roundNumber - 1]) {
          return durations[roundNumber - 1];
        }
      } catch (error) {
        console.error('Error parsing individual round durations:', error);
      }
    }

    return tournament.roundDuration || 60;
  };

  // Fetch participants with predictions untuk tournament ini
  const { data: participants = [] } = useQuery({
    queryKey: [`/api/survival-tournaments/${tournament.id}/participants-with-predictions`],
    refetchInterval: 3000,
  });

  // Join tournament mutation
  const joinTournamentMutation = useMutation({
    mutationFn: () => apiRequest(`/api/survival-tournaments/${tournament.id}/join`, {
      method: 'POST'
    }),
    onSuccess: () => {
      toast({
        title: "Successfully Joined!",
        description: "You have joined the survival tournament. Good luck!",
      });
      queryClient.invalidateQueries({ queryKey: ['/api/survival-tournaments'] });
      queryClient.invalidateQueries({ queryKey: [`/api/survival-tournaments/${tournament.id}/participants-with-predictions`] });
    },
    onError: (error: any) => {
      toast({
        title: "Failed to Join",
        description: error.message || "Unable to join tournament",
        variant: "destructive",
      });
    }
  });

  // UP/DOWN prediction mutations
  const predictUpMutation = useMutation({
    mutationFn: () => apiRequest(`/api/survival-tournaments/${tournament.id}/predict`, {
      method: 'POST',
      body: JSON.stringify({ prediction: 'up' }),
      headers: { 'Content-Type': 'application/json' }
    }),
    onSuccess: () => {
      toast({
        title: "Prediction Submitted!",
        description: "Your UP prediction has been recorded. Good luck!",
      });
      queryClient.invalidateQueries({ queryKey: ['/api/survival-tournaments'] });
      queryClient.invalidateQueries({ queryKey: [`/api/survival-tournaments/${tournament.id}/participants-with-predictions`] });
    },
    onError: (error: any) => {
      toast({
        title: "Prediction Failed",
        description: error.message || "Unable to submit prediction",
        variant: "destructive",
      });
    }
  });

  const predictDownMutation = useMutation({
    mutationFn: () => apiRequest(`/api/survival-tournaments/${tournament.id}/predict`, {
      method: 'POST',
      body: JSON.stringify({ prediction: 'down' }),
      headers: { 'Content-Type': 'application/json' }
    }),
    onSuccess: () => {
      toast({
        title: "Prediction Submitted!",
        description: "Your DOWN prediction has been recorded. Good luck!",
      });
      queryClient.invalidateQueries({ queryKey: ['/api/survival-tournaments'] });
      queryClient.invalidateQueries({ queryKey: [`/api/survival-tournaments/${tournament.id}/participants-with-predictions`] });
    },
    onError: (error: any) => {
      toast({
        title: "Prediction Failed",
        description: error.message || "Unable to submit prediction",
        variant: "destructive",
      });
    }
  });

  // Get current crypto price using live Pyth Network data
  const currentCrypto = cryptoPrices?.find(crypto => crypto.id === tournament.cryptocurrency);
  const currentPrice = getRealTimePrice(tournament.cryptocurrency);
  const priceChange24h = currentCrypto?.price_change_percentage_24h || 0;

  // Check if user has joined
  const userParticipant = (participants as any[])?.find((p: any) => p.userId === user?.id);
  const hasJoined = !!userParticipant;

  // Get current user status and prediction info
  const currentUser = (participants as any[])?.find((p: any) => p.userId === user?.id);
  const isEliminated = currentUser?.status === 'eliminated';
  const userCurrentPrediction = currentUser?.prediction;
  const eliminationRound = currentUser?.eliminatedRound;

  // Check if user is winner
  const activeParticipants = (participants as any[])?.filter((p: any) => p.status === 'active') || [];
  const isWinner = currentUser?.status === 'winner' || 
                   (tournament.status === 'completed' && 
                    currentUser?.status === 'active' && 
                    !isEliminated &&
                    activeParticipants.length === 1 &&
                    activeParticipants[0]?.userId === user?.id); // Last person standing wins

  // Check if user can make prediction
  const canPredict = hasJoined && tournament.status === 'active' && tournament.currentRound > 0 && !isEliminated && !isWinner && !userCurrentPrediction;

  // Get current round info
  const currentRound = tournament.rounds?.find(r => r.roundNumber === tournament.currentRound);
  const roundEndTime = currentRound?.endTime || tournament.nextRoundTime;
  const startingPrice = parseFloat(currentRound?.startPrice?.toString() || '0') || 0;

  try {
    return (
      <Card className="bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 border-slate-700 text-white">
        <CardContent className="p-6">
        {/* Header */}
        <div className="flex items-center justify-between mb-4">
          <div>
            <h3 className="text-xl font-bold text-white">{tournament.title}</h3>
            <p className="text-gray-400 text-sm">{tournament.description}</p>
          </div>
          <Badge
            variant={tournament.status === 'active' ? 'default' : 'secondary'}
            className={
              tournament.status === 'active' ? 'bg-green-600' : 
              tournament.status === 'completed' ? 'bg-gray-600' : 
              'bg-blue-600'
            }
          >
            {tournament.status.toUpperCase()}
          </Badge>
        </div>

        {/* Live Price Section */}
        {currentCrypto && (
          <div className="bg-yellow-500 text-black p-3 rounded-lg mb-4">
            <div className="flex items-center justify-between mb-2">
              <div className="flex items-center gap-2">
                <img src={currentCrypto.image} alt={currentCrypto.name} className="w-6 h-6" />
                <span className="font-semibold">{currentCrypto.name}</span>
              </div>
              <div className="text-right">
                <div className="font-bold">${currentPrice.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</div>
                <div className={`text-sm ${priceChange24h >= 0 ? 'text-green-700' : 'text-red-700'}`}>
                  {priceChange24h >= 0 ? '+' : ''}{priceChange24h.toFixed(2)}%
                </div>
              </div>
            </div>

            {/* Starting Price vs Current Price Comparison */}
            {tournament.status === 'active' && startingPrice > 0 && (
              <div className="border-t border-yellow-600 pt-2 mt-2">
                <div className="flex justify-between items-center text-sm">
                  <div>
                    <span className="font-medium">Starting Price:</span>
                    <span className="ml-1">${startingPrice.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</span>
                  </div>
                  <div className="text-right">
                    {(() => {
                      const livePythPrice = getRealTimePrice(tournament.cryptocurrency);
                      const priceDiff = Number(livePythPrice) - Number(startingPrice);
                      const priceDiffPercent = ((priceDiff / Number(startingPrice)) * 100);
                      return (
                        <div className={`font-medium ${priceDiff >= 0 ? 'text-green-800' : 'text-red-800'}`}>
                          {priceDiff >= 0 ? '+' : ''}${priceDiff.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })} 
                          <span className="text-xs ml-1">
                            ({priceDiff >= 0 ? '+' : ''}{priceDiffPercent.toFixed(2)}%)
                          </span>
                        </div>
                      );
                    })()}
                  </div>
                </div>
              </div>
            )}

            {/* Completed Rounds Results for Completed Tournaments */}
            {tournament.status === 'completed' && tournament.rounds && tournament.rounds.length > 0 && (
              <div className="border-t border-yellow-600 pt-2 mt-2">
                <div className="font-medium text-sm mb-2">Tournament Results:</div>
                <div className="space-y-1">
                  {tournament.rounds
                    .filter(round => round.status === 'completed')
                    .sort((a, b) => a.roundNumber - b.roundNumber)
                    .map(round => {
                      const startPrice = parseFloat(round.startPrice?.toString() || '0');
                      const endPrice = parseFloat(round.endPrice?.toString() || '0');
                      const priceChange = endPrice - startPrice;
                      const priceChangePercent = startPrice > 0 ? ((priceChange / startPrice) * 100) : 0;

                      return (
                        <div key={round.id} className="flex justify-between items-center text-xs bg-black/20 p-2 rounded">
                          <span className="font-medium">Round {round.roundNumber}:</span>
                          <span className="font-mono">${startPrice.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })} → ${endPrice.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</span>
                          <span className={`font-bold ${priceChange >= 0 ? 'text-green-300' : 'text-red-300'}`}>
                            {priceChange >= 0 ? '↗ UP' : '↘ DOWN'} ({priceChangePercent >= 0 ? '+' : ''}{priceChangePercent.toFixed(2)}%)
                          </span>
                        </div>
                      );
                    })}
                </div>
              </div>
            )}
          </div>
        )}

        {/* Tournament Info */}
        <div className="grid grid-cols-2 gap-4 mb-4">
          <div className="flex items-center gap-2">
            <DollarSign className="h-4 w-4 text-green-400" />
            <span className="text-sm">Entry Fee: {tournament.entryFee} NTIQ</span>
          </div>
          <div className="flex items-center gap-2">
            <Trophy className="h-4 w-4 text-yellow-400" />
            <span className="text-sm">Prize: {tournament.prizePool} NTIQ</span>
          </div>
          <div className="flex items-center gap-2">
            <Users className="h-4 w-4 text-blue-400" />
            <span className="text-sm">{tournament.currentParticipants}/{tournament.maxParticipants} Players</span>
          </div>
          <div className="flex items-center gap-2">
            <Target className="h-4 w-4 text-purple-400" />
            <span className="text-sm">Round {tournament.currentRound}/3</span>
          </div>
        </div>

        {/* Round Structure */}
        <div className="mb-4">
          <h4 className="font-semibold mb-2">Round Structure:</h4>
          <div className="grid grid-cols-3 gap-2 text-xs">
            {[1, 2, 3].map(roundNum => {
              // Find the round data to get starting and ending prices
              const roundData = tournament.rounds?.find(r => r.roundNumber === roundNum);
              const startingPrice = roundData?.startPrice ? parseFloat(roundData.startPrice.toString()) : null;
              const endingPrice = roundData?.endPrice ? parseFloat(roundData.endPrice.toString()) : null;
              const isRoundCompleted = roundData?.status === 'completed';

              return (
                <div
                  key={roundNum}
                  className={`p-2 rounded text-center ${
                    tournament.status === 'completed'
                      ? 'bg-green-600' // All rounds green when tournament completed
                      : roundNum === tournament.currentRound
                      ? 'bg-yellow-600 text-black'
                      : roundNum < tournament.currentRound
                      ? 'bg-green-600'
                      : 'bg-gray-600'
                  }`}
                >
                  <div className="font-semibold">Round {roundNum}</div>
                  <div>{getRoundDuration(tournament, roundNum)} min</div>

                  {/* Show start price if round has started */}
                  {startingPrice && (
                    <div className="text-[10px] mt-1 opacity-90">
                      Start: ${startingPrice.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                    </div>
                  )}

                  {/* Show end price if round is completed */}
                  {isRoundCompleted && endingPrice && (
                    <div className="text-[10px] opacity-90">
                      End: ${endingPrice.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                    </div>
                  )}

                  {/* Show price direction if round is completed */}
                  {isRoundCompleted && startingPrice && endingPrice && (
                    <div className={`text-[10px] font-bold mt-1 ${
                      endingPrice > startingPrice ? 'text-green-300' : 'text-red-300'
                    }`}>
                      {endingPrice > startingPrice ? '↗ UP' : '↘ DOWN'}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>

        {/* User Status Section */}
        {hasJoined && (
          <div className="mb-4 p-3 rounded-lg border border-slate-600 bg-slate-800/50">
            <h4 className="font-semibold mb-2 text-sm">Your Status:</h4>
            <div className="space-y-2">
              {isEliminated ? (
                <div className="flex items-center gap-2">
                  <X className="h-4 w-4 text-red-500" />
                  <Badge className="bg-red-600 text-white text-xs">ELIMINATED</Badge>
                  <span className="text-red-400 text-xs">Round {eliminationRound || 'Unknown'}</span>
                </div>
              ) : isWinner ? (
                <div className="flex items-center gap-2">
                  <Trophy className="h-4 w-4 text-yellow-500" />
                  <Badge className="bg-gradient-to-r from-yellow-500 to-amber-500 text-white font-bold border border-yellow-400 text-xs">WIN 🏆</Badge>
                  <span className="text-yellow-400 text-xs">Tournament champion!</span>
                </div>
              ) : currentUser?.status === 'active' ? (
                <div className="flex items-center gap-2">
                  <CheckCircle className="h-4 w-4 text-green-500" />
                  <Badge className="bg-green-600 text-white text-xs">ACTIVE</Badge>
                  <span className="text-green-400 text-xs">Still in tournament</span>
                </div>
              ) : (
                <div className="flex items-center gap-2">
                  <AlertTriangle className="h-4 w-4 text-orange-500" />
                  <Badge className="bg-orange-600 text-white text-xs">UNKNOWN</Badge>
                  <span className="text-orange-400 text-xs">Status unknown</span>
                </div>
              )}

              {/* Show prediction for current round if made */}
              {userCurrentPrediction && tournament.status === 'active' && !isEliminated && (
                <div className="flex items-center gap-2 mt-2">
                  <span className="text-xs text-gray-400">Current prediction:</span>
                  <div className={`flex items-center gap-1 ${userCurrentPrediction.toLowerCase() === 'up' ? 'text-green-500' : 'text-red-500'}`}>
                    {userCurrentPrediction.toLowerCase() === 'up' ? <TrendingUp className="h-3 w-3" /> : <TrendingDown className="h-3 w-3" />}
                    <span className="font-semibold text-xs">{userCurrentPrediction.toUpperCase()}</span>
                  </div>
                </div>
              )}
            </div>
          </div>
        )}

        {/* Tournament Actions */}
        <div className="space-y-3">
          {!user ? (
            <p className="text-center text-gray-400">Please login to participate</p>
          ) : tournament.status === 'open' && !hasJoined ? (
            <Button
              onClick={() => {
                checkWalletRequired(() => {
                  joinTournamentMutation.mutate();
                }, 'survival');
              }}
              disabled={joinTournamentMutation.isPending}
              className="w-full bg-green-600 hover:bg-green-700"
            >
              {joinTournamentMutation.isPending ? 'Joining...' : `Join Tournament (${tournament.entryFee} NTIQ)`}
            </Button>
          ) : tournament.status === 'open' && hasJoined ? (
            <div className="text-center">
              <Badge className="bg-blue-600">Joined! Waiting for tournament to start...</Badge>
              {tournament.currentRound === 0 && (
                <p className="text-sm text-gray-400 mt-2">
                  Round 1 starts when first player makes a prediction
                </p>
              )}
            </div>
          ) : tournament.status === 'active' && hasJoined && canPredict ? (
            <div className="space-y-3">
              {/* Anti-Gaming System - Prediction Timing Indicator */}
              <PredictionTimingIndicator tournamentId={tournament.id} />

              <div className="text-center">
                <div className="flex items-center justify-center gap-2 mb-2">
                  <Clock className="h-4 w-4" />
                  <span className="text-sm">Time remaining: <CountdownTimer targetTime={roundEndTime} /></span>
                </div>
                <p className="text-sm text-gray-400">Make your prediction for Round {tournament.currentRound}</p>
              </div>
              <div className="flex gap-2">
                <Button
                  onClick={() => {
                    checkWalletRequired(() => {
                      predictUpMutation.mutate();
                    }, 'survival');
                  }}
                  disabled={predictUpMutation.isPending}
                  className="flex-1 bg-green-600 hover:bg-green-700"
                >
                  <TrendingUp className="h-4 w-4 mr-2" />
                  {predictUpMutation.isPending ? 'Submitting...' : 'Price UP'}
                  {tournament.entryFee > 0 && <span className="ml-2">(-{tournament.entryFee} NTIQ)</span>}
                </Button>
                <Button
                  onClick={() => {
                    checkWalletRequired(() => {
                      predictDownMutation.mutate();
                    }, 'survival');
                  }}
                  disabled={predictDownMutation.isPending}
                  className="flex-1 bg-red-600 hover:bg-red-700"
                >
                  <TrendingDown className="h-4 w-4 mr-2" />
                  {predictDownMutation.isPending ? 'Submitting...' : 'Price DOWN'}
                  {tournament.entryFee > 0 && <span className="ml-2">(-{tournament.entryFee} NTIQ)</span>}
                </Button>
              </div>
            </div>
          ) : tournament.status === 'active' && hasJoined && isEliminated ? (
            <div className="text-center bg-red-900/20 p-4 rounded-lg border border-red-500">
              <div className="flex items-center justify-center gap-2 mb-2">
                <X className="h-5 w-5 text-red-500" />
                <Badge className="bg-red-600 text-white">ELIMINATED</Badge>
              </div>
              <p className="text-sm text-red-400">
                Eliminated in Round {eliminationRound || 'N/A'}
              </p>
              {userCurrentPrediction && (
                <div className="flex items-center justify-center gap-1 mt-2 text-sm">
                  <span className="text-gray-400">Your prediction was:</span>
                  <div className={`flex items-center gap-1 ${userCurrentPrediction.toLowerCase() === 'up' ? 'text-green-500' : 'text-red-500'}`}>
                    {userCurrentPrediction.toLowerCase() === 'up' ? <TrendingUp className="h-4 w-4" /> : <TrendingDown className="h-4 w-4" />}
                    <span className="font-semibold">{userCurrentPrediction.toUpperCase()}</span>
                  </div>
                </div>
              )}
            </div>
          ) : tournament.status === 'active' && hasJoined && userCurrentPrediction && !canPredict ? (
            <div className="text-center bg-blue-900/20 p-4 rounded-lg border border-blue-500">
              <div className="flex items-center justify-center gap-2 mb-2">
                <CheckCircle className="h-5 w-5 text-blue-500" />
                <Badge className="bg-blue-600 text-white">PREDICTION SUBMITTED</Badge>
              </div>
              <div className="flex items-center justify-center gap-1 mb-2">
                <span className="text-sm text-gray-400">Your prediction:</span>
                <div className={`flex items-center gap-1 ${userCurrentPrediction.toLowerCase() === 'up' ? 'text-green-500' : 'text-red-500'}`}>
                  {userCurrentPrediction.toLowerCase() === 'up' ? <TrendingUp className="h-4 w-4" /> : <TrendingDown className="h-4 w-4" />}
                  <span className="font-semibold">{userCurrentPrediction.toUpperCase()}</span>
                </div>
              </div>
              <div className="flex items-center justify-center gap-2 text-sm">
                <Clock className="h-4 w-4 text-gray-400" />
                <span className="text-gray-400">Time remaining: </span>
                <CountdownTimer targetTime={roundEndTime} />
              </div>
            </div>
          ) : tournament.status === 'active' && hasJoined && isWinner ? (
            <div className="text-center bg-gradient-to-r from-yellow-900/30 to-amber-900/30 p-4 rounded-lg border border-yellow-500">
              <div className="flex items-center justify-center gap-2 mb-2">
                <Trophy className="h-5 w-5 text-yellow-500" />
                <Badge className="bg-gradient-to-r from-yellow-500 to-amber-500 text-white font-bold border border-yellow-400">🏆 WINNER</Badge>
              </div>
              <p className="text-sm text-yellow-400">
                Congratulations! You are the tournament champion!
              </p>
              <p className="text-xs text-yellow-300 mt-1">
                Tournament will end when all rounds complete
              </p>
            </div>
          ) : tournament.status === 'active' && hasJoined && !canPredict ? (
            <div className="text-center">
              <Badge className="bg-orange-600">Waiting for next round...</Badge>
              <p className="text-sm text-gray-400 mt-2">
                Round {tournament.currentRound} in progress
              </p>
            </div>
          ) : tournament.status === 'active' && !hasJoined ? (
            <div className="text-center">
              <Badge className="bg-red-600">Tournament in Progress</Badge>
              <p className="text-sm text-gray-400 mt-2">Cannot join active tournament</p>
            </div>
          ) : (
            <div className="text-center">
              <Badge variant="secondary">Tournament {tournament.status}</Badge>
            </div>
          )}
        </div>

        {/* Participants Preview */}
        <div className="mt-4 pt-4 border-t border-slate-600">
          <div className="flex items-center justify-between">
            <span className="text-sm text-gray-400">Participants</span>
            <Progress 
              value={(tournament.currentParticipants / tournament.maxParticipants) * 100} 
              className="w-24 h-2"
            />
          </div>
          {(participants as any[])?.length > 0 && (
            <div className="flex items-center gap-1 mt-2">
              {(participants as any[]).slice(0, 5).map((participant: any, index: number) => (
                <div
                  key={participant.id}
                  className="w-6 h-6 rounded-full bg-gray-600 flex items-center justify-center text-xs"
                  title={participant.username}
                >
                  {participant.username?.charAt(0).toUpperCase() || 'U'}
                </div>
              ))}
              {(participants as any[]).length > 5 && (
                <span className="text-xs text-gray-400">+{(participants as any[]).length - 5}</span>
              )}
            </div>
          )}
        </div>
      </CardContent>
    </Card>
    );
  } catch (error) {
    console.error('TournamentCard error:', error);
    return (
      <Card className="p-4 bg-red-100 border-red-300">
        <CardContent>
          <h3 className="font-bold text-red-800">Tournament Card Error</h3>
          <p className="text-red-600">Failed to render tournament: {tournament?.title || 'Unknown'}</p>
          <p className="text-sm text-red-500">{String(error)}</p>
        </CardContent>
      </Card>
    );
  }
};

client/src/components/verification-setti.content:
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { useToast } from "@/hooks/use-toast";
import { Mail, Twitter, CheckCircle, XCircle, AlertTriangle } from "lucide-react";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";

interface VerificationSettingsProps {
  user: {
    id: number;
    email?: string;
    twitterHandle?: string;
    emailVerified: boolean;
    twitterVerified: boolean;
  };
}

export function VerificationSettings({ user }: VerificationSettingsProps) {
  const [email, setEmail] = useState(user.email || "");
  const [twitterHandle, setTwitterHandle] = useState(user.twitterHandle || "");
  const [duplicateCheck, setDuplicateCheck] = useState<any>(null);
  const { toast } = useToast();
  const queryClient = useQueryClient();

  // Update email mutation
  const updateEmailMutation = useMutation({
    mutationFn: (email: string) => apiRequest("/api/user/update-email", { method: "POST", body: { email } }),
    onSuccess: () => {
      toast({
        title: "Email Updated",
        description: "Your email has been updated successfully",
      });
      queryClient.invalidateQueries({ queryKey: ["/api/user"] });
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to update email",
        variant: "destructive",
      });
    },
  });

  // Update Twitter mutation
  const updateTwitterMutation = useMutation({
    mutationFn: (twitterHandle: string) => apiRequest("/api/user/update-twitter", { method: "POST", body: { twitterHandle } }),
    onSuccess: () => {
      toast({
        title: "Twitter Handle Updated",
        description: "Your Twitter handle has been updated successfully",
      });
      queryClient.invalidateQueries({ queryKey: ["/api/user"] });
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to update Twitter handle",
        variant: "destructive",
      });
    },
  });

  // Verify email mutation
  const verifyEmailMutation = useMutation({
    mutationFn: () => apiRequest("/api/user/verify-email", { method: "POST" }),
    onSuccess: () => {
      toast({
        title: "Email Verified",
        description: "Your email has been verified successfully",
      });
      queryClient.invalidateQueries({ queryKey: ["/api/user"] });
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to verify email",
        variant: "destructive",
      });
    },
  });

  // Verify Twitter mutation
  const verifyTwitterMutation = useMutation({
    mutationFn: () => apiRequest("/api/user/verify-twitter", { method: "POST" }),
    onSuccess: () => {
      toast({
        title: "Twitter Verified",
        description: "Your Twitter handle has been verified successfully",
      });
      queryClient.invalidateQueries({ queryKey: ["/api/user"] });
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to verify Twitter handle",
        variant: "destructive",
      });
    },
  });

  // Check duplicates mutation
  const checkDuplicatesMutation = useMutation({
    mutationFn: (params: { email?: string; twitterHandle?: string }) => 
      apiRequest(`/api/user/check-duplicates?${new URLSearchParams(params).toString()}`),
    onSuccess: (data) => {
      setDuplicateCheck(data);
    },
  });

  const handleUpdateEmail = () => {
    if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      toast({
        title: "Invalid Email",
        description: "Please enter a valid email address",
        variant: "destructive",
      });
      return;
    }
    updateEmailMutation.mutate(email);
  };

  const handleUpdateTwitter = () => {
    if (!twitterHandle || !/^@?[\w]{1,15}$/.test(twitterHandle.replace(/^@/, ""))) {
      toast({
        title: "Invalid Twitter Handle",
        description: "Please enter a valid Twitter handle (1-15 characters)",
        variant: "destructive",
      });
      return;
    }
    updateTwitterMutation.mutate(twitterHandle);
  };

  const handleCheckDuplicates = () => {
    const params: any = {};
    if (email && email !== user.email) params.email = email;
    if (twitterHandle && twitterHandle !== user.twitterHandle) params.twitterHandle = twitterHandle.replace(/^@/, "");

    if (Object.keys(params).length > 0) {
      checkDuplicatesMutation.mutate(params);
    }
  };

  return (
    <div className="space-y-6">
      <div className="text-center">
        <h2 className="text-2xl font-bold text-gray-900 dark:text-white">Account Verification</h2>
        <p className="text-gray-600 dark:text-gray-400 mt-2">
          Verify your email and Twitter to prevent multiple wallet usage and enhance security
        </p>
      </div>

      {/* Email Verification Card */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Mail className="h-5 w-5" />
            Email Verification
            {user.emailVerified ? (
              <Badge variant="default" className="bg-green-100 text-green-800">
                <CheckCircle className="h-3 w-3 mr-1" />
                Verified
              </Badge>
            ) : (
              <Badge variant="secondary" className="bg-yellow-100 text-yellow-800">
                <AlertTriangle className="h-3 w-3 mr-1" />
                Unverified
              </Badge>
            )}
          </CardTitle>
          <CardDescription>
            Link your email address to your wallet to prevent multiple accounts
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="email">Email Address</Label>
            <div className="flex gap-2">
              <Input
                id="email"
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="Enter your email address"
                className="flex-1"
              />
              <Button 
                onClick={handleUpdateEmail}
                disabled={updateEmailMutation.isPending || !email || email === user.email}
                variant="outline"
              >
                {updateEmailMutation.isPending ? "Updating..." : "Update"}
              </Button>
            </div>
          </div>

          {user.email && !user.emailVerified && (
            <Button 
              onClick={() => verifyEmailMutation.mutate()}
              disabled={verifyEmailMutation.isPending}
              className="w-full"
            >
              {verifyEmailMutation.isPending ? "Verifying..." : "Verify Email"}
            </Button>
          )}
        </CardContent>
      </Card>

      {/* Twitter Verification Card */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Twitter className="h-5 w-5" />
            Twitter Verification
            {user.twitterVerified ? (
              <Badge variant="default" className="bg-green-100 text-green-800">
                <CheckCircle className="h-3 w-3 mr-1" />
                Verified
              </Badge>
            ) : (
              <Badge variant="secondary" className="bg-yellow-100 text-yellow-800">
                <AlertTriangle className="h-3 w-3 mr-1" />
                Unverified
              </Badge>
            )}
          </CardTitle>
          <CardDescription>
            Link your Twitter handle to your wallet to prevent multiple accounts
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="twitter">Twitter Handle</Label>
            <div className="flex gap-2">
              <Input
                id="twitter"
                type="text"
                value={twitterHandle}
                onChange={(e) => setTwitterHandle(e.target.value)}
                placeholder="@username or username"
                className="flex-1"
              />
              <Button 
                onClick={handleUpdateTwitter}
                disabled={updateTwitterMutation.isPending || !twitterHandle || twitterHandle === user.twitterHandle}
                variant="outline"
              >
                {updateTwitterMutation.isPending ? "Updating..." : "Update"}
              </Button>
            </div>
          </div>

          {user.twitterHandle && !user.twitterVerified && (
            <Button 
              onClick={() => verifyTwitterMutation.mutate()}
              disabled={verifyTwitterMutation.isPending}
              className="w-full"
            >
              {verifyTwitterMutation.isPending ? "Verifying..." : "Verify Twitter"}
            </Button>
          )}
        </CardContent>
      </Card>

      {/* Duplicate Check Card */}
      <Card>
        <CardHeader>
          <CardTitle>Check for Duplicates</CardTitle>
          <CardDescription>
            Check if your email or Twitter handle is already registered with another wallet
          </CardDescription>
        </CardHeader>
        <CardContent>
          <Button 
            onClick={handleCheckDuplicates}
            disabled={checkDuplicatesMutation.isPending}
            variant="outline"
            className="w-full"
          >
            {checkDuplicatesMutation.isPending ? "Checking..." : "Check for Duplicates"}
          </Button>

          {duplicateCheck && (
            <div className="mt-4 space-y-2">
              {duplicateCheck.emailUsers && duplicateCheck.emailUsers.length > 0 && (
                <div className="p-3 bg-red-50 dark:bg-red-900/20 rounded-lg">
                  <h4 className="font-medium text-red-800 dark:text-red-200 flex items-center gap-2">
                    <XCircle className="h-4 w-4" />
                    Email Already Registered
                  </h4>
                  <p className="text-sm text-red-600 dark:text-red-300 mt-1">
                    This email is already linked to {duplicateCheck.emailUsers.length} other wallet(s)
                  </p>
                </div>
              )}

              {duplicateCheck.twitterUsers && duplicateCheck.twitterUsers.length > 0 && (
                <div className="p-3 bg-red-50 dark:bg-red-900/20 rounded-lg">
                  <h4 className="font-medium text-red-800 dark:text-red-200 flex items-center gap-2">
                    <XCircle className="h-4 w-4" />
                    Twitter Handle Already Registered
                  </h4>
                  <p className="text-sm text-red-600 dark:text-red-300 mt-1">
                    This Twitter handle is already linked to {duplicateCheck.twitterUsers.length} other wallet(s)
                  </p>
                </div>
              )}

              {(!duplicateCheck.emailUsers || duplicateCheck.emailUsers.length === 0) && 
               (!duplicateCheck.twitterUsers || duplicateCheck.twitterUsers.length === 0) && (
                <div className="p-3 bg-green-50 dark:bg-green-900/20 rounded-lg">
                  <h4 className="font-medium text-green-800 dark:text-green-200 flex items-center gap-2">
                    <CheckCircle className="h-4 w-4" />
                    No Duplicates Found
                  </h4>
                  <p className="text-sm text-green-600 dark:text-green-300 mt-1">
                    Your email and Twitter handle are unique to this wallet
                  </p>
                </div>
              )}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

client/src/components/wallet-connect.tsx.content:
import { useState, useEffect } from 'react';
import { useAccount, useConnect, useDisconnect, useBalance } from 'wagmi';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Wallet, LogOut, Copy, ExternalLink, AlertCircle, CheckCircle } from 'lucide-react';
import { useToast } from '@/hooks/use-toast';
import { formatEther } from 'viem';

interface WalletConnectProps {
  onConnectionChange?: (connected: boolean, address?: string) => void;
}

export function WalletConnect({ onConnectionChange }: WalletConnectProps) {
  const { address, isConnected, chain } = useAccount();
  const { connect, connectors, isPending } = useConnect();
  const { disconnect } = useDisconnect();
  const { toast } = useToast();
  const [isConnecting, setIsConnecting] = useState(false);

  // Get ETH balance
  const { data: balance, refetch: refetchBalance } = useBalance({
    address: address,
    query: {
      enabled: !!address,
      refetchInterval: 10000, // Refetch every 10 seconds
    },
  });

  // Notify parent component of connection changes
  useEffect(() => {
    onConnectionChange?.(isConnected, address);
  }, [isConnected, address, onConnectionChange]);

  // Auto-refresh balance when connected
  useEffect(() => {
    if (isConnected && address) {
      const interval = setInterval(() => {
        refetchBalance();
      }, 15000); // Refresh every 15 seconds

      return () => clearInterval(interval);
    }
  }, [isConnected, address, refetchBalance]);

  const handleConnect = async (connector: any) => {
    try {
      setIsConnecting(true);
      await connect({ connector });

      toast({
        title: "Wallet Connected",
        description: "Successfully connected to your wallet",
      });
    } catch (error: any) {
      console.error('Connection error:', error);
      toast({
        title: "Connection Failed",
        description: error.message || "Failed to connect wallet",
        variant: "destructive",
      });
    } finally {
      setIsConnecting(false);
    }
  };

  const handleDisconnect = () => {
    disconnect();
    toast({
      title: "Wallet Disconnected",
      description: "Your wallet has been disconnected",
    });
  };

  const copyAddress = () => {
    if (address) {
      navigator.clipboard.writeText(address);
      toast({
        title: "Address Copied",
        description: "Wallet address copied to clipboard",
      });
    }
  };

  const formatAddress = (addr: string) => {
    return `${addr.slice(0, 6)}...${addr.slice(-4)}`;
  };

  const getNetworkName = (chainId?: number) => {
    switch (chainId) {
      case 1: return 'Ethereum';
      case 137: return 'Polygon';
      case 42161: return 'Arbitrum';
      case 10: return 'Optimism';
      case 8453: return 'Base';
      default: return 'Unknown';
    }
  };

  const getNetworkColor = (chainId?: number) => {
    switch (chainId) {
      case 1: return 'bg-blue-500';
      case 137: return 'bg-purple-500';
      case 42161: return 'bg-blue-600';
      case 10: return 'bg-red-500';
      case 8453: return 'bg-blue-400';
      default: return 'bg-gray-500';
    }
  };

  if (!isConnected) {
    return (
      <Card className="bg-surface border-surface-light">
        <CardHeader>
          <CardTitle className="flex items-center">
            <Wallet className="mr-2" size={20} />
            Connect Wallet
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <p className="text-sm text-slate-400">
            Connect your wallet to start making predictions and earning rewards
          </p>

          <div className="space-y-2">
            {connectors.map((connector) => (
              <Button
                key={connector.id}
                onClick={() => handleConnect(connector)}
                disabled={isPending || isConnecting}
                className="w-full justify-start"
                variant="outline"
              >
                <Wallet className="mr-2" size={16} />
                {isPending || isConnecting ? 'Connecting...' : `Connect ${connector.name}`}
              </Button>
            ))}
          </div>

          <div className="text-xs text-slate-500 space-y-1">
            <p className="flex items-center">
              <AlertCircle className="mr-1" size={12} />
              Make sure you have a Web3 wallet installed
            </p>
            <p>• Metamask, WalletConnect, and other wallets supported</p>
            <p>• Your wallet will open for connection approval</p>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className="bg-surface border-surface-light">
      <CardHeader>
        <CardTitle className="flex items-center justify-between">
          <div className="flex items-center">
            <CheckCircle className="mr-2 text-green-500" size={20} />
            Wallet Connected
          </div>
          <Button
            onClick={handleDisconnect}
            variant="outline"
            size="sm"
          >
            <LogOut className="mr-1" size={14} />
            Disconnect
          </Button>
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Network Info */}
        <div className="flex items-center justify-between">
          <span className="text-sm text-slate-400">Network:</span>
          <Badge 
            className={`${getNetworkColor(chain?.id)} text-white`}
          >
            {getNetworkName(chain?.id)}
          </Badge>
        </div>

        {/* Address */}
        <div className="flex items-center justify-between">
          <span className="text-sm text-slate-400">Address:</span>
          <div className="flex items-center space-x-2">
            <code className="text-sm bg-surface-light px-2 py-1 rounded">
              {formatAddress(address!)}
            </code>
            <Button
              onClick={copyAddress}
              variant="ghost"
              size="sm"
              className="h-6 w-6 p-0"
            >
              <Copy size={12} />
            </Button>
            <Button
              onClick={() => window.open(`https://etherscan.io/address/${address}`, '_blank')}
              variant="ghost"
              size="sm"
              className="h-6 w-6 p-0"
            >
              <ExternalLink size={12} />
            </Button>
          </div>
        </div>

        {/* Balance */}
        {balance && (
          <div className="flex items-center justify-between">
            <span className="text-sm text-slate-400">Balance:</span>
            <div className="text-right">
              <div className="font-semibold">
                {parseFloat(formatEther(balance.value)).toFixed(4)} {balance.symbol}
              </div>
              <div className="text-xs text-slate-500">
                Auto-refreshing every 15s
              </div>
            </div>
          </div>
        )}

        {/* Balance Refresh Button */}
        <Button
          onClick={() => refetchBalance()}
          variant="outline"
          size="sm"
          className="w-full"
        >
          Refresh Balance
        </Button>

        {/* Connection Status */}
        <div className="text-xs text-slate-500 space-y-1">
          <p className="flex items-center">
            <CheckCircle className="mr-1 text-green-500" size={12} />
            Wallet securely connected
          </p>
          <p>• Balance updates automatically</p>
          <p>• You can now make predictions and earn rewards</p>
        </div>
      </CardContent>
    </Card>
  );
}

