                                variant="destructive" 
                                disabled={twoFACode.length !== 6 || isResetting}
                                className="bg-red-600 hover:bg-red-700 disabled:opacity-50"
                                onClick={async () => {
                                  console.log('🔐 [2FA] Verifying code:', twoFACode);

                                  if (!verify2FACode(twoFACode)) {
                                    toast({
                                      title: "Invalid 2FA Code",
                                      description: "Please check your code and try again",
                                      variant: "destructive"
                                    });
                                    return;
                                  }

                                  console.log('✅ [2FA] Code verified successfully');
                                  console.log('🚀 [RESET-DEBUG] Starting database reset with 2FA...');
                                  console.log('🔥 [RESET-DEBUG] Confirm Reset button clicked!');

                              if (resetConfirmText !== 'RESET') {
                                console.log('❌ [RESET-DEBUG] Invalid confirmation code:', resetConfirmText);
                                return;
                              }

                              console.log('🚀 [RESET-DEBUG] Starting reset process...');
                              console.log('🔍 [RESET-DEBUG] Confirm text:', resetConfirmText);

                              setIsResetting(true);

                              try {
                                console.log('📡 [RESET-DEBUG] Making API call to /api/admin/reset-database');
                                const response = await fetch('/api/admin/reset-database', {
                                  method: 'POST',
                                  headers: {
                                    'Content-Type': 'application/json',
                                    'X-Admin-Operation': 'database-reset',
                                    'X-Bypass-Rate-Limit': 'true',
                                    'X-Admin-IP-Override': 'true'
                                  },
                                  credentials: 'include',
                                  body: JSON.stringify({ confirmationCode: 'RESET' })
                                });

                                console.log('📄 [RESET-DEBUG] Response status:', response.status);
                                console.log('📄 [RESET-DEBUG] Response headers:', Object.fromEntries(response.headers.entries()));

                                let result;
                                try {
                                  result = await response.json();
                                  console.log('✅ [RESET-DEBUG] Reset response JSON:', result);
                                } catch (jsonError) {
                                  console.error('❌ [RESET-DEBUG] JSON parse error:', jsonError);
                                  const text = await response.text();
                                  console.log('📄 [RESET-DEBUG] Raw response text:', text);
                                  result = { message: 'Failed to parse response: ' + text };
                                }

                                if (response.ok && result.success) {
                                  console.log('🎉 [RESET-DEBUG] Reset successful!');
                                  toast({ 
                                    title: "Database Reset Successful", 
                                    description: "All data has been cleared. Page will reload...",
                                    variant: "default"
                                  });
                                  setTimeout(() => window.location.reload(), 2000);
                                } else {
                                  console.error('❌ [RESET-DEBUG] Reset failed:', result);
                                  toast({ 
                                    title: "Reset Failed", 
                                    description: result.message || result.error || 'Unknown error',
                                    variant: "destructive"
                                  });
                                }
                              } catch (error: any) {
                                console.error('❌ [RESET-DEBUG] Network/Fetch error:', error);
                                toast({ 
                                  title: "Network Error", 
                                  description: 'Reset failed: ' + error.message,
                                  variant: "destructive"
                                });
                                  } finally {
                                    setIsResetting(false);
                                    reset2FAState();
                                  }
                                }}
                              >
                                {isResetting ? "Resetting..." : "Confirm Reset"}
                              </Button>
                              <Button 
                                variant="outline" 
                                onClick={() => {
                                  setTwoFAStep(false);
                                  setTwoFACode('');
                                }}
                              >
                                Back
                              </Button>
                              <DialogTrigger asChild>
                                <Button variant="outline" onClick={reset2FAState}>Cancel</Button>
                              </DialogTrigger>
                            </div>
                          </>
                        )}
                      </div>
                    </DialogContent>
                  </Dialog>
                </div>
              </CardContent>
            </Card>
          </TabsContent>
        </Tabs>
      </div>

      {/* Event Edit/Create Dialog */}
      <Dialog open={isEventDialogOpen} onOpenChange={setIsEventDialogOpen}>
        <DialogContent className="bg-slate-800 border-slate-700 max-w-2xl">
          <DialogHeader>
            <DialogTitle className="text-white">
              {selectedEvent ? 'Edit Event' : 'Create Event'}
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-4 max-h-96 overflow-y-auto">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <Label className="text-white">Title *</Label>
                <Input
                  value={eventFormData.title}
                  onChange={(e) => setEventFormData(prev => ({ ...prev, title: e.target.value }))}
                  className="bg-slate-700 border-slate-600 text-white"
                  placeholder="Event title"
                  data-testid="input-event-title"
                />
              </div>
              <div>
                <Label className="text-white">Event Type</Label>
                <Select
                  value={eventFormData.eventType}
                  onValueChange={(value) => setEventFormData(prev => ({ ...prev, eventType: value }))}
                >
                  <SelectTrigger className="bg-slate-700 border-slate-600 text-white">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent className="bg-slate-700 border-slate-600">
                    <SelectItem value="announcement">Announcement</SelectItem>
                    <SelectItem value="competition">Competition</SelectItem>
                    <SelectItem value="maintenance">Maintenance</SelectItem>
                    <SelectItem value="update">Update</SelectItem>
                    <SelectItem value="promotion">Promotion</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div>
              <Label className="text-white">Description</Label>
              <Textarea
                value={eventFormData.description}
                onChange={(e) => setEventFormData(prev => ({ ...prev, description: e.target.value }))}
                className="bg-slate-700 border-slate-600 text-white"
                placeholder="Event description"
                rows={3}
                data-testid="textarea-event-description"
              />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <Label className="text-white">Start Date</Label>
                <Input
                  type="date"
                  value={eventFormData.startDate}
                  onChange={(e) => setEventFormData(prev => ({ ...prev, startDate: e.target.value }))}
                  className="bg-slate-700 border-slate-600 text-white"
                  data-testid="input-event-start-date"
                />
              </div>
              <div>
                <Label className="text-white">End Date</Label>
                <Input
                  type="date"
                  value={eventFormData.endDate}
                  onChange={(e) => setEventFormData(prev => ({ ...prev, endDate: e.target.value }))}
                  className="bg-slate-700 border-slate-600 text-white"
                  data-testid="input-event-end-date"
                />
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <Label className="text-white">Organizer</Label>
                <Input
                  value={eventFormData.organizer}
                  onChange={(e) => setEventFormData(prev => ({ ...prev, organizer: e.target.value }))}
                  className="bg-slate-700 border-slate-600 text-white"
                  placeholder="Event organizer"
                  data-testid="input-event-organizer"
                />
              </div>
              <div>
                <Label className="text-white">Location</Label>
                <Input
                  value={eventFormData.location}
                  onChange={(e) => setEventFormData(prev => ({ ...prev, location: e.target.value }))}
                  className="bg-slate-700 border-slate-600 text-white"
                  placeholder="Event location"
                  data-testid="input-event-location"
                />
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <Label className="text-white">Image URL</Label>
                <Input
                  value={eventFormData.imageUrl}
                  onChange={(e) => setEventFormData(prev => ({ ...prev, imageUrl: e.target.value }))}
                  className="bg-slate-700 border-slate-600 text-white"
                  placeholder="https://example.com/image.jpg"
                  data-testid="input-event-image-url"
                />
              </div>
              <div>
                <Label className="text-white">Link URL</Label>
                <Input
                  value={eventFormData.linkUrl}
                  onChange={(e) => setEventFormData(prev => ({ ...prev, linkUrl: e.target.value }))}
                  className="bg-slate-700 border-slate-600 text-white"
                  placeholder="https://example.com"
                  data-testid="input-event-link-url"
                />
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div>
                <Label className="text-white">Priority</Label>
                <Input
                  type="number"
                  value={eventFormData.priority}
                  onChange={(e) => setEventFormData(prev => ({ ...prev, priority: parseInt(e.target.value) || 0 }))}
                  className="bg-slate-700 border-slate-600 text-white"
                  placeholder="0"
                  min="0"
                  data-testid="input-event-priority"
                />
              </div>
              <div className="flex items-center space-x-2">
                <Switch
                  checked={eventFormData.isActive}
                  onCheckedChange={(checked) => setEventFormData(prev => ({ ...prev, isActive: checked }))}
                  data-testid="switch-event-active"
                />
                <Label className="text-white">Active</Label>
              </div>
              <div className="flex items-center space-x-2">
                <Switch
                  checked={eventFormData.isFeatured}
                  onCheckedChange={(checked) => setEventFormData(prev => ({ ...prev, isFeatured: checked }))}
                  data-testid="switch-event-featured"
                />
                <Label className="text-white">Featured</Label>
              </div>
            </div>
          </div>

          <div className="flex justify-end gap-2 mt-6">
            <Button
              variant="outline"
              onClick={() => setIsEventDialogOpen(false)}
              data-testid="button-cancel-event"
            >
              Cancel
            </Button>
            <Button
              onClick={handleSaveEvent}
              disabled={createEventMutation.isPending || updateEventMutation.isPending}
              className="bg-blue-600 hover:bg-blue-700"
              data-testid="button-save-event"
            >
              {createEventMutation.isPending || updateEventMutation.isPending 
                ? "Saving..." 
                : selectedEvent ? "Update Event" : "Create Event"
              }
            </Button>
          </div>
        </DialogContent>
      </Dialog>

      <Footer />
    </div>
  );
}

