import { Header } from "@/components/header";
import { Footer } from "@/components/footer";
import { HeroStats } from "@/components/hero-stats";
import { PredictionForm } from "@/components/prediction-form";
import { ActivePredictions } from "@/components/active-predictions";
import { LivePrices } from "@/components/live-prices";
import { RecentRewards } from "@/components/recent-rewards";
import { TopPredictors } from "@/components/top-predictors";

import { useRainbowAuth } from "@/hooks/useRainbowAuth";
import { RainbowConnectButton } from "@/components/RainbowConnectButton";

import { PredictionBattles } from "@/components/prediction-battles";
import { BannerSection } from "@/components/banner-section";
import { EventsSection } from "@/components/events-section";
import { MarketSentimentDashboard } from "@/components/market-sentiment-dashboard";
import { TopMovers } from "@/components/top-movers";
import { PlatformActivity } from "@/components/platform-activity";
import { PredictionInsights } from "@/components/prediction-insights";
import TradingViewChart from "@/components/TradingViewChart";
import { useState, useEffect } from "react";
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { BarChart3, Target, TrendingUp, Users, Award, Zap } from "lucide-react";
import type { CryptoPrice } from "@/types";
import type { User as UserType } from "@shared/schema";
import "../styles/mobile-admin.css";



export default function Dashboard() {
  const [selectedCryptoId, setSelectedCryptoId] = useState<string | null>(null);
  const [showChart, setShowChart] = useState(false);
  const [showPredictionForm, setShowPredictionForm] = useState(false);
  const [preSelectedForPrediction, setPreSelectedForPrediction] = useState<string | undefined>(undefined);

  // Use Rainbow Kit authentication
  const { user, isConnected } = useRainbowAuth();

  // Fetch live prices with optimized intervals to prevent rate limiting
  const { data: livePrices = [] } = useQuery<CryptoPrice[]>({
    queryKey: ["/api/crypto/prices"],
    queryFn: async () => {
      const res = await fetch("/api/crypto/prices", {
        credentials: "include",
      });
      if (!res.ok) throw new Error(`HTTP error! status: ${res.status}`);
      return res.json();
    },
    refetchInterval: 60000, // Reduced to 1 minute to prevent overwhelming server
    refetchIntervalInBackground: false, // Disable background updates
    staleTime: 45000, // 45 seconds stale time
  });

  // Auto-select Bitcoin as default when prices are loaded
  useEffect(() => {
    if (livePrices.length > 0 && !selectedCryptoId) {
      const bitcoin = livePrices.find(crypto => crypto.id === 'bitcoin');
      if (bitcoin) {
        setSelectedCryptoId('bitcoin');
        setShowChart(true);
      }
    }
  }, [livePrices, selectedCryptoId]);

  // Find the currently selected crypto from live prices
  const selectedCrypto = selectedCryptoId 
    ? livePrices.find(crypto => crypto.id === selectedCryptoId) 
    : null;

  const handleCryptoSelect = (crypto: CryptoPrice) => {
    setSelectedCryptoId(crypto.id);
    setShowChart(true);
  };

  const handlePredictClick = (cryptoId: string) => {
    // If not connected, user needs to connect wallet first
    if (!isConnected) {
      return; // Rainbow Kit button will handle connection
    }

    setPreSelectedForPrediction(cryptoId);
    setShowPredictionForm(true);
    // Scroll to prediction form
    setTimeout(() => {
      const form = document.querySelector('[data-prediction-form]');
      if (form) {
        form.scrollIntoView({ behavior: 'smooth' });
      }
    }, 100);
  };

  // Create different content based on authentication state
  const renderUnauthenticatedHome = () => (
    <div className="min-h-screen bg-background">
      <Header />

      <main className="max-w-7xl mx-auto px-2 sm:px-4 lg:px-8 py-2 sm:py-4 md:py-8">
        {/* Welcome Section for Unauthenticated Users */}
        <div className="text-center py-4 sm:py-6 mb-4 sm:mb-6">
          <h1 className="text-2xl sm:text-3xl lg:text-4xl font-bold mb-4 bg-gradient-to-r from-cyan-500 to-blue-500 bg-clip-text text-transparent">
            Welcome to Nectiq
          </h1>
          <p className="text-base sm:text-lg lg:text-xl text-muted-foreground mb-6 max-w-2xl mx-auto px-4 sm:px-0">
            Accuracy-based cryptocurrency price prediction platform. Predict prices, join battles, and earn NTIQ tokens.
          </p>
        </div>

        {/* Live Prices Section - Moved to Top */}
        <div className="mb-4 sm:mb-6">
          <LivePrices onCryptoSelect={handleCryptoSelect} />
        </div>

        {/* Chart Section - Full Width */}
        {showChart && selectedCrypto && (
          <div className="mb-24">
            <Card>
              <CardContent className="p-0">
                <TradingViewChart 
                  cryptoId={selectedCrypto.id}
                />
              </CardContent>
            </Card>
          </div>
        )}

        {/* Feature Cards for Unauthenticated Users - Full Width */}
        <div className="grid grid-cols-3 gap-6 mt-20 mb-12">
          <Card className="text-center p-6 sm:p-8">
            <div className="w-12 h-12 sm:w-14 sm:h-14 bg-gradient-to-r from-cyan-500 to-blue-500 rounded-full flex items-center justify-center mx-auto mb-4 sm:mb-6">
              <Target className="w-6 h-6 sm:w-7 sm:h-7 text-white" />
            </div>
            <h3 className="text-lg sm:text-xl font-semibold mb-3">Price Prediction</h3>
            <p className="text-muted-foreground text-sm sm:text-base">
              Predict cryptocurrency prices across various timeframes and earn rewards based on accuracy
            </p>
          </Card>

          <Card className="text-center p-6 sm:p-8">
            <div className="w-12 h-12 sm:w-14 sm:h-14 bg-gradient-to-r from-green-500 to-teal-500 rounded-full flex items-center justify-center mx-auto mb-4 sm:mb-6">
              <Users className="w-6 h-6 sm:w-7 sm:h-7 text-white" />
            </div>
            <h3 className="text-lg sm:text-xl font-semibold mb-3">Battle Mode</h3>
            <p className="text-muted-foreground text-sm sm:text-base">
              Challenge other users in prediction battles and win total rewards from both parties
            </p>
          </Card>

          <Card className="text-center p-6 sm:p-8">
            <div className="w-12 h-12 sm:w-14 sm:h-14 bg-gradient-to-r from-yellow-500 to-orange-500 rounded-full flex items-center justify-center mx-auto mb-4 sm:mb-6">
              <Award className="w-6 h-6 sm:w-7 sm:h-7 text-white" />
            </div>
            <h3 className="text-lg sm:text-xl font-semibold mb-3">NTIQ Rewards</h3>
            <p className="text-muted-foreground text-sm sm:text-base">
              Earn NTIQ tokens as rewards for accurate predictions and use them for various platform features
            </p>
          </Card>
        </div>


        {/* Platform Stats - Full Width */}
        <div className="mt-16">
          <HeroStats />
        </div>
      </main>

      <Footer />
    </div>
  );

  const renderAuthenticatedHome = () => (
    <div className="min-h-screen bg-background text-foreground">
      <Header />

      <main className="max-w-7xl mx-auto px-2 sm:px-4 lg:px-8 py-2 sm:py-4 md:py-8">
        {/* Live Prices Section - Moved to Top */}
        <div className="mb-4 sm:mb-6">
          <LivePrices 
            onCryptoSelect={handleCryptoSelect}
            onPredictClick={handlePredictClick}
          />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-4 sm:gap-6">
          {/* Main Content - Chart Section (Now Takes More Space) */}
          <div className="lg:col-span-2 space-y-4 sm:space-y-6">
            {/* Chart Section */}
            {selectedCrypto && showChart ? (
              <>
                <Card>
                  <CardContent className="p-0">
                    <TradingViewChart
                      cryptoId={selectedCrypto.id}
                    />
                  </CardContent>
                </Card>

                {/* Make Prediction Button Below Chart */}
                <div className="mb-6">
                  <Button 
                    onClick={() => selectedCrypto && handlePredictClick(selectedCrypto.id)}
                    className="w-full bg-gradient-to-r from-cyan-500 to-blue-500 hover:from-cyan-600 hover:to-blue-600 text-white font-semibold py-3 rounded-lg shadow-lg hover:shadow-xl transform hover:scale-105 transition-all duration-200"
                  >
                    <Target className="w-5 h-5 mr-2" />
                    Make Prediction
                  </Button>
                </div>
              </>
            ) : (
              <Card className="bg-surface-light border-border-subtle mb-6">
                <CardContent className="p-4 sm:p-8 text-center">
                  <BarChart3 className="h-12 w-12 sm:h-16 sm:w-16 text-gray-400 mx-auto mb-3 sm:mb-4" />
                  <h3 className="text-base sm:text-lg font-medium text-gray-300 mb-2">
                    Select a Cryptocurrency
                  </h3>
                  <p className="text-sm sm:text-base text-gray-500">
                    Choose a cryptocurrency from Live Prices to view its interactive chart and start making predictions.
                  </p>
                </CardContent>
              </Card>
            )}

            {/* Active Predictions */}
            <ActivePredictions />

            {/* Events Section */}
            <EventsSection />
          </div>

          {/* Right Sidebar */}
          <div className="lg:col-span-1">
            <div className="flex flex-col space-y-6 h-full min-h-[600px] sticky top-4">
              {/* Top Predictors */}
              <div>
                <TopPredictors />
              </div>

              {/* Recent Rewards */}
              <div className="flex-1">
                <RecentRewards />
              </div>
            </div>
          </div>
        </div>

        {/* Banner Section - Horizontal Layout Above Live Activity */}
        <div className="mt-8">
          <BannerSection position="below_live_prices" className="horizontal-banners" />
        </div>

        {/* Market Sentiment Dashboard - 3 Column Layout */}
        <div className="mt-6">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* Column 1: Market Sentiment */}
            <div>
              <MarketSentimentDashboard />
            </div>

            {/* Column 2: Top Movers */}
            <div>
              <TopMovers />
            </div>

            {/* Column 3: Prediction Insights */}
            <div>
              <PredictionInsights />
            </div>
          </div>
        </div>
      </main>

      {/* Prediction Form Modal */}
      {showPredictionForm && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-surface border border-surface-light rounded-xl p-6 w-full max-w-2xl max-h-[90vh] overflow-y-auto shadow-2xl">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-2xl font-bold text-white">Make New Prediction</h2>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => {
                  setShowPredictionForm(false);
                  setPreSelectedForPrediction(undefined);
                }}
                className="text-slate-400 hover:text-white hover:bg-slate-700 rounded-full w-8 h-8 p-0"
              >
                ×
              </Button>
            </div>
            <PredictionForm 
              preSelectedCrypto={preSelectedForPrediction}
              onSuccess={() => {
                setShowPredictionForm(false);
                setPreSelectedForPrediction(undefined);
              }}
            />
          </div>
        </div>
      )}

      <Footer />

      {/* Wallet requirement functionality removed */}
    </div>
  );

  // Return different content based on authentication
  return isConnected ? renderAuthenticatedHome() : renderUnauthenticatedHome();
}

client/src/pages/landing.tsx.content:
import { TrendingUp, Trophy, Zap, Wallet } from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { useQuery } from "@tanstack/react-query";
import { useLocation } from "wouter";
import nectiqLogo from "@/assets/nectiq-logo.png";
import { PlatformStats } from "@/components/platform-stats";

interface CryptoPrice {
  id: string;
  symbol: string;
  name: string;
  current_price: number;
  price_change_percentage_24h: number;
  image?: string;
}

function CryptoPriceTicker() {
  const { data: prices = [] } = useQuery<CryptoPrice[]>({
    queryKey: ["/api/crypto/prices"],
    refetchInterval: 2000, // Update every 2 seconds
    refetchIntervalInBackground: true,
    staleTime: 30000, // 30 seconds
  });

  if (!prices.length) return null;

  return (
    <div className="fixed bottom-0 left-0 right-0 bg-black/90 backdrop-blur-sm border-t border-gray-800 overflow-hidden">
      <div className="ticker-container py-3">
        <div className="ticker-content animate-scroll">
          {/* Triple the array to create longer seamless loop */}
          {[...prices, ...prices, ...prices].map((crypto, index) => {
            const isPositive = crypto.price_change_percentage_24h >= 0;
            return (
              <div key={`${crypto.id}-${index}`} className="flex items-center space-x-3 text-sm whitespace-nowrap">
                <div className="flex items-center space-x-2">
                  <img 
                    src={crypto.image || `https://coin-images.coingecko.com/coins/images/${
                      crypto.id === 'bitcoin' ? '1' : 
                      crypto.id === 'ethereum' ? '279' : 
                      crypto.id === 'binancecoin' ? '825' : 
                      crypto.id === 'cardano' ? '975' : 
                      crypto.id === 'solana' ? '4128' : 
                      crypto.id === 'chainlink' ? '877' : 
                      crypto.id === 'polkadot' ? '12171' : 
                      crypto.id === 'litecoin' ? '2' : 
                      crypto.id === 'matic-network' ? '4713' : 
                      crypto.id === 'tron' ? '1094' : 
                      crypto.id === 'stellar' ? '100' : 
                      crypto.id === 'hyperliquid' ? '44077' : 
                      crypto.id === 'sahara-ai' ? '66681' : '1'
                    }/large/${crypto.id}.png`} 
                    alt={crypto.name}
                    className="w-6 h-6 rounded-full"
                  />
                  <span className="text-white font-medium">{crypto.symbol.toUpperCase()}</span>
                </div>
                <span className="text-gray-300">
                  ${crypto.current_price.toLocaleString(undefined, {
                    minimumFractionDigits: 2,
                    maximumFractionDigits: crypto.current_price >= 1 ? 2 : 6
                  })}
                </span>
                <span className={`${isPositive ? 'text-green-400' : 'text-red-400'} font-medium`}>
                  {isPositive ? '+' : ''}{crypto.price_change_percentage_24h.toFixed(2)}%
                </span>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

