import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { AlertTriangle, Eye, Shield, Users, Activity, CheckCircle, XCircle } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { apiRequest } from "@/lib/queryClient";

interface AbuseDetection {
  id: number;
  primaryUserId: number;
  suspiciousUserId: number;
  abuseType: string;
  similarityScore: number;
  evidenceData: any;
  status: string;
  actionTaken?: string;
  createdAt: string;
  primaryUser: {
    id: number;
    username: string;
    walletAddress: string;
  };
  suspiciousUser: {
    id: number;
    username: string;
    walletAddress: string;
  };
}

interface WalletFingerprint {
  id: number;
  userId: number;
  walletAddress: string;
  ipAddress: string;
  userAgent: string;
  browserFingerprint?: string;
  deviceFingerprint?: string;
  screenResolution?: string;
  timezone?: string;
  language?: string;
  platform?: string;
  createdAt: string;
  lastSeen: string;
  isActive: boolean;
}

export function AbuseManagement() {
  const [selectedStatus, setSelectedStatus] = useState<string>("all");
  const [selectedDetection, setSelectedDetection] = useState<AbuseDetection | null>(null);
  const { toast } = useToast();
  const queryClient = useQueryClient();

  // Fetch abuse detections
  const { data: detections = [], isLoading } = useQuery<AbuseDetection[]>({
    queryKey: ["/api/admin/abuse-detections", selectedStatus],
    queryFn: async () => {
      const params = selectedStatus !== "all" ? `?status=${selectedStatus}` : "";
      return await apiRequest("GET", `/api/admin/abuse-detections${params}`);
    },
  });

  // Update abuse detection
  const updateDetectionMutation = useMutation({
    mutationFn: async ({ id, status, actionTaken }: { id: number; status: string; actionTaken?: string }) => {
      return await apiRequest("PUT", `/api/admin/abuse-detections/${id}`, { status, actionTaken });
    },
    onSuccess: () => {
      toast({ title: "Success", description: "Abuse detection updated successfully" });
      queryClient.invalidateQueries({ queryKey: ["/api/admin/abuse-detections"] });
      setSelectedDetection(null);
    },
    onError: () => {
      toast({ title: "Error", description: "Failed to update abuse detection", variant: "destructive" });
    },
  });

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'pending': return 'bg-yellow-500';
      case 'confirmed': return 'bg-red-500';
      case 'false_positive': return 'bg-green-500';
      case 'resolved': return 'bg-blue-500';
      default: return 'bg-gray-500';
    }
  };

  const getSimilarityColor = (score: number) => {
    if (score >= 0.9) return 'text-red-500';
    if (score >= 0.7) return 'text-orange-500';
    if (score >= 0.5) return 'text-yellow-500';
    return 'text-green-500';
  };

  const handleUpdateDetection = (status: string, actionTaken?: string) => {
    if (!selectedDetection) return;
    updateDetectionMutation.mutate({
      id: selectedDetection.id,
      status,
      actionTaken
    });
  };

  if (isLoading) {
    return (
      <div className="space-y-6">
        <div className="animate-pulse">
          <div className="h-8 bg-surface-light rounded w-1/4 mb-4"></div>
          <div className="space-y-3">
            {[...Array(5)].map((_, i) => (
              <div key={i} className="h-20 bg-surface-light rounded"></div>
            ))}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-3">
          <Shield className="h-8 w-8 text-red-500" />
          <h2 className="text-2xl font-bold text-white">Anti-Multi Wallet Abuse</h2>
        </div>

        <div className="flex items-center space-x-3">
          <Select value={selectedStatus} onValueChange={setSelectedStatus}>
            <SelectTrigger className="w-40">
              <SelectValue placeholder="Filter Status" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Status</SelectItem>
              <SelectItem value="pending">Pending</SelectItem>
              <SelectItem value="confirmed">Confirmed</SelectItem>
              <SelectItem value="false_positive">False Positive</SelectItem>
              <SelectItem value="resolved">Resolved</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>

      <Tabs defaultValue="detections" className="space-y-4">
        <TabsList className="grid w-full grid-cols-2">
          <TabsTrigger value="detections" className="flex items-center space-x-2">
            <AlertTriangle className="h-4 w-4" />
            <span>Abuse Detections ({detections.length})</span>
          </TabsTrigger>
          <TabsTrigger value="statistics" className="flex items-center space-x-2">
            <Activity className="h-4 w-4" />
            <span>Statistics</span>
          </TabsTrigger>
        </TabsList>

        <TabsContent value="detections" className="space-y-4">
          {detections.length === 0 ? (
            <Card className="bg-surface border-border-subtle">
              <CardContent className="p-8 text-center">
                <Shield className="h-16 w-16 text-gray-400 mx-auto mb-4" />
                <h3 className="text-lg font-medium text-gray-300 mb-2">No Abuse Detected</h3>
                <p className="text-gray-500">
                  {selectedStatus === "all" 
                    ? "No multi-wallet abuse has been detected yet." 
                    : `No ${selectedStatus} abuse detections found.`}
                </p>
              </CardContent>
            </Card>
          ) : (
            <div className="grid grid-cols-1 gap-4">
              {detections.map((detection) => (
                <Card key={detection.id} className="bg-surface border-border-subtle hover:border-primary/50 transition-colors">
                  <CardContent className="p-6">
                    <div className="flex items-start justify-between">
                      <div className="space-y-3 flex-1">
                        <div className="flex items-center space-x-3">
                          <Badge className={`${getStatusColor(detection.status)} text-white`}>
                            {detection.status.replace('_', ' ').toUpperCase()}
                          </Badge>
                          <Badge variant="outline" className="text-primary border-primary">
                            {detection.abuseType.replace('_', ' ').toUpperCase()}
                          </Badge>
                          <span className={`font-bold text-lg ${getSimilarityColor(detection.similarityScore)}`}>
                            {Math.round(detection.similarityScore * 100)}% Match
                          </span>
                        </div>

                        <div className="grid grid-cols-2 gap-6">
                          <div>
                            <h4 className="font-medium text-gray-300 mb-2">Primary User</h4>
                            <div className="space-y-1">
                              <p className="text-white font-medium">{detection.primaryUser?.username}</p>
                              <p className="text-gray-400 text-sm font-mono">
                                {detection.primaryUser?.walletAddress}
                              </p>
                            </div>
                          </div>

                          <div>
                            <h4 className="font-medium text-gray-300 mb-2">Suspicious User</h4>
                            <div className="space-y-1">
                              <p className="text-white font-medium">{detection.suspiciousUser?.username}</p>
                              <p className="text-gray-400 text-sm font-mono">
                                {detection.suspiciousUser?.walletAddress}
                              </p>
                            </div>
                          </div>
                        </div>

                        <div className="text-sm text-gray-400">
                          Detected: {new Date(detection.createdAt).toLocaleDateString('id-ID', {
                            year: 'numeric',
                            month: 'long',
                            day: 'numeric',
                            hour: '2-digit',
                            minute: '2-digit'
                          })}
                          {detection.actionTaken && (
                            <span className="ml-4">Action: <span className="text-primary">{detection.actionTaken}</span></span>
                          )}
                        </div>
                      </div>

                      <div className="flex space-x-2 ml-4">
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => setSelectedDetection(detection)}
                          className="text-primary border-primary hover:bg-primary/10"
                        >
                          <Eye className="h-4 w-4 mr-1" />
                          Detail
                        </Button>

                        {detection.status === 'pending' && (
                          <>
                            <Button
                              variant="outline"
                              size="sm"
                              onClick={() => handleUpdateDetection('confirmed', 'warning_issued')}
                              className="text-red-500 border-red-500 hover:bg-red-500/10"
                            >
                              <AlertTriangle className="h-4 w-4 mr-1" />
                              Confirm
                            </Button>
                            <Button
                              variant="outline"
                              size="sm"
                              onClick={() => handleUpdateDetection('false_positive')}
                              className="text-green-500 border-green-500 hover:bg-green-500/10"
                            >
                              <CheckCircle className="h-4 w-4 mr-1" />
                              False Positive
                            </Button>
                          </>
                        )}
                      </div>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          )}
        </TabsContent>

        <TabsContent value="statistics" className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <Card className="bg-surface border-border-subtle">
              <CardContent className="p-6">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-gray-400 text-sm">Total Detections</p>
                    <p className="text-2xl font-bold text-white">{detections.length}</p>
                  </div>
                  <AlertTriangle className="h-8 w-8 text-yellow-500" />
                </div>
              </CardContent>
            </Card>

            <Card className="bg-surface border-border-subtle">
              <CardContent className="p-6">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-gray-400 text-sm">Pending Review</p>
                    <p className="text-2xl font-bold text-yellow-500">
                      {detections.filter(d => d.status === 'pending').length}
                    </p>
                  </div>
                  <Eye className="h-8 w-8 text-yellow-500" />
                </div>
              </CardContent>
            </Card>

            <Card className="bg-surface border-border-subtle">
              <CardContent className="p-6">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-gray-400 text-sm">Confirmed Abuse</p>
                    <p className="text-2xl font-bold text-red-500">
                      {detections.filter(d => d.status === 'confirmed').length}
                    </p>
                  </div>
                  <XCircle className="h-8 w-8 text-red-500" />
                </div>
              </CardContent>
            </Card>

            <Card className="bg-surface border-border-subtle">
              <CardContent className="p-6">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-gray-400 text-sm">False Positives</p>
                    <p className="text-2xl font-bold text-green-500">
                      {detections.filter(d => d.status === 'false_positive').length}
                    </p>
                  </div>
                  <CheckCircle className="h-8 w-8 text-green-500" />
                </div>
              </CardContent>
            </Card>
          </div>

          <Card className="bg-surface border-border-subtle">
            <CardHeader>
              <CardTitle className="text-white">Detection Overview</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                <div>
                  <h4 className="font-medium text-gray-300 mb-2">High Risk Detections (90%+ Match)</h4>
                  <div className="text-2xl font-bold text-red-500">
                    {detections.filter(d => d.similarityScore >= 0.9).length}
                  </div>
                </div>

                <div>
                  <h4 className="font-medium text-gray-300 mb-2">Medium Risk Detections (70-89% Match)</h4>
                  <div className="text-2xl font-bold text-orange-500">
                    {detections.filter(d => d.similarityScore >= 0.7 && d.similarityScore < 0.9).length}
                  </div>
                </div>

                <div>
                  <h4 className="font-medium text-gray-300 mb-2">Low Risk Detections (50-69% Match)</h4>
                  <div className="text-2xl font-bold text-yellow-500">
                    {detections.filter(d => d.similarityScore >= 0.5 && d.similarityScore < 0.7).length}
                  </div>
                </div>
              </div>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>

      {/* Detection Detail Modal */}
      {selectedDetection && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-surface border border-surface-light rounded-xl p-6 w-full max-w-4xl max-h-[90vh] overflow-y-auto shadow-2xl">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-2xl font-bold text-white">Abuse Detection Detail</h2>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setSelectedDetection(null)}
                className="text-slate-400 hover:text-white hover:bg-slate-700 rounded-full w-8 h-8 p-0"
              >
                ×
              </Button>
            </div>

            <div className="space-y-6">
              <div className="grid grid-cols-2 gap-6">
                <div>
                  <h3 className="font-medium text-gray-300 mb-3">Detection Info</h3>
                  <div className="space-y-2">
                    <div className="flex justify-between">
                      <span className="text-gray-400">ID:</span>
                      <span className="text-white">#{selectedDetection.id}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-gray-400">Type:</span>
                      <Badge variant="outline">{selectedDetection.abuseType}</Badge>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-gray-400">Similarity:</span>
                      <span className={`font-bold ${getSimilarityColor(selectedDetection.similarityScore)}`}>
                        {Math.round(selectedDetection.similarityScore * 100)}%
                      </span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-gray-400">Status:</span>
                      <Badge className={`${getStatusColor(selectedDetection.status)} text-white`}>
                        {selectedDetection.status}
                      </Badge>
                    </div>
                  </div>
                </div>

                <div>
                  <h3 className="font-medium text-gray-300 mb-3">Evidence Breakdown</h3>
                  {selectedDetection.evidenceData?.similarityBreakdown && (
                    <div className="space-y-2">
                      <div className="flex justify-between">
                        <span className="text-gray-400">IP Match:</span>
                        <span className={selectedDetection.evidenceData.similarityBreakdown.ipMatch ? 'text-red-500' : 'text-green-500'}>
                          {selectedDetection.evidenceData.similarityBreakdown.ipMatch ? 'Yes' : 'No'}
                        </span>
                      </div>
                      <div className="flex justify-between">
                        <span className="text-gray-400">Device Match:</span>
                        <span className={selectedDetection.evidenceData.similarityBreakdown.deviceMatch ? 'text-red-500' : 'text-green-500'}>
                          {selectedDetection.evidenceData.similarityBreakdown.deviceMatch ? 'Yes' : 'No'}
                        </span>
                      </div>
                      <div className="flex justify-between">
                        <span className="text-gray-400">Browser Match:</span>
                        <span className={selectedDetection.evidenceData.similarityBreakdown.browserMatch ? 'text-red-500' : 'text-green-500'}>
                          {selectedDetection.evidenceData.similarityBreakdown.browserMatch ? 'Yes' : 'No'}
                        </span>
                      </div>
                      <div className="flex justify-between">
                        <span className="text-gray-400">User Agent Match:</span>
                        <span className={selectedDetection.evidenceData.similarityBreakdown.userAgentMatch ? 'text-red-500' : 'text-green-500'}>
                          {selectedDetection.evidenceData.similarityBreakdown.userAgentMatch ? 'Yes' : 'No'}
                        </span>
                      </div>
                    </div>
                  )}
                </div>
              </div>

              {selectedDetection.status === 'pending' && (
                <div className="flex space-x-3 pt-4 border-t border-surface-light">
                  <Button
                    onClick={() => handleUpdateDetection('confirmed', 'warning_issued')}
                    className="bg-red-500 hover:bg-red-600 text-white"
                    disabled={updateDetectionMutation.isPending}
                  >
                    <AlertTriangle className="h-4 w-4 mr-2" />
                    Confirm Abuse & Issue Warning
                  </Button>
                  <Button
                    onClick={() => handleUpdateDetection('confirmed', 'account_restricted')}
                    variant="outline"
                    className="text-red-500 border-red-500 hover:bg-red-500/10"
                    disabled={updateDetectionMutation.isPending}
                  >
                    <XCircle className="h-4 w-4 mr-2" />
                    Confirm Abuse & Restrict Account
                  </Button>
                  <Button
                    onClick={() => handleUpdateDetection('false_positive')}
                    variant="outline"
                    className="text-green-500 border-green-500 hover:bg-green-500/10"
                    disabled={updateDetectionMutation.isPending}
                  >
                    <CheckCircle className="h-4 w-4 mr-2" />
                    Mark as False Positive
                  </Button>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

client/src/components/admin/banner-manag.content:
import { useState, useRef } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { useToast } from "@/hooks/use-toast";
import { Plus, Edit, Trash2, ExternalLink, Image, Calendar, Upload, X } from "lucide-react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";

interface Banner {
  id: number;
  title: string;
  description: string;
  imageUrl: string;
  linkUrl?: string;
  isActive: boolean;
  position: string;
  priority: number;
  startDate?: string;
  endDate?: string;
  createdAt: string;
  updatedAt: string;
}

export function BannerManagement() {
  const [showCreateDialog, setShowCreateDialog] = useState(false);
  const [editingBanner, setEditingBanner] = useState<Banner | null>(null);
  const [formData, setFormData] = useState({
    title: "",
    description: "",
    imageUrl: "",
    linkUrl: "",
    isActive: true,
    position: "below_live_prices",
    priority: 0,
    startDate: "",
    endDate: ""
  });
  const [uploadedFile, setUploadedFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string>("");
  const [isUploading, setIsUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const { toast } = useToast();
  const queryClient = useQueryClient();

  const { data: banners = [], isLoading } = useQuery<Banner[]>({
    queryKey: ["/api/admin/banners"],
  });

  const uploadImageMutation = useMutation({
    mutationFn: async (file: File) => {
      const formData = new FormData();
      formData.append('image', file);

      const response = await fetch('/api/admin/upload-banner-image', {
        method: 'POST',
        body: formData,
      });

      if (!response.ok) {
        throw new Error('Failed to upload image');
      }

      return response.json();
    },
    onSuccess: (data) => {
      setFormData(prev => ({ ...prev, imageUrl: data.imageUrl }));
      toast({ title: "Success", description: "Image uploaded successfully" });
      setIsUploading(false);
    },
    onError: (error: any) => {
      toast({ title: "Error", description: error.message || "Failed to upload image", variant: "destructive" });
      setIsUploading(false);
    },
  });

  const createBannerMutation = useMutation({
    mutationFn: async (bannerData: any) => {
      const response = await fetch("/api/admin/banners", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(bannerData),
      });
      if (!response.ok) throw new Error("Failed to create banner");
      return response.json();
    },
    onSuccess: () => {
      toast({ title: "Success", description: "Banner created successfully" });
      queryClient.invalidateQueries({ queryKey: ["/api/admin/banners"] });
      queryClient.invalidateQueries({ queryKey: ["/api/banners"] });
      setShowCreateDialog(false);
      resetForm();
    },
    onError: () => {
      toast({ title: "Error", description: "Failed to create banner", variant: "destructive" });
    },
  });

  const updateBannerMutation = useMutation({
    mutationFn: async ({ id, data }: { id: number; data: any }) => {
      const response = await fetch(`/api/admin/banners/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(data),
      });
      if (!response.ok) throw new Error("Failed to update banner");
      return response.json();
    },
    onSuccess: () => {
      toast({ title: "Success", description: "Banner updated successfully" });
      queryClient.invalidateQueries({ queryKey: ["/api/admin/banners"] });
      queryClient.invalidateQueries({ queryKey: ["/api/banners"] });
      setEditingBanner(null);
      resetForm();
    },
    onError: () => {
      toast({ title: "Error", description: "Failed to update banner", variant: "destructive" });
    },
  });

  const deleteBannerMutation = useMutation({
    mutationFn: async (id: number) => {
      const response = await fetch(`/api/admin/banners/${id}`, {
        method: "DELETE",
      });
      if (!response.ok) throw new Error("Failed to delete banner");
      return response.json();
    },
    onSuccess: () => {
      toast({ title: "Success", description: "Banner deleted successfully" });
      queryClient.invalidateQueries({ queryKey: ["/api/admin/banners"] });
      queryClient.invalidateQueries({ queryKey: ["/api/banners"] });
    },
    onError: () => {
      toast({ title: "Error", description: "Failed to delete banner", variant: "destructive" });
    },
  });

  const resetForm = () => {
    setFormData({
      title: "",
      description: "",
      imageUrl: "",
      linkUrl: "",
      isActive: true,
      position: "below_live_prices",
      priority: 0,
      startDate: "",
      endDate: ""
    });
    setUploadedFile(null);
    setPreviewUrl("");
    setIsUploading(false);
    if (fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      // Validate file type
      if (!file.type.startsWith('image/')) {
        toast({ title: "Error", description: "Please select a valid image file", variant: "destructive" });
        return;
      }

      // Validate file size (max 5MB)
      if (file.size > 5 * 1024 * 1024) {
        toast({ title: "Error", description: "Maximum image size is 5MB", variant: "destructive" });
        return;
      }

      setUploadedFile(file);

      // Create preview URL
      const reader = new FileReader();
      reader.onload = (e) => {
        setPreviewUrl(e.target?.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleUploadImage = () => {
    if (uploadedFile) {
      setIsUploading(true);
      uploadImageMutation.mutate(uploadedFile);
    }
  };

  const clearUploadedImage = () => {
    setUploadedFile(null);
    setPreviewUrl("");
    setFormData(prev => ({ ...prev, imageUrl: "" }));
    if (fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  };

  const handleEdit = (banner: Banner) => {
    setEditingBanner(banner);
    setFormData({
      title: banner.title,
      description: banner.description || "",
      imageUrl: banner.imageUrl,
      linkUrl: banner.linkUrl || "",
      isActive: banner.isActive,
      position: banner.position,
      priority: banner.priority,
      startDate: banner.startDate ? banner.startDate.split('T')[0] : "",
      endDate: banner.endDate ? banner.endDate.split('T')[0] : ""
    });
  };

  const handleSubmit = () => {
    if (!formData.title) {
      toast({ title: "Error", description: "Banner title is required", variant: "destructive" });
      return;
    }

    if (!formData.imageUrl) {
      toast({ title: "Error", description: "Please upload an image first", variant: "destructive" });
      return;
    }

    // Ensure proper date formatting
    const submitData = {
      ...formData,
      startDate: formData.startDate && formData.startDate !== "" ? formData.startDate : null,
      endDate: formData.endDate && formData.endDate !== "" ? formData.endDate : null,
      priority: parseInt(formData.priority.toString()) || 0
    };

    if (import.meta.env.DEV) {
      console.log("Submitting banner data:", submitData);
    }

    if (editingBanner) {
      updateBannerMutation.mutate({ id: editingBanner.id, data: submitData });
    } else {
      createBannerMutation.mutate(submitData);
    }
  };

  const getPositionLabel = (position: string) => {
    const labels = {
      'below_live_prices': 'Di Bawah Live Prices',
      'sidebar': 'Sidebar',
      'header': 'Header'
    };
    return labels[position as keyof typeof labels] || position;
  };

  if (isLoading) {
    return <div className="p-6">Loading...</div>;
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-white">Manajemen Banner</h2>
          <p className="text-gray-400">Kelola banner promo dan iklan untuk platform</p>
        </div>
        <Dialog open={showCreateDialog} onOpenChange={setShowCreateDialog}>
          <DialogTrigger asChild>
            <Button onClick={resetForm}>
              <Plus className="h-4 w-4 mr-2" />
              Tambah Banner
            </Button>
          </DialogTrigger>
          <DialogContent className="max-w-2xl">
            <DialogHeader>
              <DialogTitle>
                {editingBanner ? "Edit Banner" : "Tambah Banner Baru"}
              </DialogTitle>
            </DialogHeader>
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="title">Title *</Label>
                  <Input
                    id="title"
                    value={formData.title}
                    onChange={(e) => setFormData(prev => ({ ...prev, title: e.target.value }))}
                    placeholder="Judul banner"
                  />
                </div>
                <div>
                  <Label htmlFor="position">Posisi</Label>
                  <Select value={formData.position} onValueChange={(value) => setFormData(prev => ({ ...prev, position: value }))}>
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="below_live_prices">Di Bawah Live Prices</SelectItem>
                      <SelectItem value="sidebar">Sidebar</SelectItem>
                      <SelectItem value="header">Header</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div>
                <Label htmlFor="description">Deskripsi</Label>
                <Textarea
                  id="description"
                  value={formData.description}
                  onChange={(e) => setFormData(prev => ({ ...prev, description: e.target.value }))}
                  placeholder="Deskripsi banner"
                  rows={3}
                />
              </div>

              <div>
                <Label htmlFor="image">Upload Gambar Banner *</Label>
                <div className="space-y-4">
                  {/* File Upload Area */}
                  <div className="border-2 border-dashed border-gray-600 rounded-lg p-6 text-center">
                    <input
                      ref={fileInputRef}
                      type="file"
                      accept="image/*"
                      onChange={handleFileChange}
                      className="hidden"
                      id="banner-upload"
                    />

                    {!previewUrl ? (
                      <div className="space-y-2">
                        <Upload className="h-12 w-12 text-gray-400 mx-auto" />
                        <div>
                          <label
                            htmlFor="banner-upload"
                            className="cursor-pointer text-blue-400 hover:text-blue-300"
                          >
                            Klik untuk upload gambar
                          </label>
                          <p className="text-sm text-gray-500">atau drag & drop file di sini</p>
                        </div>
                        <p className="text-xs text-gray-600">PNG, JPG, JPEG, GIF (Max: 5MB)</p>
                      </div>
                    ) : (
                      <div className="space-y-3">
                        <div className="relative inline-block">
                          <img
                            src={previewUrl}
                            alt="Preview"
                            className="max-w-full max-h-40 rounded-lg"
                          />
                          <Button
                            type="button"
                            variant="destructive"
                            size="sm"
                            className="absolute -top-2 -right-2"
                            onClick={clearUploadedImage}
                          >
                            <X className="h-4 w-4" />
                          </Button>
                        </div>

                        {uploadedFile && !formData.imageUrl && (
                          <Button
                            type="button"
                            onClick={handleUploadImage}
                            disabled={isUploading}
                            className="bg-blue-600 hover:bg-blue-700"
                          >
                            {isUploading ? "Uploading..." : "Upload Gambar"}
                          </Button>
                        )}

                        {formData.imageUrl && (
                          <div className="text-sm text-green-400">
                            ✓ Image successfully uploaded
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                </div>
              </div>

              <div>
                <Label htmlFor="linkUrl">Link URL (opsional)</Label>
                <Input
                  id="linkUrl"
                  value={formData.linkUrl}
                  onChange={(e) => setFormData(prev => ({ ...prev, linkUrl: e.target.value }))}
                  placeholder="https://example.com"
                />
              </div>

              <div className="grid grid-cols-3 gap-4">
                <div>
                  <Label htmlFor="priority">Priority</Label>
                  <Input
                    id="priority"
                    type="number"
                    value={formData.priority}
                    onChange={(e) => setFormData(prev => ({ ...prev, priority: parseInt(e.target.value) || 0 }))}
                    placeholder="0"
                  />
                </div>
                <div>
                  <Label htmlFor="startDate">Tanggal Mulai</Label>
                  <Input
                    id="startDate"
                    type="date"
                    value={formData.startDate}
                    onChange={(e) => setFormData(prev => ({ ...prev, startDate: e.target.value }))}
                  />
                </div>
                <div>
                  <Label htmlFor="endDate">Tanggal Berakhir</Label>
                  <Input
                    id="endDate"
                    type="date"
                    value={formData.endDate}
                    onChange={(e) => setFormData(prev => ({ ...prev, endDate: e.target.value }))}
                  />
                </div>
              </div>

              <div className="flex items-center space-x-2">
                <Switch
                  id="isActive"
                  checked={formData.isActive}
                  onCheckedChange={(checked) => setFormData(prev => ({ ...prev, isActive: checked }))}
                />
                <Label htmlFor="isActive">Banner Aktif</Label>
              </div>

              <div className="flex justify-end gap-2">
                <Button variant="outline" onClick={() => {
                  setShowCreateDialog(false);
                  setEditingBanner(null);
                  resetForm();
                }}>
                  Batal
                </Button>
                <Button onClick={handleSubmit} disabled={createBannerMutation.isPending || updateBannerMutation.isPending}>
                  {editingBanner ? "Update" : "Simpan"}
                </Button>
              </div>
            </div>
          </DialogContent>
        </Dialog>
      </div>

      {/* Banner List */}
      <div className="grid gap-4">
        {banners.length === 0 ? (
          <Card>
            <CardContent className="p-6 text-center">
              <Image className="h-16 w-16 text-gray-400 mx-auto mb-4" />
              <h3 className="text-lg font-medium text-gray-300 mb-2">
                Belum Ada Banner
              </h3>
              <p className="text-gray-500 mb-4">
                Mulai dengan membuat banner pertama untuk platform Anda
              </p>
              <Button onClick={() => setShowCreateDialog(true)}>
                <Plus className="h-4 w-4 mr-2" />
                Tambah Banner
              </Button>
            </CardContent>
          </Card>
        ) : (
          banners.map((banner) => (
            <Card key={banner.id} className="overflow-hidden">
              <CardContent className="p-6">
                <div className="flex items-center gap-4">
                  {/* Banner Preview */}
                  <div className="flex-shrink-0">
                    <img
                      src={banner.imageUrl}
                      alt={banner.title}
                      className="w-24 h-16 object-cover rounded-lg border"
                      onError={(e) => {
                        (e.target as HTMLImageElement).src = 'data:image/svg+xml;base64,PHN2ZyB3aWR0aD0iOTYiIGhlaWdodD0iNjQiIHZpZXdCb3g9IjAgMCA5NiA2NCIgZmlsbD0ibm9uZSIgeG1sbnM9Imh0dHA6Ly93d3cudzMub3JnLzIwMDAvc3ZnIj4KPHJlY3Qgd2lkdGg9Ijk2IiBoZWlnaHQ9IjY0IiBmaWxsPSIjMzc0MTUxIi8+CjxwYXRoIGQ9Ik00OCAzMkw0MCAyNEw1NiAyNEw0OCAzMloiIGZpbGw9IiM2QjcyODAiLz4KPC9zdmc+';
                      }}
                    />
                  </div>

                  {/* Banner Info */}
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-2">
                      <h3 className="font-semibold text-white truncate">
                        {banner.title}
                      </h3>
                      <Badge variant={banner.isActive ? "default" : "secondary"}>
                        {banner.isActive ? "Aktif" : "Nonaktif"}
                      </Badge>
                      <Badge variant="outline">
                        {getPositionLabel(banner.position)}
                      </Badge>
                      {banner.priority > 0 && (
                        <Badge variant="outline">
                          Priority: {banner.priority}
                        </Badge>
                      )}
                    </div>

                    {banner.description && (
                      <p className="text-sm text-gray-400 mb-2 line-clamp-2">
                        {banner.description}
                      </p>
                    )}

                    <div className="flex items-center gap-4 text-xs text-gray-500">
                      {banner.linkUrl && (
                        <div className="flex items-center gap-1">
                          <ExternalLink className="h-3 w-3" />
                          <span>Link tersedia</span>
                        </div>
                      )}
                      {(banner.startDate || banner.endDate) && (
                        <div className="flex items-center gap-1">
                          <Calendar className="h-3 w-3" />
                          <span>
                            {banner.startDate && new Date(banner.startDate).toLocaleDateString('id-ID')}
                            {banner.startDate && banner.endDate && ' - '}
                            {banner.endDate && new Date(banner.endDate).toLocaleDateString('id-ID')}
                          </span>
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Actions */}
                  <div className="flex items-center gap-2">
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => {
                        handleEdit(banner);
                        setShowCreateDialog(true);
                      }}
                    >
                      <Edit className="h-4 w-4" />
                    </Button>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => deleteBannerMutation.mutate(banner.id)}
                      disabled={deleteBannerMutation.isPending}
                    >
                      <Trash2 className="h-4 w-4" />
                    </Button>
                  </div>
                </div>
              </CardContent>
            </Card>
          ))
        )}
      </div>
    </div>
  );
}

client/src/components/admin/user-growth-.content:
import React from 'react';
import { useQuery } from '@tanstack/react-query';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, AreaChart, Area } from 'recharts';
import { Calendar, TrendingUp, Users, Activity } from 'lucide-react';

interface GrowthData {
  dailyRegistrations: Array<{
    date: string;
    count: number;
    cumulative: number;
  }>;
  dailyActiveUsers: Array<{
    date: string;
    count: number;
  }>;
  retentionData: Array<{
    userId: number;
    registrationDate: string;
    firstPrediction: string;
    daysBetween: number;
  }>;
  period: string;
}

interface UserGrowthChartProps {
  days?: number;
}

export function UserGrowthChart({ days = 30 }: UserGrowthChartProps) {
  const [selectedDays, setSelectedDays] = React.useState(days);

  const { data: growthData, isLoading } = useQuery<GrowthData>({
    queryKey: ['/api/admin/user-growth', { days: selectedDays }],
  });

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', { 
      month: 'short', 
      day: 'numeric' 
    });
  };

  if (isLoading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <TrendingUp className="h-5 w-5" />
            User Growth Chart
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="animate-pulse">
            <div className="h-64 bg-gray-200 rounded"></div>
          </div>
        </CardContent>
      </Card>
    );
  }

  if (!growthData) {
    return (
      <Card>
        <CardContent className="p-6 text-center">
          <p>Failed to load growth data</p>
        </CardContent>
      </Card>
    );
  }

  // Combine registration and activity data
  const combinedData = growthData.dailyRegistrations.map(reg => {
    const activity = growthData.dailyActiveUsers.find(act => act.date === reg.date);
    return {
      date: reg.date,
      registrations: reg.count,
      cumulative: reg.cumulative,
      activeUsers: activity?.count || 0,
      formattedDate: formatDate(reg.date)
    };
  });

  return (
    <div className="space-y-4">
      {/* Controls */}
      <div className="flex items-center justify-between">
        <h3 className="text-lg font-semibold flex items-center gap-2">
          <TrendingUp className="h-5 w-5" />
          User Growth Chart
        </h3>
        <Select value={selectedDays.toString()} onValueChange={(value) => setSelectedDays(parseInt(value))}>
          <SelectTrigger className="w-32">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="7">7 Days</SelectItem>
            <SelectItem value="14">14 Days</SelectItem>
            <SelectItem value="30">30 Days</SelectItem>
            <SelectItem value="60">60 Days</SelectItem>
            <SelectItem value="90">90 Days</SelectItem>
          </SelectContent>
        </Select>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        {/* Daily Registrations */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-base">
              <Users className="h-4 w-4" />
              Daily Registrations
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="h-64">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={combinedData}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis 
                    dataKey="formattedDate" 
                    fontSize={12}
                    tick={{ fontSize: 10 }}
                  />
                  <YAxis fontSize={12} />
                  <Tooltip 
                    labelFormatter={(label) => `Date: ${label}`}
                    formatter={(value, name) => [
                      value,
                      name === 'registrations' ? 'Registrations' : 'Cumulative'
                    ]}
                  />
                  <Area
                    type="monotone"
                    dataKey="registrations"
                    stroke="#3b82f6"
                    fill="#3b82f6"
                    fillOpacity={0.3}
                  />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          </CardContent>
        </Card>

        {/* Daily Active Users */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-base">
              <Activity className="h-4 w-4" />
              Daily Active Users
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="h-64">
              <ResponsiveContainer width="100%" height="100%">
                <LineChart data={combinedData}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis 
                    dataKey="formattedDate" 
                    fontSize={12}
                    tick={{ fontSize: 10 }}
                  />
                  <YAxis fontSize={12} />
                  <Tooltip 
                    labelFormatter={(label) => `Date: ${label}`}
                    formatter={(value) => [value, 'Active Users']}
                  />
                  <Line
                    type="monotone"
                    dataKey="activeUsers"
                    stroke="#10b981"
                    strokeWidth={2}
                    dot={{ r: 4 }}
                  />
                </LineChart>
              </ResponsiveContainer>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Cumulative Growth */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-base">
            <Calendar className="h-4 w-4" />
            Cumulative Growth
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={combinedData}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis 
                  dataKey="formattedDate" 
                  fontSize={12}
                  tick={{ fontSize: 10 }}
                />
                <YAxis fontSize={12} />
                <Tooltip 
                  labelFormatter={(label) => `Date: ${label}`}
                  formatter={(value) => [value, 'Total Users']}
                />
                <Area
                  type="monotone"
                  dataKey="cumulative"
                  stroke="#8b5cf6"
                  fill="#8b5cf6"
                  fillOpacity={0.4}
                />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </CardContent>
      </Card>

      {/* Retention Summary */}
      {growthData.retentionData.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle className="text-base">User Retention Summary</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div className="text-center">
                <div className="text-2xl font-bold text-green-600">
                  {growthData.retentionData.length}
                </div>
                <div className="text-sm text-muted-foreground">
                  Users who made predictions
                </div>
              </div>
              <div className="text-center">
                <div className="text-2xl font-bold text-blue-600">
                  {(growthData.retentionData.reduce((sum, user) => sum + user.daysBetween, 0) / growthData.retentionData.length).toFixed(1)}
                </div>
                <div className="text-sm text-muted-foreground">
                  Average days to first prediction
                </div>
              </div>
              <div className="text-center">
                <div className="text-2xl font-bold text-purple-600">
                  {((growthData.retentionData.filter(user => user.daysBetween <= 7).length / growthData.retentionData.length) * 100).toFixed(1)}%
                </div>
                <div className="text-sm text-muted-foreground">
                  7-day retention
                </div>
              </div>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

